P.entries["quest:5634"] = {n="Desperate Prayer",s="In Stormwind, preotii Human cauta o rugaciune pentru propriile clipe de nevoie. La Cathedral of Light, High Priestess Laurena ii invata pe acoliti sa cheme Holy Light atunci cand vietile lor sunt in pericol.",h="In Stormwind, preotii Human cauta o rugaciune pentru propriile clipe de nevoie.",kw={"Cathedral of Light","piata catedralei","Desperate Prayer","High Priestess Laurena","Lumina Sacra","Laurena","Priest","Stormwind"},ang={["class:Priest"]="Ca Priest, acest ritual marcheaza trecerea ta de la acolit ucenic la slujitor activ al Holy Light, pregatit sa supravietuiesti incercarilor mortale de pe campul de lupta.",["faction:Alliance"]="Ca membru al Alliance, stii ca binecuvantari precum Desperate Prayer ii ajuta pe vindecatorii din prima linie sa supravietuiasca si sa ingrijeasca soldatii de la granitele primejdioase.",["race:Human"]="Ca Human, primesti aceasta invatatura de la clerul Cathedral of Light, care confirma locul de frunte al Stormwindului ca centru al credintei Human."},sec={{t="O rugaminte in intuneric",b="Preotii din Cathedral of Light invata sa-si foloseasca credinta pentru a-si proteja tovarasii, a vindeca ranile si a lovi raul. Totusi, chiar si cei devotati pot fi izolati, incercuiti sau adusi in pragul mortii. In asemenea clipe, un acolit poate striga dupa ajutor catre Holy Light, luptandu-se pentru propria supravietuire."},{t="Binecuvantarea catedralei",b="High Priestess Laurena ii indruma pe clerici in Cathedral Square din Stormwind si hotaraste cand un acolit este pregatit pentru invataturi mai profunde. Initiatii Human care dau dovada de devotament fata de Light in tot regatul primesc aceasta lectie atat ca protectie, cat si ca indatorire de a sluji in continuare regatul."}},faq={{q="Care este scopul Desperate Prayer?",a="Desperate Prayer ii permite unui priest ranit sa ceara pe loc ajutorul Holy Light pentru a-si vindeca ranile grave, fara o incantatie lunga.",al={"ce face Desperate Prayer","de ce Desperate Prayer","scopul lui Desperate Prayer"}},{q="Cine preda aceasta lectie in Stormwind?",a="High Priestess Laurena preda aceasta lectie in Cathedral of Light, in Cathedral Square din Stormwind, dupa ce un acolit si-a dovedit devotamentul si a dobandit experienta in lumea larga.",al={"cine preda Desperate Prayer","unde gasesc Desperate Prayer","misiunea High Priestess Laurena"}},{q="De ce primesc preotii aceasta invatatura anume?",a="Priestii Holy Light isi risca viata pentru a-i ajuta pe ceilalti. Aceasta rugaciune poate ajuta la salvarea vietii unui vindecator atunci cand este singur sau grav ranit.",al={"de ce primesc preotii Desperate Prayer","povestea din spatele Desperate Prayer"}},{q="Poate orice aventurier sa invete Desperate Prayer aici?",a="Nu. Doar preotii devotati Holy Light si indrumati de Church of the Light primesc aceasta lectie.",al={"poate oricine sa invete Desperate Prayer","este aceasta misiune doar pentru Priest"}},{q="Unde are loc acest ritual?",a="Ritualul are loc in Cathedral of Light, in cartierul de nord din Stormwind City.",al={"locatia Desperate Prayer","unde se afla Laurena"}},{q="Este Desperate Prayer rezervata preotilor umani?",a="Atat clericii Human, cat si cei Dwarven din tinuturile Alliance pot folosi Desperate Prayer, datorita traditiilor lor strans inrudite de venerare a Holy Light in Stormwind si Ironforge.",al={"primesc si alte rase Desperate Prayer","Desperate Prayer pentru Dwarf"}}},fp="16,192,18.289.0,24.275.0,40.128.0,36.170.0,46.138.0,47.101.0,32.91.0,44.177.0"}
P.entries["quest:5635"] = {n="Desperate Prayer",s="Preotii promitatori din Elwynn Forest sunt chemati la Stormwind pentru instruire suplimentara in cadrul Church of the Holy Light. Dupa ce isi dovedesc devotiunea si disciplina, se infatiseaza in fata lui High Priestess Laurena, la Cathedral of Light.",h="Preotii promitatori din Elwynn Forest sunt chemati la Stormwind pentru instruire suplimentara in cadrul...",kw={"cathedral of light","desperate prayer","goldshire","high priestess laurena","lumina sacra","priest","priestess josetta","stormwind"},ang={["class:Priest"]="Ca preot, treci de la slujirea de novice din Goldshire la pregatirea sub indrumarea conducerii superioare a Cathedral of Light.",["faction:Alliance"]="Ca membru al Alliance, faci parte dintr-un popor unit, in parte, de Church of the Holy Light, unul dintre cei mai puternici piloni culturali si morali ai sai in fata amenintarilor iminente.",["race:Human"]="Ca human care urmeaza Holy Light, intrarea in Cathedral of Light iti reafirma datoria fata de inima spirituala a regatului."},sec={{t="O chemare in capitala",b="Priestess Josetta ii indruma pe preotii novici din Goldshire, in timp ce alti mentori locali slujesc asezarile indepartate din Elwynn Forest. Cand un discipol dovedeste ca este capabil prin spirit si fapte, vestea ajunge la conducerea clerului din Stormwind. Chemarea la Cathedral of Light marcheaza trecerea la responsabilitati mai mari in credinta si la instruirea oficiala in inima spirituala a Kingdom of Stormwind."},{t="Indrumarea Inaltei Preotese",b="La Cathedral, acolitii se infatiseaza inaintea lui High Priestess Laurena, una dintre conducatoarele de seama ale Bisericii din Stormwind. Ea le supravegheaza pregatirea spirituala si instruirea practica pe masura ce devin priests. Indrumarile sale ii pregatesc pentru incercarile grele cu care se confrunta Alliance si ii invata miracolele Light, inclusiv Desperate Prayer, rugaciunea pentru izbavire cunoscuta printre practicantii Human."}},faq={{q="Care este scopul misiunii Desperate Prayer?",a="Desperate Prayer trimite preotii promitatori din Goldshire la Cathedral of Light din Stormwind, pentru instruire suplimentara sub indrumarea lui High Priestess Laurena.",al={"misiunea desperate prayer","ce este misiunea desperate prayer","de ce sa faci desperate prayer"}},{q="Cine ofera misiunea Desperate Prayer?",a="Priestess Josetta, instructorul de priest de la Lion's Pride Inn din Goldshire, iti da chemarea dupa ce iti dovedesti devotiunea.",al={"cine incepe Desperate Prayer","cel care ofera misiunea Desperate Prayer"}},{q="Cine este High Priestess Laurena?",a="High Priestess Laurena este o conducatoare cu rang inalt a Church of the Holy Light, care instruieste acolitii in Cathedral of Light din Stormwind.",al={"cine este Laurena","povestea High Priestess Laurena"}},{q="Unde se afla Cathedral of Light?",a="Cathedral of Light se afla in Cathedral Square, in cartierul de nord al Stormwind City. Este centrul spiritual al preotilor si paladinilor regatului.",al={"unde este Cathedral of Light","locatia catedralei din Stormwind"}},{q="De ce se numeste misiunea Desperate Prayer?",a="Preotii Human invata Desperate Prayer ca pe o rugaminte adresata Light-ului pentru izbavire imediata, menita sa le salveze viata, in timpul pregatirii lor avansate din Stormwind.",al={"de ce se numeste Desperate Prayer","semnificatia numelui desperate prayer"}},{q="Primesc aceasta misiune si alte rase sau clase?",a="Aceasta instruire este pentru priest care avanseaza din Elwynn Forest si incep pregatirea superioara in Stormwind.",al={"pot Dwarves sa faca misiunea Desperate Prayer","este Desperate Prayer doar pentru Priest"}}},fx={["24d97f9e"]={q="De ce vrea Priestess Josetta sa vizitezi Cathedral of Light?",a="Priestess Josetta actioneaza la ordinele ierarhiei Bisericii. Ti-ai dovedit devotamentul si priceperea pe teren, atragand atentia superiorilor Bisericii din Stormwind. Rolul lui Josetta este sa-i indrume pe acolitii promitatori catre mentori de rang superior, asa ca te trimite la Cathedral of Light pentru a primi invataturi mai avansate despre caile Light.",al={"de ce te trimite josetta","motivul lui priestess josetta","de ce sa vizitezi preotul din stormwind"}}},fp="16,228,24.392.0,32.399.0,50.140.0,37.128.0,30.132.0,40.157.0,40.147.0,41.99.0"}
P.entries["quest:5636"] = {n="Desperate Prayer"}
P.entries["quest:5637"] = {n="Desperate Prayer",s="In Stormwind, preotii Dwarf sunt chemati sa-si aprofundeze slujirea lui Light. High Priestess Laurena ii convoaca la Cathedral of Light pe acolitii promitatori din Dun Morogh. Acolo isi asuma indatoriri mai ample in randul Alliance.",h="In Stormwind, preotii Dwarf sunt chemati sa-si aprofundeze slujirea lui Light.",kw={"Cathedral of Light","Desperate Prayer","Dun Morogh","Kharanos","Laurena","Maxan Anvol","Priest","Stormwind"},ang={["class:Priest"]="Ca Priest, treci de la indatoririle de baza din parohia ta la tehnici sfinte avansate, predate de conducatorii Bisericii.",["faction:Alliance"]="Ca membru al Alliance, impartasesti Light cu adepti din Ironforge si Stormwind, uniti dincolo de granitele rasiale.",["race:Dwarf"]="Ca Dwarf, calatoria ta la Cathedral of Light din Stormwind intareste legatura spirituala dintre Ironforge si regatul Human al Stormwind."},sec={{t="O chemare la catedrala",b="Preotii dwarf instruiti in Dun Morogh pot depasi lectiile indrumatorilor locali precum Maxan Anvol din Kharanos. Cand un acolit da dovada de talent, High Priestess Laurena ii trimite o convocare oficiala de la Cathedral of Light. Atentia ei inseamna ca tanarul Priest este pregatit pentru studii mai aprofundate si indatoriri mai mari in credinta."},{t="Legaturi intre regate",b="Ironforge isi pastreaza propriile traditii sacre in Mystic Ward, in timp ce Church of the Holy Light din Stormwind ii intampina deopotriva pe humans si dwarves. Calatoria spre sud cu Deeprun Tram ii aduce pe acolitii dwarven in sanul comunitatii mai largi a bisericii si intareste legatura spirituala dintre regatele aliate."}},faq={{q="De ce ii cheama High Priestess Laurena pe preotii pitici la Stormwind?",a="High Priestess Laurena ii cheama pe acolitii promitatori sa-si continue pregatirea religioasa la Cathedral of Light. Invatatorii locali, precum Maxan Anvol, ii trimit acolo dupa ce au deprins principiile de baza, ca sa invete tehnici avansate precum Desperate Prayer.",al={"de ce ma cheama Laurena","de ce sa merg la preotul din Stormwind","cine este High Priestess Laurena"}},{q="Ce este Desperate Prayer in istorie?",a="Desperate Prayer este o invocare urgenta a Holy Light, practicata de clericii Human si dwarven. Cand un priest este aproape de moarte, un strigat brusc de credinta inchide ranile si ii reda vitalitatea.",al={"povestea lui desperate prayer","ce este desperate prayer","cum functioneaza desperate prayer"}},{q="Unde are loc aceasta misiune?",a="Iti incepi calatoria in Kharanos, in Dun Morogh, unde te invata Maxan Anvol. De acolo, calatoresti la Stormwind City si la Cathedral of Light din Cathedral Square, unde conduce High Priestess Laurena.",al={"locatia misiunii","unde trebuie sa merg","unde este Laurena"}},{q="De ce s-ar instrui un priest dwarf sub indrumarea unei High Priestess human?",a="Dwarves si Humans impartasesc credinta in Holy Light, o legatura intarita in timpul Second War. Preotii Dwarven slujesc adesea in Mystic Ward din Ironforge, in timp ce Cathedral of Light din Stormwind ii primeste pe practicantii din toata Alliance.",al={"de ce antreneaza un Human un Dwarf","Dwarf si Biserica Luminii","Lumina din Ironforge si Stormwind"}},{q="Cum ar trebui sa ajunga un tanar calator din Dun Morogh la Stormwind?",a="Treci prin Tinker Town din Ironforge si ia Deeprun Tram pe sub munti pana in Dwarven District din Stormwind.",al={"cum ajung la Stormwind","calatorie la Stormwind ca pitic","Deeprun Tram"}},{q="Cine este Maxan Anvol?",a="Maxan Anvol este un instructor dwarven de preoti in Kharanos, Dun Morogh. El ii invata pe tinerii clerici notiunile de baza pana cand sunt pregatiti sa studieze cu liderii superiori ai bisericii din Stormwind.",al={"povestea lui Maxan Anvol","cine a dat misiunea","antrenorul Priest din Kharanos"}}},fx={["9ecbae4a"]={q="De ce te trimite Maxan Anvol la Stormwind?",a="Maxan Anvol este indrumatorul tau local din Kharanos, dar stie sa recunoasca momentul in care un tanar acolit a depasit lectiile modeste ale unui avanpost inzapezit. A aflat ca High Priestess Laurena insasi te-a chemat la Cathedral of Light. Maxan vrea sa se asigure ca nu-ti irosesti potentialul - fie ca aceasta chemare aduce vesti sumbre, fie o mare oportunitate, pentru a-ti desavarsi puterea Light trebuie sa inveti de la cei mai de seama conducatori ai Bisericii din capitala oamenilor.",al={"de ce te trimite Maxan","motivul lui Maxan Anvol","de ce sa mergi la Stormwind pentru misiunea preotului"}},["12c7ba04"]={q="De ce te trimite Maxan Anvol in loc sa mearga el insusi?",a="Chemarea nu este o insarcinare sau un mesaj diplomatic oficial; High Priestess Laurena te-a chemat anume pe nume. Maxan crede ca devotamentul si progresul pe care le-ai dovedit au atras atentia Catedralei. In plus, Maxan trebuie sa ramana in Kharanos pentru a sluji comunitatea locala de pitici si a-i indruma pe novicii neincercati care fac primii pasi in credinta.",al={"de ce eu pentru desperate prayer","de ce nu merge maxan la stormwind"}}},fp="16,223,26.310.0,21.291.0,67.260.0,37.181.0,33.195.0,60.234.0,60.119.0,19.177.0"}
P.entries["quest:5638"] = {n="Desperate Prayer",s="In Stormwind, o convocare duce un priest tanar din Park la Cathedral of Light. Nara Meideros te trimite la High Priestess Laurena pentru instructiuni suplimentare.",h="In Stormwind, o convocare duce un priest tanar din Park la Cathedral of Light.",kw={"cathedral of light","desperate prayer","high priestess laurena","holy light","nara meideros","misiune priest","stormwind","the park"},ang={["class:Priest"]="Ca priest, aceasta chemare marcheaza intrarea ta in discipline spirituale superioare si iti deschide calea spre invatarea rugaciunii Desperate Prayer, o invocatie care poate salva vieti.",["faction:Alliance"]="Ca membru al Alliance, poti observa solidaritatea tacuta dintre Darnassus si ordinele sfinte din Stormwind, reflectata in colaborarea dintre Nara Meideros si clericii Cathedral.",["race:Human"]="Ca human, Cathedral of Light este principalul sanctuar al credintei human in sudul Eastern Kingdoms. Indrumarea lui Laurena marcheaza un pas spiritual important."},sec={{t="O vorba in parc",b="In Park din Stormwind, Nara Meideros isi pastreaza credinta in Elune. Indrumatorii spirituali ai orasului au legaturi intre ei, in ciuda traditiilor diferite. Cand Cathedral cauta un student promitator, Nara te trimite peste canale cu o incurajare discreta. Mesajul aduce vesti bune, nu e motiv de ingrijorare."},{t="Chemarea catedralei",b="La Cathedral of Light, in Cathedral Square, te prezinti in fata lui High Priestess Laurena. Una dintre conducatoarele clericale de rang inalt din Stormwind, ea indruma tinerii acolytes dincolo de primele lor rugaciuni. Laurena ii invata invocatia sacra numita Desperate Prayer, o rugaminte personala pentru ajutor divin. Aceasta poate vindeca rani grave intr-o clipa, atunci cand un slujitor al Light se afla aproape de moarte."}},faq={{q="Cine ma trimite in aceasta misiune?",a="Priestess Nara Meideros, o clerica night elf din Park, in Stormwind, iti trimite vorba ca liderii Catedralei te cauta.",al={"cel care ofera misiunea","cine ofera Desperate Prayer","nara meideros"}},{q="Cui trebuie sa-i raportez in Stormwind?",a="Prezinta-te la High Priestess Laurena in Cathedral of Light, in Cathedral Square din Stormwind.",al={"unde sa merg","predarea misiunii","cine este laurena"}},{q="Care este semnificatia misiunii Desperate Prayer?",a="Desperate Prayer este o invocatie care cheama harul divin pentru a-si vindeca pe loc invocatorul in momente de primejdie extrema. Este predata clericilor Human si Dwarven ai Holy Light.",al={"ce face Desperate Prayer","lore despre vraja Priest","vraja Desperate Prayer"}},{q="De ce indruma o Night Elf preotii catre catedrala Humanilor?",a="Preotesele night elf se inchina lui Elune, in timp ce oamenii si piticii urmeaza Holy Light. Ordinele spirituale din Stormwind pastreaza legaturi stranse si respect reciproc si isi impartasesc vestile cand clericii din Alliance au nevoie de instruire.",al={"de ce nara meideros","parc pana la catedrala","elf de noapte elune stormwind"}},{q="In ce etapa a antrenamentului are loc aceasta chemare?",a="Chemarea vine de obicei pe la al zecelea cerc de experienta, cand un tanar Priest si-a dovedit priceperea pe teren si poate indeplini ritualuri divine mai solicitante.",al={"ce nivel are","cand primesc Desperate Prayer"}},{q="Unde se afla Cathedral of Light?",a="Cathedral of Light domina Cathedral Square, in nordul Stormwind City, intre Dwarven District si Park.",al={"locatia catedralei","unde se afla piata catedralei"}}},fx={["8a572a98"]={q="De ce vrea Nara Meideros sa vizitez Cathedral of Light?",a="Nara Meideros nu are niciun interes personal sau vreo nemultumire; doar ii face o favoare unui preot din acelasi ordin cu tine. Un preot a venit in Park anume ca sa te gaseasca si i-a cerut Narei sa-ti transmita mesajul cand va intalniti. Observand firea vesela si optimista a mesagerului, ea iti da de stire, linistindu-te cu gandul ca sub indrumarea lui High Priestess Laurena te asteapta vesti bune si un progres important.",al={"de ce ma trimite Nara","motivul lui Nara Meideros","de ce sa merg la Cathedral of Light"}},e569a4a2={q="De ce ma convoaca tocmai High Priestess Laurena?",a="Ca preot aspirant al Holy Light, care si-a dovedit valoarea in primele aventuri, mentorul tau recunoaste ca legatura ta spirituala s-a maturizat. Laurena iti cere prezenta personala, deoarece misterele mai profunde si responsabilitatile preotiei nu pot fi delegate sau predate prin intermediari. Ea a pregatit lectii esentiale, directe, despre credinta ta, care iti vor spori darurile sacre si iti vor oferi maiestria necesara pentru a-ti proteja aliatii.",al={"de ce eu, Desperate Prayer","de ce ma vrea Laurena","de ce sa ma cheme la catedrala"}}},fp="16,162,18.295.0,25.368.0,27.122.0,40.97.0,45.179.0,60.206.0,50.145.0,40.120.0"}
P.entries["quest:5639"] = {n="Desperate Prayer"}
P.entries["quest:564"] = {n="Costly Menace",s="Darren Malvew din Southshore uraste sa piarda caii frumosi ai orasului. Undead, banda Syndicate si tot felul de ticalosi au pricinuit destule pierderi, dar Darren spune ca nimic nu ii ameninta mai mult decat leii de munte care tot coboara de pe dealurile din Alterac.",h="Darren Malvew din Southshore uraste sa piarda caii frumosi ai orasului.",kw={"muntii Alterac","Costly Menace","Darren Malvew","dealurile Hillsbrad","cai","leu de munte masiv","leu de munte","Southshore"},sec={{t="Cai pierduti",b="Darren Malvew din Southshore nu suporta sa piarda frumosii cai de acolo. Destul de multi au fost pierduti din cauza creaturilor strigoi, a bandei Syndicate si a ticalosilor care dau tarcoale prin regiune. Totusi, dupa cum spune chiar Darren, nicio amenintare la adresa cailor nu e mai mare decat pumele de munte din Alterac, care coboara necontenit de pe dealuri."},{t="Leii dealurilor",b="Darren vrea sa scape de lei: opt Mountain Lions si zece Hulking Mountain Lions. Mountain Lions se gasesc pe dealurile joase din Alterac Mountains."}},faq={{q="Cine este Darren Malvew?",a="Darren Malvew este din Southshore, in Hillsbrad Foothills, si s-a saturat sa piarda caii orasului.",al={"darren malvew","cine da costly menace","darren malvew si caii din southshore"}},{q="De unde vin leii de munte?",a="Ei coboara din dealurile Alterac. Mountain Lions se gasesc pe versantii inferiori ai Alterac Mountains.",al={"locatia leului de munte","unde sunt leii de munte","unde gasesc lei"}},{q="Ce pericole pentru cai mentioneaza Darren?",a="Undead ratacitori, banda Syndicate si alti nemernici din regiune au lasat Southshore fara cai, dar Darren spune ca leii de munte din Alterac sunt cea mai mare amenintare dintre toate.",al={"amenintari pentru southshore","ce ataca caii din southshore","dusmanii lui darren malvew"}},{q="Ce bestii anume trebuie eliminate?",a="Opt lei de munte si zece lei de munte masivi.",al={"ce lei sa ucid","leu de munte masiv, Costly Menace","tinte pentru Costly Menace"}}},fp="13,255,11.322.0,18.157.0,21.99.0,41.111.0,47.174.0,39.52.0"}
