P.entries["quest:5643"] = {n="Shadowguard"}
P.entries["quest:5644"] = {n="Devouring Plague",s="Devouring Plague este o misiune de initiere pentru preotii Forsaken care calatoresc departe de Lordaeron. Indrumat de Miles Welsh, instructorul preot Forsaken din Thunder Bluff, adeptul este trimis inapoi peste mari, la Aelthalyste din Undercity, pentru a debloca o manifestare specifica a magiei umbrelor.",h="Devouring Plague este o misiune de initiere pentru preotii Forsaken care calatoresc departe de Lordaeron.",kw={"Aelthalyste","Devouring Plague","forsaken","Miles Welsh","preot al Umbrei","Thunder Bluff","Undercity","War Quarter"},ang={["class:Priest"]="Aceasta misiune marcheaza o etapa importanta in educatia unui preot Forsaken, trecerea de la principiile de baza la traditiile terifiante ale umbrelor, specifice strigoilor.",["faction:Horde"]="Aceasta misiune ilustreaza legaturile logistice si spirituale care unesc avanposturile indepartate ale Horde din Mulgore cu inima intunecata a Undercity.",["race:Undead"]="Spre deosebire de Light pe care o urmau in viata, preotii Forsaken imbratiseaza suferinte cumplite si magia Shadow, precum Devouring Plague."},sec={{t="O chemare acasa",b="In timpul vizitei in Thunder Bluff, preotii Forsaken care si-au desavarsit stapanirea disciplinelor divine si ale umbrei sunt evaluati de Miles Welsh, un preot Forsaken stationat printre tauren. Vazand ca un acolit a dobandit destula putere, Miles ii cere sa se intoarca la Ruins of Lordaeron, in loc sa incerce sa-i transmita el insusi aceste taine superioare in Kalimdor."},{t="Secretele lui Aelthalyste",b="Sub ruinele orasului, in War Quarter din Undercity, o asteapta Aelthalyste, una dintre cele mai de seama indrumatoare ale preotimii Forsaken. Ea vegheaza asupra formarii acolitilor care tes umbre, asigurandu-se ca blestemul puternic si mistuitor numit Devouring Plague este incredintat doar celor capabili sa-i stapaneasca forta corupatoare fara sa-i cada prada."}},faq={{q="Cine te trimite in aceasta misiune?",a="Miles Welsh, un instructor Forsaken de preoti, aflat la Pools of Vision, sub Spirit Rise, in Thunder Bluff, te trimite in aceasta calatorie dupa ce ti-ai dezvoltat suficient abilitatile.",al={"cine da misiunea Devouring Plague","cine ofera misiunea Devouring Plague","rolul lui Miles Welsh"}},{q="Unde se afla Aelthalyste?",a="Aelthalyste locuieste in War Quarter din Undercity, printre arenele de antrenament si canalele intunecate unde se aduna preotii Forsaken.",al={"locatia lui aelthalyste","unde se afla aelthalyste","predarea devouring plague"}},{q="De ce nu poate Miles Welsh sa predea el insusi vraja?",a="Vraja in sine nu este un secret: toti preotii invata Devouring Plague de la un antrenor de preoti, la nivelul 20. Insa Welsh respecta ierarhia preotimii Forsaken si ii trimite pe acolitii vrednici inapoi acasa, unde mentori maestri precum Aelthalyste ii pot pune la incercare in inima Undercity.",al={"de ce sa calatoresti la Undercity","de ce sa o vezi pe Aelthalyste","instructor de preoti din Undercity"}},{q="Ce este Devouring Plague din perspectiva lore-ului?",a="Este un blestem devastator practicat de preotii Forsaken, care napastuieste victima cu o afectiune magica virulenta, consumandu-i vigoarea pentru a o reda celui care l-a lansat.",al={"ce este Devouring Plague","povestea despre Devouring Plague","vraja bolii Forsaken"}},{q="Este aceasta misiune disponibila si pentru alte rase?",a="Nu. Aceasta chemare este pentru preotii Forsaken, desi orice preot, indiferent de rasa, invata Devouring Plague de la un antrenor de preoti la nivelul 20.",al={"pot Trolls sa faca misiunea Devouring Plague","pot Orcs sa faca Devouring Plague","este aceasta misiune doar pentru Undead"}},{q="De ce se afla un antrenor Forsaken in Thunder Bluff?",a="Dupa admiterea Forsaken in Horde, diplomati si mentori au fost trimisi intre capitale. Preoti precum Miles Welsh reprezinta traditiile spirituale din Undercity si ii indruma pe Forsaken care calatoresc prin Kalimdor.",al={"de ce sunt forsaken in thunder bluff","lore despre forsaken in thunder bluff","miles welsh thunder bluff"}}},fx={ec2983f6={q="De ce te trimite Miles Welsh la Undercity?",a="Miles Welsh isi da seama ca intelegerea ta asupra preotiei a depasit nivelul pe care il poate oferi instruirea de baza din strainatate. Ca reprezentant stationat printre tauren, datoria sa este sa recunoasca momentul in care un preot Forsaken promitator este pregatit pentru taine mai adanci. In loc sa te tina pe loc, te trimite acasa, la Aelthalyste, pentru a fi initiat in invataturile mai intunecate ale preotiei Forsaken.",al={"de ce vrea miles welsh sa se faca asta","motivul lui miles welsh","de ce sa mergi in undercity"}},["988f0d1b"]={q="De ce are Miles Welsh nevoie sa mergi tu, in loc sa livreze el insusi mesajul?",a="Miles Welsh este un trimis si indrumator al vizitatorilor Forsaken de pe platourile inalte din Thunder Bluff; functia lui il obliga sa ramana pe faleza pentru a-si instrui si reprezenta poporul. Mai important, calatoria tine de inaltarea ta personala. Marea preoteasa din Undercity iti cere sa te infatisezi in persoana, pentru a-ti putea judeca pe loc evolutia spirituala inainte de a-ti impartasi invataturile ei letale.",al={"de ce eu","de ce sa ma trimita","de ce are miles nevoie de mine"}}},fp="16,291,14.368.0,26.361.0,28.184.0,29.139.0,46.266.0,49.165.0,39.149.0,62.235.0"}
