P.entries["quest:573"] = {n="Mok'thardin's Enchantment",s="Far Seer Mok'thardin are nevoie de o ultima componenta sacra pentru a incheia vraja unui colier ceremonial la Grom'gol Base Camp. Te indruma spre un Izvor Sacru aflat la inaltime, de-a lungul falezelor sudice, in apropierea marii din vest, care a atras atentia unei expeditii naga ostile.",h="Far Seer Mok'thardin are nevoie de o ultima componenta sacra pentru a incheia vraja unui colier ceremonial la...",kw={"colier ceremonial","grom'gol","izvor sacru","apa din izvorul sacru","mok'thardin","explorator naga","stranglethorn"},ang={["faction:Horde"]="Far Seer Mok'thardin le cere campionilor Horde sa ajute la terminarea unui colier ceremonial menit sa-l onoreze pe Warchief si sa protejeze Horde."},sec={{t="Un izvor disputat",b="Dupa primele etape ale vrajii lui Mok'thardin, far seer-ul cauta apa dintr-un izvor sfant aflat sus, deasupra falezelor din tinuturile sudice ale lui Stranglethorn Vale, aproape de coasta vestica. Locul starneste controverse printre invatatii in tainele misticismului si divinitatii, fiecare rasa din Azeroth sustinand ca apele sfinte au fost binecuvantate anume pentru poporul ei."},{t="Incursiunea Naga",b="Un grup de explorare naga s-a mutat langa izvor si trebuie eliminat la randul sau. Mok'thardin cere sa omori zece dintre acesti intrusi serpentiniformi si sa aduci o doza din apa izvorului, pentru a termina pregatirea colierului ceremonial in numele lui Warchief."}},faq={{q="Unde se afla Holy Spring?",a="Izvorul Sacru se afla sus, pe culmile stancoase de-a lungul coastei vestice, in regiunea sudica din Stranglethorn Vale.",al={"locatia Holy Spring","unde se afla apa din Holy Spring","stancile Holy Spring"}},{q="De ce este considerat Holy Spring important?",a="Carturarii religiosi si mistici se cearta aprig in privinta izvorului, deoarece fiecare rasa din Azeroth sustine ca apele sale divine au fost sfintite anume pentru ea.",al={"de ce este sfant izvorul","importanta izvorului sfant"}},{q="Cine revendica Izvorul Sfintit?",a="O expeditie de exploratori naga a avansat pe stancile din jurul Izvorului Sacru, amenintand zona.",al={"cine ataca izvorul","dusmanii izvorului sacru"}},{q="La ce este folosita apa?",a="Apa este ultimul reactiv de care are nevoie Far Seer Mok'thardin pentru a pregati si vraji un colier ceremonial in apararea Horde.",al={"de ce este nevoie de apa sfanta de izvor","scopul apei sfinte de izvor"}}},fp="25,280,18.386.0,18.253.0,33.112.0,44.162.0,34.108.0,33.138.0"}
P.entries["quest:5730"] = {n="Hidden Enemies"}
P.entries["quest:574"] = {n="Special Forces",s="Dupa ce ai redus numarul soldatilor de rand ai colonelului rebel, Sergeant Yohwa iti cere sa te ocupi de nucleul de elita al complexului. Esti trimis in pestera Depozitului ca sa-i elimini pe comando si pe scalpatorii de capete, apoi sa te prezinti la Lieutenant Doren.",h="Dupa ce ai redus numarul soldatilor de rand ai colonelului rebel, Sergeant Yohwa iti cere sa te ocupi de...",kw={"kurzen commando","tabara lui kurzen","kurzen headshrinker","lieutenant doren","rebel camp","sergeant yohwa","special forces","rezerva"},sec={{t="Atacarea depozitului",b="Dupa ce fortele obisnuite din Kurzen Compound au fost imputinate de actiunile din Second Rebellion, Sergeant Yohwa isi indreapta atentia spre specialistii de elita ai colonelului. Cunoaste personal multi dintre soldatii lui Kurzen si ii numeste priceputi, loiali si cruzi. Cand nu se afla in salbaticie, masacrand soldatii rebeli, ii gasesti intr-o pestera din spatele complexului, numita Stockpile. Pentru a le zdrobi puterea, esti trimis in caverna sa-i elimini pe zece Kurzen Commandos si sase Kurzen Headshrinkers."},{t="Raportare catre comandament",b="Dupa lupta, Sergeant Yohwa iti spune sa te prezinti superiorului ei, Lieutenant Doren, la Rebel Camp; acesta va dori sa-ti auda personal relatarea."}},faq={{q="Cine ordona atacul asupra trupelor de elita ale lui Kurzen?",a="Sergeant Yohwa din Rebel Camp, in nordul Stranglethorn Vale, iti cere sa pornesti acest atac dupa ce ai ajutat la rarirea infanteriei obisnuite a lui Kurzen.",al={"cine ofera special forces","cel care da misiunea special forces","unde incepe special forces"}},{q="Unde se afla comando-urile si ciopartitorii lui Kurzen?",a="Se gasesc intr-o pestera din fundul Kurzen Compound, numita Depozitul, desi ies si in salbaticie ca sa vaneze rebeli.",al={"unde sunt headshrinkers","unde este depozitul","locatia komandosului kurzen"}},{q="Cui raportezi dupa ce cureti pestera?",a="Ii prezinti raportul direct Lieutenant Doren, ofiterului comandant aflat la Rebel Camp.",al={"cui sa predau","unde se afla Doren","cine incheie Special Forces"}},{q="Ce precede acest asalt din campania rebelilor?",a="Aceasta misiune urmeaza dupa The Second Rebellion, in care slabesti trupele regulate ale lui Colonel Kurzen din toata tabara.",al={"cerinte preliminare pentru Special Forces","ce misiune preceda Special Forces"}}},fp="14,256,22.515.0,20.153.0,47.152.0,55.144.0,46.106.0,53.118.0"}
P.entries["quest:5741"] = {n="Sceptre of Light",s="Azore Aldamort a auzit ca Burning Blade din Thunder Axe Fortress, aflata la est, detine acum Sceptre of Light, despre care se spune ca a fost obtinut de la naga. Legenda spune ca acesta ar putea scufunda orase intregi sub marile intinderi ale oceanului, iar Azore nu va lasa Burning Blade sa pastreze o asemenea putere. Ti se cere sa-l aduci inapoi la Ethel Rethor.",h="Azore Aldamort a auzit ca Burning Blade din Thunder Axe Fortress, aflata la est, detine acum Sceptre of...",kw={"azore aldamort","burning blade","desolace","ethel rethor","naga","sceptre of light","vizionar","thunder axe fortress"},sec={{t="Un sceptru al Naga",b="Se spune ca Sceptre of Light al naga a ajuns in mainile Burning Blade de la Thunder Axe Fortress. Legenda spune ca poate scufunda orase intregi sub marile intinderi de ape. Azore Aldamort sustine ca Burning Blade nu poate fi lasata sa detina o asemenea putere."},{t="Turnul clarvazatorului",b="Un vizionar Burning Blade pastreaza sceptrul si il studiaza din varful unuia dintre turnurile de straja ale fortaretei. Azore vrea sa-l iei chiar tu de acolo si sa-l duci inapoi la turnul din Ethel Rethor."}},faq={{q="Ce puteri are Sceptre of Light?",a="Legenda spune ca poate scufunda orase intregi sub marile intinderi ale oceanului. Se zice ca naga l-au adus la Burning Blade.",al={"ce face sceptrul luminii","povestea sceptrului luminii","cat de puternic este sceptrul luminii"}},{q="Cine detine in prezent Sceptre of Light?",a="Un clarvazator din Burning Blade il pastreaza intr-unul dintre turnurile de veghe din Thunder Axe Fortress si il studiaza acolo.",al={"cine are sceptre of light","unde este sceptre of light","cine lasa sceptre of light"}},{q="Cine cere Sceptrul Luminii?",a="Azore Aldamort, din turnul de la Ethel Rethor.",al={"cine ofera Sceptre of Light","de unde iei Sceptre of Light"}},{q="Cum a obtinut Burning Blade sceptrul?",a="Se spune ca au obtinut-o de la naga.",al={"cum a obtinut Burning Blade sceptrul","legatura dintre Burning Blade si naga"}}},fp="16,330,21.249.0,16.197.0,45.117.0,41.106.0,34.45.0,42.44.0"}
P.entries["quest:575"] = {n="Supply and Demand",s="Drizzlik, un tabacar din Booty Bay, pretinde ca este cel mai bun din South Seas. Director Riddlevox din Tinkers' Union a comandat douasprezece perechi de cizme Excelsior-line, iar Drizzlik are nevoie de piei de la crocolisci din raul nordic Stranglethorn ca sa inceapa sa le confectioneze.",h="Drizzlik, un tabacar din Booty Bay, pretinde ca este cel mai bun din South Seas.",kw={"booty bay","crocolisk","drizzlik","excelsior","pielarie","riddlevox","stranglethorn","uniunea tinkers"},sec={{t="Un ordin al Tinkers' Union",b="Drizzlik se lauda ca obiectele din piele pe care le face sunt renumite pretutindeni pentru rafinamentul lor si preferate de cunoscatori. Cea mai recenta comanda vine de la Director Riddlevox, inventatorul-sef al Tinkers' Union, care vrea o duzina de cizme Excelsior-line, printre cele mai bine vandute ale lui Drizzlik si preferatele sale. Ca sa inceapa sa le confectioneze, Drizzlik are nevoie de pieile crocoliscurilor de langa raul din nordul Stranglethorn. Echipamentul este pregatit, iar sa nemultumesti un client atat de important ar fi o idee proasta."},{t="Odata ce sosesc pieile",b="Drizzlik considera ca pieile sunt suficient de bune. Calitatea lor conteaza prea putin, fiindca vor forma stratul interior al cizmelor, desi trebuie sa fie totusi comode. Pieile care se dovedesc prea rigide pot fi inmuiate cu sange de tigru, unul dintre trucurile meseriei."}},faq={{q="Cine este Drizzlik?",a="Drizzlik este un tabacar din Booty Bay, care se lauda ca este cel mai bun din South Seas si chiar din tinuturile de dincolo.",al={"drizzlik booty bay","tabacar din booty bay"}},{q="Cine a comandat cizmele Excelsior?",a="Director Riddlevox, inventatorul-sef al Tinkers' Union, a comandat doisprezece bocanci Excelsior-line.",al={"cine a comandat cizmele","director riddlevox","comanda Uniunii Tinkers"}},{q="Unde se gasesc crocoliscii cautati in cadrul acestei comenzi?",a="Drizzlik indica raul din nordul Stranglethorn, unde traiesc crocolisks.",al={"locatia crocoliscului","unde sunt crocodilii de rau","unde gasesc pieile"}},{q="Cate piei vrea Drizzlik?",a="Doua piei mari de crocolisc de rau.",al={"cate piei de crocolisk","piele de crocolisk mare de rau"}}},fp="17,277,32.466.0,21.254.1,16.102.0,32.93.0,51.79.0,34.32.0"}
P.entries["quest:576"] = {n="Keep An Eye Out",s="In Booty Bay, batranul lup de mare Dizzy One-Eye si-a pierdut vederea in lupta si nu vede decat printr-un ochi de sticla vrajit. Bloodsail Buccaneers l-au atacat aseara si i l-au luat, iar Dizzy cere ajutor ca sa-si recupereze ochiul.",h="In Booty Bay, batranul lup de mare Dizzy One-Eye si-a pierdut vederea in lupta si nu vede decat printr-un...",kw={"Bloodsail","Booty Bay","bucanieri","Dizzy","ochi de sticla","Menethil","One-Eye","Stranglethorn"},sec={{t="Ochiul fermecat",b="Dizzy One-Eye si-a pierdut ambii ochi in lupta. Din fericire, corabia lui Dizzy a acostat la Menethil, unde un vrajitor calator i-a facut un ochi de sticla vrajit, special, care i-a redat vederea. Fara el, Dizzy se simte inutil si isi aminteste ca odinioara cuibul de cioara ii era casa."},{t="Luati de bucanieri",b="Aseara, Bloodsail Buccaneers l-au atacat pe Dizzy cand pleca si i-au luat ochiul. Se pare ca Bloodsails au ajuns in Booty Bay. Dizzy se teme ca, atunci cand se va afla ce s-a intamplat cu ochiul, capitanul il va trage pe chila si crede ca un veghetor care nu poate vedea ar fi bun doar la frecat santina. Asa ca Dizzy iti cere ajutorul pentru a recupera ochiul de la Bloodsail Buccaneers."}},faq={{q="Cine este Dizzy One-Eye?",a="Dizzy One-Eye este un lup de mare batran din Booty Bay, care a lucrat ca observator. Dizzy si-a pierdut ambii ochi in lupta si vede doar printr-un ochi de sticla fermecat.",al={"dizzy one eye","cine ofera Keep an Eye Out","cine este dizzy"}},{q="De unde a luat Dizzy ochiul magic?",a="Nava lui Dizzy a acostat la Menethil, unde un vrajitor aflat in trecere a creat un ochi de sticla fermecat, care i-a redat vederea lui Dizzy.",al={"cum si-a pierdut Dizzy ochiul","originea ochiului fermecat al lui Dizzy","ochi de sticla vrajitor"}},{q="Cine i-a luat ochiul lui Dizzy?",a="Bloodsail Buccaneers l-au atacat pe Dizzy aseara, cand pleca, si au luat ochiul.",al={"cine a furat ochiul","cine i-a luat ochiul lui Dizzy","cine are ochiul lui Dizzy"}},{q="De ce se teme Dizzy ca se va intampla fara ochi?",a="Dizzy se teme ca capitanul il va pedepsi cu chila pentru asta si crede ca un observator care nu poate vedea nu e bun decat la frecat santina.",al={"ce se intampla daca Dizzy isi pierde ochiul","pedeapsa capitanului Dizzy"}}},fp="15,225,17.259.0,23.370.0,21.146.0,36.124.0,21.79.0,49.131.0"}
P.entries["quest:5761"] = {n="Slaying the Beast"}
P.entries["quest:5762"] = {n="Hemet Nesingwary",s="Aceasta insarcinare ii poarta pe calatori peste mare, de la salinele din Kalimdor pana in junglele aburinde din Stranglethorn Vale. Kravel Koalbeard, un negustor oportunist de la Mirage Raceway, le cere aventurierilor sa livreze un pachet de provizii speciale, asteptat de multa vreme, renumitului vanator de vanat mare Hemet Nesingwary.",h="Aceasta insarcinare ii poarta pe calatori peste mare, de la salinele din Kalimdor pana in junglele aburinde...",kw={"munitii","hemet nesingwary","kravel koalbeard","kravel's crate","mirage raceway","shimmering flats","stranglethorn vale"},ang={["class:Hunter"]="Transportarea munitiei specializate direct la Hemet Nesingwary le face cunostinta vanatorilor de urme cu cel mai faimos safari de vanat mare din Azeroth.",["race:Dwarf"]="Livrarea de munitie facuta la comanda intre doi cunoscuti dwarf necinstiti arata cat de departe se imprastie expatriatii din Ironforge in cautarea banilor si a prazii."},sec={{t="O livrare transcontinentala",b="In intinderea orbitoare din Shimmering Flats, comertul se desfasoara rapid, dar uneori transporturile intarzie. Kravel Koalbeard primeste in cele din urma un cufar intarziat, destinat unuia dintre patronii sai instariti, Hemet Nesingwary. Hemet plecase din Thousand Needles cu mult inainte ca pachetul sa ajunga si platise in avans pentru a fi trimis mai departe la tabara sa de vanatoare din salbaticie, in Stranglethorn Vale. In loc sa faca singur drumul anevoios, Kravel recruteaza aventurieri ratacitori dispusi sa traverseze oceanul."},{t="Munitie pentru vanatoare",b="Dand peste expeditia lui Nesingwary la nord de Grom'gol Base Camp, descoperi continutul lazilor grele: munitie speciala, de calibru mare, esentiala pentru a dobori pradatorii periculosi care pandesc prin jungla. Hemet recunoaste imediat crusta alba distinctiva a salinelor, lipita de echipamentul curierului, si se bucura ca vechile sale legaturi cu siretul Kravel i-au adus puterea de foc de care avea atata nevoie pentru safari."}},faq={{q="De unde incepe si unde se incheie aceasta livrare?",a="Livrarea incepe la Mirage Raceway din Shimmering Flats, in Thousand Needles de sud, unde se afla Kravel Koalbeard. Se incheie la jumatatea lumii, in tabara expeditiei lui Hemet Nesingwary, ascunsa in nordul Stranglethorn Vale, chiar la nord de Grom'gol.",al={"inceputul si sfarsitul misiunii","unde este Hemet","unde trebuie sa merg"}},{q="Ce se afla in Kravel's Crate?",a="Lada contine munitie de calibru special, conceputa pentru arme de vanatoare mare. Hemet Nesingwary a comandat proiectilele personalizate pentru a strapunge pieile groase ale celor mai feroce bestii din Stranglethorn.",al={"ce se afla in lada","continutul lazii","pachetul lui Kravel"}},{q="De ce nu a livrat Kravel personal lada?",a="Kravel este un negustor pitic intreprinzator, ocupat sa-si supravegheze investitiile si planurile de la Mirage Raceway. Prefera sa angajeze aventurieri aflati in trecere, platindu-i cu banii pe care i-a primit in avans de la Nesingwary, decat sa-si abandoneze postul si sa traverseze marile.",al={"de ce angajeaza Kravel pe cineva","de ce are Kravel nevoie de ajutor"}},{q="Cum stie Hemet de unde a venit curierul?",a="Cand primeste coletul, Hemet simte imediat si identifica crusta distincta de sare prinsa de hainele curierului, observand ca a venit drept din Shimmering Flats, nu dintr-un desert obisnuit.",al={"sare desertica","dialogul lui hemet despre sare"}},{q="Ce fel de relatie au Kravel si Hemet?",a="Hemet este un client vechi si profitabil al lui Kravel. Desi Kravel ii respecta averea, Hemet il priveste cu drag pe Kravel ca pe un nelegiuit 'batran si scortos', care pune mereu ceva la cale.",al={"trecutul lui Kravel si Hemet","se cunosc?"}},{q="Cine este Hemet Nesingwary?",a="Hemet Nesingwary este un tragator pitic celebru, autor si vanator de vanat mare, care conduce un safari in desfasurare prin tinuturile primejdioase din Stranglethorn Vale.",al={"cine este hemet","nesingwary lore"}}},fx={["4f3179a4"]={q="De ce vrea Kravel Koalbeard ca aceasta lada sa-i fie livrata lui Hemet?",a="Kravel mentine o relatie comerciala profitabila. Hemet Nesingwary este un pitic remarcabil de bogat, iar Kravel stie ca satisfacerea unor clienti atat de instariti aduce castiguri. Hemet a platit in avans pentru ca lada sa fie trimisa la terenurile lui de vanatoare dupa sosire, asa ca respectarea intelegerii protejeaza reputatia lui Kravel si ii garanteaza castiguri viitoare.",al={"de ce sa livrezi lada lui Kravel","motivul lui Kravel Koalbeard","de ce sa trimiti lada la Hemet"}}},fp="16,316,27.507.0,23.417.0,39.265.0,30.179.0,44.241.0,48.209.0,51.178.0,24.157.0"}
P.entries["quest:5763"] = {n="Hunting in Stranglethorn",s="Roon Wildmane, un Tauren din Desolace, vana odinioara alaturi de un dwarf pe nume Hemet. Acum, Roon te trimite cu un corn de kodo la Hemet Nesingwary, in Stranglethorn, la nord de Grom'gol Base Camp.",h="Roon Wildmane, un Tauren din Desolace, vana odinioara alaturi de un dwarf pe nume Hemet.",kw={"desolace","grom'gol","hemet nesingwary","corn de kodo","roon wildmane","stranglethorn"},sec={{t="Un semn intre Hunter",b="Cu mult timp in urma, un dwarf pe nume Hemet a venit in Desolace, nerabdator sa vaneze bestii uriase. Hemet manevra o pusca cu o pricepere neobisnuita, iar cei doi vanatori au petrecut multe zile impreuna, lasand deoparte vechea dusmanie dintre popoarele lor. Cand Hemet a plecat spre Stranglethorn, Roon a jurat ca il va intampina intr-o zi la intoarcere pentru o noua vanatoare, iar acum Roon socoteste ca a sosit momentul. Trebuie sa duci cornul de kodo al lui Roon la Hemet, care va sti cui ii apartine. Cauta in Stranglethorn, la nord de Grom'gol Base Camp."},{t="Raspunsul lui Hemet",b="Hemet recunoaste imediat cornul ca fiind al lui Roon Wildmane, din randul Tauren, si isi aminteste de partidele frumoase de vanatoare impreuna, printre bestiile din Desolace. Deocamdata, Hemet e pana la gat in jungla, dar iti multumeste si crede ca urmatoarea expeditie ar putea duce inapoi in Desolace, tinutul centaurilor."}},faq={{q="Cine este Hemet?",a="Un dwarf a venit in Desolace dorind sa vaneze fiare uriase. Iscusinta lui Hemet cu pusca era nemaivazuta, iar el si Roon Wildmane au vanat impreuna multe zile, pana cand Hemet a plecat spre Stranglethorn.",al={"hemet nesingwary","cine este hemet"}},{q="De ce ii pasa lui Roon Wildmane de un Dwarf?",a="Cei doi au vanat impreuna multe zile, iar dusmania dintre popoarele lor a fost uitata. Roon a jurat ca il va primi cu bratele deschise pe Hemet, ca sa poata vana din nou impreuna.",al={"de ce sa-l ajuti pe dwarf","Roon Wildmane prieten dwarf"}},{q="Unde se afla Hemet?",a="In Stranglethorn, la nord de Grom'gol Base Camp.",al={"unde este hemet","locatia lui hemet","tabara de vanatoare stranglethorn"}},{q="La ce foloseste cornul de kodo?",a="Roon Wildmane i-l trimite lui Hemet, care va sti ca vine de la Roon.",al={"la ce foloseste cornul de kodo","de ce sa duci cornul de kodo"}}},fp="24,191,23.471.0,14.272.1,13.186.0,42.149.0,23.46.0,37.63.0"}
P.entries["quest:577"] = {n="Some Assembly Required",s="In Booty Bay, Drizzlik raporteaza ca cizmele prind forma, dar pieile pe care le-ai furnizat nu vor acoperi straturile interioare. Drizzlik propune sa le umple cu piei mai ieftine si mai groase, luate de la crocolisks din apropiere de Lake Nazferiti.",h="In Booty Bay, Drizzlik raporteaza ca cizmele prind forma, dar pieile pe care le-ai furnizat nu vor acoperi...",kw={"cizme","booty bay","crocodil","drizzlik","lake nazferiti","snapjaw","stranglethorn vale"},sec={{t="Umplerea cizmelor",b="Drizzlik a terminat forma aproximativa a cizmelor si spune ca avanseaza bine, dar pieile obtinute prin Supply and Demand nu ajung pentru captuseala. Nimeni n-o sa vada vreodata straturile acelea, asa ca Drizzlik se va multumi cu piei mai groase si mai ieftine, luate de la crocolisci din apropiere de Lake Nazferiti."},{t="Oferta de vanzare",b="Oferta lui Drizzlik promite cea mai fina executie si cizme confectionate din piele de crocolisc marin pura, de cea mai buna calitate. Drizzlik compara cizmele cu carnatii: arata grozav, au gust grozav si se spune ca sunt facute doar din cele mai bune ingrediente. E mai sigur si mai placut sa ai incredere in creator si sa nu te uiti prea atent la ce se afla cu adevarat inauntru."}},faq={{q="Cine cere aceste blanuri?",a="Drizzlik din Booty Bay, care lucreaza la cizmele Excelsior si are nevoie de mai multe piei, dupa cele livrate in Supply and Demand.",al={"cel care ofera misiunea","cine da Some Assembly Required","locatia lui drizzlik"}},{q="De ce blanuri are nevoie Drizzlik?",a="Cinci piei de crocolisc snapjaw.",al={"de ce piei am nevoie","tipul pielii de crocolisc","ce crocolisci"}},{q="Unde se gasesc crocodilii necesari?",a="Drizzlik te trimite la crocolisks din jurul lacului Lake Nazferiti.",al={"locatia lui lake nazferiti","unde sunt snapjaws","unde gasesc crocodili"}},{q="De ce vrea Drizzlik piei mai ieftine?",a="Interiorul cizmelor ramane ascuns privirilor tuturor, asa ca Drizzlik e bucuros sa le umple cu piei mai groase si mai ieftine.",al={"de ce piei mai ieftine","de ce piei de snapjaw","captuseala pentru cizme"}}},fp="22,223,17.291.0,15.341.1,30.125.0,30.29.0,40.59.0,37.119.0"}
P.entries["quest:578"] = {n="The Stone of the Tides",s="In urma zvonurilor despre o insula bantuita din largul coastei junglei, Baron Revilgaz banuieste ca a iesit din nou la iveala o relicva antica troll. Le cere exploratorilor sa cerceteze tinutul misterios si iti da o autorizatie pentru a studia artefactul in arhivele din Stormwind.",h="In urma zvonurilor despre o insula bantuita din largul coastei junglei, Baron Revilgaz banuieste ca a iesit...",kw={"baron revilgaz","booty bay","donyal tovald","gazban","gurubashi","piatra mareelor","biblioteca din stormwind","stranglethorn vale"},sec={{t="Ambitia unui magnat",b="Dupa ce a aflat despre aparitii stranii si elementali de apa care bantau o insula din largul Stranglethorn Vale, Baron Revilgaz a vazut o oportunitate. Banuieste ca Mage-ul goblin Gazban ar fi putut descoperi legendara Stone of the Tides, asa ca stapanul din Booty Bay te trimite sa gasesti insula si sa verifici daca zvonurile sunt adevarate. Ca sa-ti satisfaca orice curiozitate despre relicva, iti da un permis de biblioteca care poate fi folosit de invatatii din Stormwind."},{t="O protectie straveche",b="Confirmarea prezentei nefiresti de pe insula implineste cele mai mari sperante ale baronului: legendarul artefact este real. Totusi, nu va fi usor sa puna mana pe el. Stone of the Tides poarta un blestem magic puternic, pe care Revilgaz intelege ca nu-l poate inlatura singur; este nevoie de priceperea unui vrajitor experimentat inainte de a putea incepe recuperarea."}},faq={{q="Cine iti cere sa gasesti insula bantuita?",a="Baron Revilgaz, conducatorul din Booty Bay, te trimite sa investighezi dupa ce aude povesti despre o activitate ciudata in larg.",al={"cine da misiunea","cel care ofera misiunea stone of the tides","cine te trimite"}},{q="Unde se afla insula bantuita?",a="Insula se afla in largul coastei din Stranglethorn Vale, o insula departe, in mare, pe care va trebui sa o gasiti singur.",al={"unde este insula","locatia insulei","gaseste insula bantuita"}},{q="Ce este Piatra Mareelor?",a="Este un artefact legendar Troll pe care Revilgaz spera sa-l adauge colectiei sale; a aflat prima oara despre legenda dintr-o carte veche.",al={"ce este piatra","povestea pietrei mareelor","ce este stone of the tides"}},{q="De ce vrea Baron Revilgaz artefactul?",a="Baronul vrea sa puna mana pe puternica relicva troll, pentru a o adauga vastei sale colectii de artefacte si relicve antice.",al={"de ce il vrea revilgaz","motivele lui revilgaz"}},{q="La ce foloseste Library Scrip?",a="Inscrisul poate fi dus la Donyal Tovald, la Stormwind Library, pentru a obtine un exemplar al cartii in care baronul a citit pentru prima data despre legenda.",al={"ce este library scrip","library scrip din stormwind","unde duc scrip-ul"}},{q="Care a fost etapa anterioara din acest lant?",a="Aceasta investigatie urmeaza direct dupa The Haunted Isle, care i-a adus baronului primele vesti despre aparitiile neobisnuite.",al={"ce misiune este inainte","misiunea necesara in prealabil"}}},fp="22,253,20.443.0,15.331.1,42.101.0,36.110.0,31.124.0,42.120.0,35.140.0,41.117.0"}
P.entries["quest:579"] = {n="Stormwind Library",s="In Stormwind Keep, Donyal Tovald copiaza cronicile regatului pentru cei care au chitante de biblioteca. Tanarul rege Anduin Wrynn a pus deoparte fonduri regale pentru aceasta munca, punand aceste relatari despre Azeroth la dispozitia cetatenilor si a invatatilor.",h="In Stormwind Keep, Donyal Tovald copiaza cronicile regatului pentru cei care au chitante de biblioteca.",kw={"anduin wrynn","carti","donyal tovald","jeton de biblioteca","tomuri de istorie","stormwind keep","biblioteca din stormwind","transcriere"},ang={["class:Mage"]="Ca mage, poti apela la Royal Library pentru istoria regatului, in paralel cu studiile arcane din Mage Quarter.",["faction:Alliance"]="Ca cetatean din Alliance, poti gasi relatari despre triumfurile si tragediile Alliance of Lordaeron, precum si despre legaturile dintre human, dwarves, gnomes si high elves.",["race:Human"]="Ca Human, stii cat de important este sa pastrezi istoria. Vechiul Stormwind a pierdut nenumarate arhive cand a fost jefuit in timpul First War, iar acum invatatii protejeaza si copiaza istoriile care au supravietuit reconstruirii regatului."},sec={{t="Un mandat regal pentru cunoastere",b="In timp ce Highlord Bolvar Fordragon si Lady Katrana Prestor coordoneaza apararea si curtea din Stormwind in lipsa regelui Varian, tanarul King Anduin indreapta sprijinul regal catre invatatura. El finanteaza copii ale manuscriselor antice si jurnalelor istorice, pentru ca trecutul regatului sa poata fi pastrat si studiat. In Stormwind Keep, Royal Library pastreaza aceste relatari scrise si le copiaza pentru cei aflati in slujba coroanei."},{t="Schimbul de bonuri",b="Copierea manuala a unui pergament delicat necesita timp, cerneala si aprobarea regala. Bibliotecarul Donyal Tovald accepta ordine oficiale de biblioteca, emise aventurierilor si carturarilor din teritoriile Alliance. In schimb, ofera copii ale unor lucrari istorice, de la vechile cronici ale Eastern Kingdoms pana la relatari despre tinuturi indepartate, punand la dispozitie cunostinte despre conflicte de dincolo de capitala."}},faq={{q="Care este scopul misiunii Stormwind Library?",a="Poti schimba un Library Scrip cu bibliotecarul Donyal Tovald pentru a primi o carte pe care o poti citi. Aceste carti impartasesc istorii despre oamenii, locurile si evenimentele Alliance din Azeroth.",al={"ce face aceasta misiune","scopul misiunii din biblioteca Stormwind","de ce sa faci aceasta misiune"}},{q="Cine este Donyal Tovald?",a="Donyal Tovald se ocupa de Royal Library din Stormwind Keep. Administreaza cronicile scrise ale regatului si distribuie copii la porunca regelui Anduin.",al={"cine este Donyal Tovald","bibliotecar in Stormwind","cine da cartile"}},{q="Unde poti obtine un Library Scrip?",a="Library Scrips sunt oferite in teritoriile Alliance de carturari, magistrati si functionari care pretuiesc cunoasterea lumii largi.",al={"de unde fac rost de tichete de biblioteca","cum obtin tichete de biblioteca","sursa tichetelor de biblioteca"}},{q="De ce finanteaza tanarul rege Anduin biblioteca?",a="Regele Anduin Wrynn finanteaza copii ale lucrarilor istorice deoarece pretuieste invatarea si educatia. Cand era inca un copil, a alocat fonduri regale pentru ca istoriile regatului sa fie puse la dispozitia publicului, sub indrumarea regentului Bolvar Fordragon.",al={"de ce ii pasa lui Anduin de carti","finantarea bibliotecii de catre Anduin","cartile regelui Anduin"}},{q="Unde se afla biblioteca din Stormwind?",a="Royal Library se afla in Stormwind Keep, marea fortareata din partea de est a orasului. Donyal Tovald poate fi gasit printre rafturile si mesele de lectura.",al={"unde se afla biblioteca din Stormwind","locatia Royal Library","unde se afla Donyal Tovald"}},{q="Pot citi cartile pe care le primesc?",a="Da. Fiecare carte din biblioteca poate fi citita si ofera informatii despre legende si evenimente istorice din Azeroth.",al={"se pot citi cartile","poti deschide cartile","fac ceva cartile"}}},fx={c9ea8ca7={q="La ce foloseste Library Scrip?",a="Un Library Scrip este o autorizatie regala oficiala care permite ridicarea unui tom copiat de la Royal Library din Stormwind. Datorita finantarii oferite de tanarul rege Anduin Wrynn, biblioteca reproduce scrieri si relatari istorice pentru cetateni, dar Donyal Tovald are nevoie de un voucher valabil inainte sa poata ceda unul dintre aceste volume transcrise cu grija.",al={"ce sunt tichetele bibliotecii","la ce folosesc tichetele bibliotecii","de ce sunt necesare tichetele bibliotecii"}}},fp="17,220,29.410.0,18.372.0,51.165.0,21.156.0,36.134.0,45.240.0,42.160.0,31.114.0"}
P.entries["quest:58"] = {n="The Night Watch",s="Aceasta ultima misiune de la Commander Althea Ebonlocke ii trimite pe aventurierii Alliance in criptele din partea estica a Raven Hill Cemetery. Cu Night Watch raspandita si ocupata sa apere Darkshire, strainii trebuie sa patrunda in morminte si sa extermine puzderia de raspanditori ai molimei. Misiunea incununeaza campania militara directa a garzii orasului, menita sa opreasca invazia mortilor-vii.",h="Aceasta ultima misiune de la Commander Althea Ebonlocke ii trimite pe aventurierii Alliance in criptele din...",kw={"Althea Ebonlocke","Darkshire","Duskwood","ghouli","mausoleu","Night Watch","raspanditori de molima","Raven Hill","strigoi"},ang={["class:Paladin"]="Criptele molipsitoare din Raven Hill sunt o batjocura profana la adresa ritualurilor sacre de inmormantare, iar purificarea lor este o datorie vitala pentru slujitorii Holy Light.",["class:Priest"]="Contagiunea abjecta raspandita de ghouls in mausoleul estic pune la incercare sfintenia Light, impunand o purificare spirituala si fizica.",["faction:Alliance"]="Cu coroana regala din Stormwind ignorand rugamintile din Duskwood, campionii Alliance trebuie sa intervina personal pentru a-i salva pe cetatenii loiali inainte sa fie coplesiti de strigoi."},sec={{t="O frontiera disperata",b="Darkshire este aproape complet izolat, abandonat de armata Stormwindului si dependent in intregime de propria militie civila, Night Watch. Commander Althea Ebonlocke si-a epuizat fortele limitate doar pentru a pazi rascrucea, perimetrul orasului si liniile de aprovizionare. Pe masura ce mortii nelinistiti se inmultesc in tot Duskwood, comandantul nu are de ales decat sa-i investeasca cu autoritate pe campionii ratacitori, trimitandu-i sa duca lupta direct in cotloanele intunecate din Raven Hill."},{t="Purificarea mausoleului",b="Mausoleul estic din Raven Hill Cemetery este una dintre cele mai periculoase concentrari de strigoi din regiune. Spre deosebire de tumulii deschisi, aceasta cripta de piatra este plina de raspanditori ai molimei - ghuli purtatori de boli corupatoare, capabili sa-i imbolnaveasca pe cei vii. Eliminarea a douazeci dintre aceste abominatii le ofera un ragaz pretios membrilor obositi ai Night Watch, asigurandu-se ca Darkshire nu va fi lovit dinspre vest de un atac coordonat al strigoilor."}},faq={{q="De ce trimite Night Watch aventurieri in loc sa-si trimita propriii oameni?",a="Night Watch este intinsa la maximum in tot tinutul Duskwood. Cum Stormwind nu trimite trupe oficiale, comandantul Althea Ebonlocke abia are destui gardieni pentru a tine sub control perimetrul din Darkshire si a supraveghea drumurile, fara sa-i ramana vreo militie disponibila pentru a curata cripte adanci si fortificate precum Raven Hill.",al={"de ce sa ajuti Darkshire","de ce are nevoie Night Watch de ajutor","numarul redus al membrilor Night Watch"}},{q="Unde se afla mausoleul estic?",a="Se afla in partea estica a cimitirului Raven Hill Cemetery, situat in nord-vestul tinutului Duskwood. Intrarea duce in subteran, in cripte de piatra unde se aduna raspanditorii ciumei.",al={"unde sunt cei care raspandesc ciuma","locatia mausoleului estic","unde este mausoleul"}},{q="Ce ii face periculosi pe raspanditorii molimei?",a="Raspanditorii plagi sunt ghuli lacomi, purtatori ai unei putreziciuni virulente. Lasata nestavilita, coruptia lor scarboasa risca sa se extinda dincolo de cimitir si sa-i molipseasca pe supravietuitorii din Darkshire.",al={"de ce sa omori raspanditorii ciumei","ce sunt raspanditorii ciumei"}},{q="Cine este Commander Althea Ebonlocke?",a="Althea Ebonlocke este comandanta si lidera a Night Watch, precum si o ruda a primarului din Darkshire, Lord Ello Ebonlocke. Ea organizeaza apararea Duskwood din interiorul Darkshire.",al={"cine este Althea","comandantul Ebonlocke","cine conduce Night Watch"}},{q="Incheierea acestei serii de misiuni pune capat amenintarii strigoilor din Duskwood?",a="Nu. Desi raruirea mausoleului usureaza presiunea imediata asupra Darkshire, Raven Hill ramane cu totul infestat, iar puterile intunecate din Duskwood continua sa-i trezeasca pe morti.",al={"este Raven Hill salvat","Darkshire este in siguranta acum"}},{q="Cum se incadreaza aceasta in firul de misiuni Night Watch?",a="Acesta este al treilea si ultimul capitol din seria martiala directa a lui Commander Ebonlocke, 'The Night Watch', care trece de la drumurile deschise la marginile cimitirului si, in cele din urma, in adancul mausoleului.",al={"ce lant de misiuni este acesta","este aceasta ultima misiune din Night Watch"}}},fx={f0d896f3={q="De ce vrea Commander Althea Ebonlocke ca acest lucru sa fie facut?",a="Comandantul Althea Ebonlocke poarta povara grea a apararii orasului Darkshire, cu randurile militiei puternic subtiate. Cimitirul intins din Raven Hill a devenit un focar al coruptiei strigoilor, iar ea se teme ca, daca fapturile hidoase care se aduna in criptele sale nu sunt tinute in frau, vor napadi negresit spre est si vor coplesi intregul oras. Nimicirea celor care raspandesc molima este o masura disperata, menita sa domoleasca valul amenintator si sa-i ocroteasca pe cei vii.",al={"de ce sa ucizi raspanditorii molimei","motivul lui Ebonlocke in Duskwood","de ce sa te trimita din nou la Raven Hill"}},["0678b7f2"]={q="Ce sunt raspanditorii ciumei din mausoleu?",a="Raspanditorii plagi sunt cadavre putrede, readuse la viata, care bantuie mormintele profanate din Raven Hill Cemetery. Imbibati cu molime spurcate si putreziciune, pandesc in adancurile mausoleului estic, profanand mormintele mortilor din Duskwood si amenintand sa-si raspandeasca mizeria contagioasa prin paduri. Prezenta lor staruitoare transforma vechiul loc de veci intr-un izvor nesecat de neviata.",al={"cine sunt raspanditorii ciumei","raspanditorii ciumei din Duskwood","strigoii din mausoleul estic"}}},fp="15,358,20.458.0,21.438.0,68.281.0,39.175.0,42.187.0,34.190.0,61.180.0,49.193.0"}
P.entries["quest:580"] = {n="Whiskey Slim's Lost Grog",s="In adapostul piratilor din Booty Bay, Whiskey Slim se afla intr-o mare incurcatura cu capitanul sau. In timpul unei furtuni violente in largul coastei din Hinterlands, Slim a deschis o lada capturata, plina cu Pupellyverbos Port, dar valurile involburate i-au luat sticlele. Ca sa scape de o bataie cumplita, are nevoie de un aventurier care sa-i recupereze bautura pierduta.",h="In adapostul piratilor din Booty Bay, Whiskey Slim se afla intr-o mare incurcatura cu capitanul sau.",kw={"Booty Bay","grogg","Hinterlands","Overlook Cliffs","corsar","Pupellyverbos Port","Stormwind","Whiskey Slim"},sec={{t="O furtuna in Hinterlands",b="Echipajul lui Whiskey Slim se lupta cu o vreme cumplita in largul falezelor Overlook, avand tarmul din Hinterlands in apropiere, cand marinarul a cautat o doza de curaj lichid. Nava lui capturase o lada de Pupellyverbos Port de pe o corabie de corsari care se indrepta spre Stormwind. Cu valuri amenintand sa le inghita nava, Slim a spart lada capitanului, dar un val puternic a maturat sticlele peste bord."},{t="Disperarea unui marinar",b="Inapoi in Booty Bay, timpul se scurge in timp ce corabia se pregateste sa ridice ancora. Slim se teme ca va fi biciuit cu noua cozi cand ofiterul sau comandant isi va da seama ca lipseste portul confiscat. Cauta pe cineva dispus sa aduca inapoi douasprezece sticle inainte ca furtul sa iasa la iveala."}},faq={{q="Cine este Whiskey Slim?",a="Whiskey Slim este un marinar care locuieste in Booty Bay si a ajuns in mare incurcatura dupa ce si-a pierdut alcoolul furat al capitanului in timpul unei furtuni pe mare.",al={"Whiskey Slim","cine ofera bautura pierduta","cine este Slim"}},{q="De unde a venit grogul?",a="Lada cu Pupellyverbos Port a fost confiscata de echipajul lui Slim de pe o nava corsara aflata in drum spre Stormwind.",al={"originea Pupellyverbos Port","de unde a luat slim grogul","bautura piratului"}},{q="Unde a pierdut Whiskey Slim sticlele?",a="Slim a pierdut sticlele peste bord in timpul unei furtuni naprasnice, in largul stancilor Overlook, aproape de coasta Hinterlands, cand un val urias a izbit corabia.",al={"unde s-a pierdut grogul","furtuna deasupra stancilor Overlook","locatia grogului in Hinterlands"}},{q="De ce are Whiskey Slim nevoie sa-i fie inapoiate sticlele atat de repede?",a="Corabia lui se pregateste sa ridice ancora, iar cand capitanul va descoperi ca portul ii lipseste, Slim se teme ca va fi pedepsit cu o biciuire cu pisica-cu-noua-cozi.",al={"de ce sa-l ajuti pe Slim","ce i se intampla lui Slim","gustul pisicii"}}},fp="24,336,29.424.0,22.280.0,20.140.0,29.121.0,40.150.0,55.159.0"}
P.entries["quest:5801"] = {n="Fire Plume Forged",s="Krinkle Goodsteel te indruma spre Fire Plume Ridge, un vulcan in clocot din vestul Un'Goro Crater, unde lacul de lava din varf este suficient de fierbinte pentru a fauri tija unei chei scheletice. Dupa aceea, du-o la Alchemist Arbington, la Chillwind Point, in Western Plaguelands.",h="Krinkle Goodsteel te indruma spre Fire Plume Ridge, un vulcan in clocot din vestul Un'Goro Crater, unde lacul...",kw={"alchemist arbington","chillwind point","fire plume ridge","krinkle goodsteel","matrita pentru cheie de schelet","thorium","un'goro crater","cheie de schelet neterminata"},sec={{t="Foc pentru tija cheii",b="Forjarea tijei cheii necesita doua lingouri de thorium si o caldura intensa. Tu trebuie sa gasesti thorium-ul, dar Krinkle Goodsteel te poate ajuta cu caldura. Cu aurul tau ai cumparat o matrita, care nu trebuie decat scufundata in lacul de lava din varful Fire Plume Ridge. Lava face restul, unind thorium-ul si osul."},{t="Inapoi la Arbington",b="Krinkle Goodsteel si-a facut partea. Pentru a termina cheia, va trebui sa vorbesti din nou cu Alchemist Arbington la Chillwind Point, in Western Plaguelands. Cheia facuta din lava este tot neterminata, iar lucrarile de pana acum sunt pregatiri pentru un asalt."},{t="Ce ne asteapta",b="Arbington spune ca cheia este foarte costisitoare, dar ca inca nu este terminata. Dusmanul impotriva caruia au fost indreptate toate aceste eforturi se afla in Andorhal: Araj the Summoner, un lich numarat printre cei mai puternici din Scourge."}},faq={{q="Unde este faurit miezul cheii?",a="La lacul de lava din varful Fire Plume Ridge, un vulcan in fierbere din Un'Goro Crater, la vest de Krinkle Goodsteel.",al={"unde se faureste cheia","locatia Fire Plume Forged","locatia lacului de lava"}},{q="De ce este nevoie pentru a fauri tija cheii?",a="Tiparul pentru cheia scheletica si doua lingouri de thorium. Thoriumul trebuie sa-l gasesti tu.",al={"de ce am nevoie","materiale necesare","cerinta de thorium"}},{q="Cine primeste cheia neterminata?",a="Alchemist Arbington, la Chillwind Point din Western Plaguelands.",al={"cui predau acest obiect","locatia lui Arbington","unde trebuie dusa cheia neterminata"}}},fp="17,268,21.304.0,17.249.0,15.202.1,29.110.0,37.78.0,32.67.0"}
P.entries["quest:5802"] = {n="Fire Plume Forged",s="Krinkle Goodsteel te indruma spre Fire Plume Ridge, un vulcan clocotitor din vestul Un'Goro Crater, unde lacul de lava din varf este suficient de fierbinte pentru a forja tija unei chei scheletice. Dupa aceea, o duci la Apothecary Dithers, la Bulwark, in Western Plaguelands.",h="Krinkle Goodsteel te indruma spre Fire Plume Ridge, un vulcan clocotitor din vestul Un'Goro Crater, unde...",kw={"andorhal","apothecary dithers","bulwark","fire plume ridge","krinkle goodsteel","matrita pentru cheie universala","lingou de thorium","un'goro crater","cheie universala neterminata"},sec={{t="Foc pentru tija cheii",b="Forjarea tijei cheii necesita doua lingouri de thorium si o caldura intensa. Tu trebuie sa gasesti thorium-ul, dar Krinkle Goodsteel te poate ajuta cu caldura. Cu aurul tau ai cumparat o matrita, care nu trebuie decat scufundata in lacul de lava din varful Fire Plume Ridge. Lava face restul, unind thorium-ul si osul."},{t="Inapoi la Dithers",b="Krinkle Goodsteel si-a facut partea. Ca sa termini cheia, va trebui sa vorbesti din nou cu Apothecary Dithers, de la Bulwark, in Western Plaguelands. Cheia din lava este inca neterminata, iar munca de pana acum a fost o pregatire pentru un asalt."},{t="Ce ne asteapta",b="Dithers spune ca cheia este foarte costisitoare, dar ca nu este inca terminata. Dusmanul impotriva caruia s-a facut toata aceasta munca se afla in Andorhal: Araj the Summoner, un lich aflat printre cei mai puternici din Scourge."}},faq={{q="Unde este faurit miezul cheii?",a="La lacul de lava din varful Fire Plume Ridge, un vulcan in fierbere din Un'Goro Crater, la vest de Krinkle Goodsteel.",al={"unde sa forjezi cheia","locatia lacului de lava","lava din fire plume ridge"}},{q="De ce este nevoie pentru a fauri tija cheii?",a="Tiparul pentru cheia scheletica si doua lingouri de thorium. Thoriumul trebuie sa-l gasesti tu.",al={"de ce am nevoie","materiale esentiale","thorium necesar"}},{q="Cine primeste cheia neterminata?",a="Apothecary Dithers, la Bulwark din Western Plaguelands.",al={"cui predau","unde ajunge cheia","predarea cheii"}}},fp="17,263,21.304.0,15.244.0,15.200.1,29.110.0,37.78.0,32.62.0"}
P.entries["quest:581"] = {n="Hunt for Yenniku",s="Nimboya s-a intors din Orgrimmar in junglele din Stranglethorn Vale pentru a-l cauta pe Yenniku, fiul cel mai tanar al conducatorului sau. Banuiind ca tribul Bloodscalp il tine captiv pe tanar, cercetasul iti cere sa-i vanezi razboinicii si sa le iei coltii pentru a-ti demonstra puterea.",h="Nimboya s-a intors din Orgrimmar in junglele din Stranglethorn Vale pentru a-l cauta pe Yenniku, fiul cel mai...",kw={"bloodscalp","darkspear","grom'gol","hunt for yenniku","nimboya","stranglethorn","colti","yenniku","zul'gurub"},ang={["faction:Horde"]="Trimis direct din Orgrimmar, Nimboya se bazeaza pe aliatii din Horde care actioneaza din Grom'gol Base Camp pentru a ajuta la asigurarea protectiei rudelor capeteniei Darkspear.",["race:Troll"]="Pentru Trolls din Darkspear, raspunsul la chemarea lui Nimboya inseamna sa-si ajute propria familie de conducator si sa-i vaneze pe Bloodscalp, care s-ar putea sa-l tina prizonier."},sec={{t="Fiul pierdut al unui sef de trib",b="La Grom'gol Base Camp, Nimboya vorbeste despre soarta sumbra care il asteapta pe Yenniku, fiul cel mic al conducatorului Darkspear. Potrivit unui vechi obicei tribal, baiatul fusese lasat in grija trollilor Gurubashi din Zul'Gurub. Cand tribul Darkspear si-a parasit patria alaturi de warchief-ul orc Thrall, Yenniku a fost lasat in urma si s-a pierdut. Intors din indepartatul Orgrimmar, Nimboya si-a asumat raspunderea de a-l gasi pe fiul conducatorului si de a-l duce intr-un loc sigur."},{t="Vanatoarea Bloodscalp",b="Nimboya crede ca tribul Bloodscalp il tine acum pe Yenniku. Cere dovada ca un aventurier este destul de puternic ca sa-i vaneze. Esti trimis spre nord sa vanezi trolls Bloodscalp si sa le aduni noua colti. Aducerea acestor trofee la Grom'gol Base Camp iti dovedeste iscusinta in lupta si incepe o urmarire mai lunga pentru gasirea baiatului capeteniei, conducand direct la vanatoarea cunoscuta drept Headhunting."}},faq={{q="Cine este Yenniku?",a="Yenniku este fiul cel mai tanar al capeteniei tribului Darkspear. Potrivit obiceiului tribal, a fost dat troll-ilor Gurubashi din Zul'Gurub, dar s-a separat de ai sai cand Darkspears au parasit regiunea.",al={"povestea lui Yenniku","cine este Yenniku","fiul sefului de trib"}},{q="De ce a fost Yenniku lasat in urma in Stranglethorn?",a="Obiceiul tribal a facut ca Yenniku sa fie trimis la Trolls Gurubashi din Zul'Gurub. Cand tribul Darkspear s-a aliat cu Thrall si a plecat, tanarul a fost pierdut pentru ei.",al={"de ce a ramas yenniku","cum s-a pierdut yenniku","de ce zul'gurub"}},{q="Cine este Nimboya?",a="Nimboya este un troll Darkspear stationat in Grom'gol Base Camp. A fost trimis din indepartatul Orgrimmar inapoi in Stranglethorn Vale pentru a-l cauta pe fiul disparut al conducatorului sau.",al={"cine ofera Hunt for Yenniku","nimboya","cercetasul grom'gol"}},{q="De ce trebuie sa aduni colti Bloodscalp?",a="Nimboya banuieste ca tribul Bloodscalp l-a capturat pe Yenniku. Iti cere noua colti de Bloodscalp drept dovada ca ai puterea sa vanezi acesti trolls ostili, inainte sa continue cautarile.",al={"scopul coltilor Bloodscalp","de ce colti","coltii pentru Hunt for Yenniku"}},{q="Unde se afla trollii Bloodscalp?",a="Nimboya le indica hunterilor sa-i caute pe cei din tribul Bloodscalp in tinutul aflat la nord de Grom'gol Base Camp.",al={"unde gasesc bloodscalps","locatia Bloodscalp","unde sunt trollii Bloodscalp"}}},fp="16,280,22.478.0,23.395.0,15.209.0,45.154.0,15.169.0,44.188.0,40.109.0"}
P.entries["quest:582"] = {n="Headhunting",s="Nimboya, de la Grom'gol Base Camp, trebuie sa afle daca Yenniku, fiul capeteniei Darkspear, este mort. Aventurierilor li se cere sa vaneze headhunteri Bloodscalp si sa le aduca inapoi capetele micsorate, pentru ca Nimboya sa le poata examina.",h="Nimboya, de la Grom'gol Base Camp, trebuie sa afle daca Yenniku, fiul capeteniei Darkspear, este mort.",kw={"bloodscalp","gan'zulah","grom'gol base camp","vanatoare de capete","nimboya","cap micsorat","yenniku","zul'kunda","zuuldaia"},ang={["faction:Horde"]="Actionand din Grom'gol Base Camp, fortele din Horde isi ajuta aliatii Darkspear sa descopere daca fiul disparut al capeteniei mai este in viata.",["race:Troll"]="Soarta fiului sefului este o chestiune profund personala pentru Darkspear, care trebuie sa infrunte tribul Bloodscalp pentru a afla ce i s-a intamplat."},sec={{t="Cautarea printre trofee",b="Continuand cautarea inceputa in Hunt for Yenniku, Nimboya se teme ca fiul capeteniei ar fi putut deja sa piara de mana tribului Bloodscalp. Pentru a afla adevarul, iti cere sa vanezi Bloodscalp Headhunter care umbla prin ruinele din Zuuldaia si Zul'Kunda, de-a lungul coastei nordice. Adunand douazeci de capete micsorate de la ei, Nimboya spera sa cerceteze trofeele sinistre si sa afle daca Yenniku a avut parte de un sfarsit violent; daca baiatul a fost ucis, va blestema capetenia Bloodscalp, Gan'zulah."}},faq={{q="Cine il cauta pe Yenniku?",a="Nimboya, aflat la Grom'gol Base Camp, il cauta pe Yenniku, fiul conducatorului tribului Darkspear.",al={"cine ofera Headhunting","scopul lui Nimboya","de ce sa-l caut pe Yenniku"}},{q="De ce vrea Nimboya capete micsorate?",a="Nimboya planuieste sa cerceteze capetele micsorate luate de la Bloodscalp headhunters, pentru a verifica daca printre trofeele lor se afla capul lui Yenniku.",al={"de ce strangem capete micsorate","scopul capetelor micsorate","ce face nimboya cu capetele"}},{q="Unde pot fi gasiti Bloodscalp Headhunters?",a="Bloodscalp Headhunters se aduna de-a lungul coastei de nord a Stranglethorn Vale, mai ales in jurul ruinelor din Zuuldaia si Zul'Kunda.",al={"locatia headhunter","unde sunt zuuldaia si zulkunda","unde gasesc capete micsorate"}},{q="Cine conduce tribul Bloodscalp mentionat aici?",a="Bloodscalp sunt condusi de Chief Gan'zulah, iar Nimboya doreste sa-i cada un blestem de sase sute de ani asupra spiritului daca Yenniku e mort.",al={"capetenia Bloodscalp","cine este ganzulah","capetenia ganzulah"}}},fp="11,225,22.487.0,27.106.0,37.135.0,46.134.0,46.125.0"}
P.entries["quest:5821"] = {n="Bodyguard for Hire"}
P.entries["quest:583"] = {n="Welcome to the Jungle",s="Barnil Stonepot le ureaza bun venit noilor veniti in tabara de vanatoare din nordul Stranglethorn Vale. Recunoscand in tine un calator incercat in lupta, iti aranjeaza o intalnire cu liderul expeditiei, renumitul vanator Hemet Nesingwary.",h="Barnil Stonepot le ureaza bun venit noilor veniti in tabara de vanatoare din nordul Stranglethorn Vale.",kw={"barnil","hemet","nesingwary","pantera","raptor","stonepot","stranglethorn","tigru"},ang={["class:Hunter"]="Pentru un Hunter care rataceste prin junglele din Stranglethorn, Hemet Nesingwary ar putea avea cateva sfaturi de vanatoare de impartasit.",["faction:Alliance"]="Barnil Stonepot arata ca Hemet Nesingwary este un renumit erou de razboi al Alliance, care are o slabiciune pentru veteranii de arme.",["race:Dwarf"]="Vanatorul renumit al taberei, Hemet Nesingwary, este un Dwarf ca tine, iar Barnil Stonepot il indica drept un maestru al vanatorii de vanat mare."},sec={{t="O audienta cu maestrul",b="Barnil Stonepot ii intampina pe cei nou-veniti in tabara din jungla Stranglethorn Vale si recunoaste dintr-o privire un combatant incercat. Ti-l arata pe Hemet Nesingwary, un erou de razboi celebru al Alliance si un cercetas fara egal. Nesingwary isi rezerva tov aras ia pentru veteranii care si-au dovedit valoarea, iar Barnil crede ca pe batranul tragator l-ar putea convinge sa-si impartaseasca intelepciunea vanatoreasca cu cineva care a trecut prin incercarile luptei."},{t="Incercarile expeditiei",b="Nesingwary te intampina cu caldura si remarca cat de rar este sa vada pe cineva de breasla ta prin aceste tinuturi salbatice. Iti explica faptul ca expeditia sa s-a adunat aici cu un singur scop: sa vaneze o bestie legendara si greu de gasit din jungla. Este dispus sa te primeasca in marea vanatoare, dar trebuie mai intai sa-i castigi increderea prin vanarea unor prazi mai putin primejdioase. Nesingwary supravegheaza personal urmarirea rapitorilor, in timp ce tovarasii sai, Ajeck si Sir Erlgadin, ii invata pe Hunteri sa vaneze tigri si pantere."}},faq={{q="Cine este Hemet Nesingwary?",a="Hemet Nesingwary este un veteran de razboi celebru al Alliance si un vanator de vanat mare renumit. Conduce o tabara de expeditie in junglele din Stranglethorn Vale.",al={"hemet nesingwary","cine este hemet","povestea lui nesingwary"}},{q="Cine te trimite sa vorbesti cu Nesingwary?",a="Barnil Stonepot, unul dintre membrii stationati in tabara din jungla, le spune aventurierilor incercati sa-l salute pe Nesingwary, dupa ce le recunoaste experienta de lupta.",al={"barnil stonepot","responsabilul misiunii","cine da misiunea Welcome to the Jungle"}},{q="Ce urmeaza dupa ce vorbesti cu Nesingwary?",a="Se deschid mai multe vanatori: Raptor Mastery, Tiger Mastery, Panther Mastery si The Green Hills of Stranglethorn.",al={"cum sa ma alatur vanatorii","probele lui Nesingwary","lectii de vanatoare"}}},fp="21,236,27.408.0,28.475.1,24.151.0,39.163.0,42.107.0"}
P.entries["quest:584"] = {n="Bloodscalp Clan Heads",s="Dupa sortarea trofeelor adunate in jungla, Nimboya confirma ca tanarul troll disparut, Yenniku, nu se numara printre ele. Pentru a afla adevarul despre soarta lui Yenniku, Darkspear incearca sa-i sileasca pe conducatorii tribului rival Bloodscalp sa raspunda.",h="Dupa sortarea trofeelor adunate in jungla, Nimboya confirma ca tanarul troll disparut, Yenniku, nu se numara...",kw={"Bloodscalp","cazan","Darkspear","Gan'zulah","Grom'gol","Nezzliok","Nimboya","Yenniku","Zul'Kunda"},ang={["faction:Horde"]="Luptatorii Horde de la Grom'gol Base Camp isi pun forta in slujba cautarii lui Yenniku de catre Darkspear.",["race:Troll"]="Pentru Darkspear, confruntarea cu capeteniile Bloodscalp inseamna sa infrunte conducatorii unui trib dusman."},sec={{t="Cerand raspunsuri de la morti",b="Dupa ce vanatoarea de mai inainte a dovedit ca Yenniku nu se numara printre trofeele Bloodscalp cazute, Nimboya cauta raspunsuri de la conducatorii de rang inalt. Capetenia Bloodscalp, Gan'zulah, si vrajitorul sau, Nezzliok the Dire, sunt dusmani ai tribului Darkspear si nu ar vorbi niciodata de bunavoie. Nimboya vrea sa smulga adevarul de pe buzele lor moarte, ducandu-le capetele la cazanul din Grom'gol Base Camp pentru a-i face sa vorbeasca."},{t="In Zul'Kunda",b="Ambii lideri Bloodscalp locuiesc adanc in ruinele Zul'Kunda, in nord-vestul Stranglethorn Vale. Nimboya vrea sa le ia capetele si sa le arunce in fiertura clocotita, pentru a-i face sa vorbeasca despre Yenniku."}},faq={{q="De ce vrea Nimboya capetele lui Gan'zulah si Nezzliok?",a="Yenniku este inca disparut, iar Nimboya crede ca doar capetenia Bloodscalp si vrajitorul sau doctor stiu adevarul. Pentru ca acesti conducatori sunt dusmani ai Darkspear si nu ar vorbi niciodata de buna voie, Nimboya planuieste sa smulga adevarul de pe buzele lor moarte cu ajutorul cazanului.",al={"de ce sa omori conducatorii Bloodscalp","de ce capete taiate","motivul lui Nimboya"}},{q="Unde se afla Gan'zulah si Nezzliok?",a="Ambii lideri troll isi au salasul in adancurile Zul'Kunda, o ruina din nord-vestul Stranglethorn Vale, aproape de plaja.",al={"unde este Ganzulah","unde este Nezzliok","gaseste capeteniile Bloodscalp","locatia Zulkunda"}},{q="Ce se intampla dupa ce sunt livrate capetele?",a="Capetele retezate sunt puse direct in cazanul clocotitor de la Grom'gol Base Camp, astfel incat cei doi conducatori sa poata fi facuti sa vorbeasca.",al={"unde ajung capetele","ce fac cu capetele","predare la bubbling cauldron"}},{q="Cum se leaga aceasta de cautarea lui Yenniku?",a="Aceasta investigatie a inceput cu cautarea tanarului Yenniku. Dupa ce vanatoarea de capete de mai devreme a dovedit ca nu se numara printre mortii de rand, urmatorul pas pentru a-i afla locul este sa-i interoghezi pe conducatorii Bloodscalp.",al={"linia de misiuni a lui yenniku","legatura cu Hunt for Yenniku"}}},fp="21,257,31.405.0,14.214.0,58.265.0,41.111.0,42.127.0,48.206.0"}
P.entries["quest:585"] = {n="Speaking with Nezzliok",s="Dupa ce il invinge pe vrajitorul Bloodscalp, capul sau retezat vorbeste din cazanul bolborositor de la Grom'gol Base Camp. Acesta sustine ca stie unde a fost dus copilul Darkspear disparut, dar refuza sa dezvaluie secretul fara un tribut sumbru.",h="Dupa ce il invinge pe vrajitorul Bloodscalp, capul sau retezat vorbeste din cazanul bolborositor de la...",kw={"balia'mah","bloodscalp","cazan","grom'gol","nezzliok","skullsplitter","stranglethorn","yenniku","ziata'jai","zul'mamwe"},ang={["faction:Horde"]="Horde se bazeaza pe negocierea cu un spirit dusman legat la Grom'gol Base Camp pentru a descalci disparitia lui Yenniku, fiul capeteniei Darkspear.",["race:Troll"]="Trolls Darkspear trebuie sa ofere la troc capul retezat al unui witch doctor Bloodscalp ostil pentru a afla ce s-a intamplat cu fiul rapit al conducatorului lor."},sec={{t="Pretul unui spirit",b="Desi este legat in cazanul clocotitor dupa vanatoarea capetelor Bloodscalp Clan Heads, Nezzliok nu coopereaza deloc. Recunoaste ca stie unde a fost dus Yenniku, dar cere o rasplata inainte sa dea informatia. Porunceste sa fie luate trei cranii de trofeu de la tribul rival Skullsplitter si aduse la locul sau de odihna, pentru ca spiritul sau raposat sa porunceasca thralls in Nether."},{t="Craniile rivalilor",b="Nezzliok cere un craniu luat direct din gramada de trofee Skullsplitter de la Balia'mah, un al doilea de la Ziata'jai si un al treilea de la Zul'Mamwe. Abia cand toate cele trei ofrande se vor afla langa propriul sau cap va considera doctorul vrajitor mort ca spiritul sau este impacat."}},faq={{q="Cine este Nezzliok?",a="Nezzliok a fost un vraci al tribului Bloodscalp. Dupa ce a cazut in lupta, capul taiat i-a fost pus intr-un cazan clocotitor la Grom'gol Base Camp, unde spiritul sau legat continua sa vorbeasca.",al={"nezzliok","witch doctor nezzliok","povestea lui nezzliok"}},{q="Ce cere Nezzliok?",a="El cere trei cranii de trofeu furate din taberele rivalilor sai urati, Skullsplitters: unul din Balia'mah, unul din Ziata'jai si unul din Zul'Mamwe.",al={"ce vrea Nezzliok","trofee pentru Nezzliok","obiectivul Speaking with Nezzliok"}},{q="De ce vrea Nezzliok trofee Skullsplitter?",a="Nezzliok vrea ca trofeele cu cranii sa fie asezate langa el, astfel incat, atunci cand spiritul lui trece in Nether, sa aiba trei slujitori legati de el in moarte.",al={"de ce cranii trofeu","de ce vrea nezzliok cranii"}},{q="Unde are loc?",a="Intalnirea are loc la cazanul clocotitor din Grom'gol Base Camp, in adancul Stranglethorn Vale.",al={"unde este nezzliok","locatia cazanului clocotitor"}}},fp="22,239,16.408.0,20.259.0,16.196.0,26.157.0,46.150.0,23.110.0"}
P.entries["quest:586"] = {n="Speaking with Gan'zulah",s="Chiar si dupa ce si-a pierdut capul in fiertura clocotita de la Grom'gol Base Camp, capetenia Bloodscalp Gan'zulah clocoteste de furie. Pentru a-i potoli mania care persista, spiritul fara cap cere moartea rivalilor sai inversunati, Skullsplitter, si nimicirea conducatorului lor, Ana'thek the Cruel.",h="Chiar si dupa ce si-a pierdut capul in fiertura clocotita de la Grom'gol Base Camp, capetenia Bloodscalp...",kw={"ana'thek","berserker","bloodscalp","cazan","gan'zulah","grom'gol","vanator de capete","skullsplitter","stranglethorn"},ang={["faction:Horde"]="Capul lui Gan'zulah sta in cazanul de la Grom'gol Base Camp, iar el trimite campioni Horde impotriva dusmanilor sai Skullsplitter.",["race:Troll"]="Pentru Troll din Darkspear, sa-i priveasca pe rivali stravechi precum Bloodscalp si Skullsplitter, carora ura neostoita le-a intors unul impotriva celuilalt, este o trista amintire a vrajbei crunte din jungla."},sec={{t="Razbunarea unui sef de trib",b="Dupa strangerea capetelor Bloodscalp Clan Heads, capul taiat al lui Gan'zulah continua sa blesteme pe oricine sta deasupra cazanului clocotitor. Mistuit de ura fata de rapitorii sai si de dusmanii lui stravechi, capetenia moarta ofera o cale de a-i potoli furia clocotitoare: un atac asupra fortaretei estice a tribului Skullsplitter. Cere masacrarea vanatorilor, capetelor-de-vanatoare si berserkerilor lor, provocandu-i pe calatori sa-si gaseasca moartea in fata bandei lor feroce de razboinici."},{t="Armura distrusa",b="Gan'zulah se asteapta ca atacul sa se incheie dezastruos si e convins ca Chief Ana'thek the Cruel va sfasia orice intrus care indrazneste sa-l infrunte. Nu accepta decat armura zdrobita luata chiar de pe conducatorul Skullsplitter, drept dovada a victoriei. Doar ducand acest trofeu inapoi la cazanul din Grom'gol Base Camp ii poti potoli ranchiuna capeteniei moarte."},{t="O pace fragila",b="Prezentarea armurii sfaramate a lui Ana'thek ii curma insultele lui Gan'zulah. Confruntat cu realitatea infrangerii rivalului sau, mania razbunatoare a capeteniei se domoleste in cele din urma. Desi recunoaste puterea necesara pentru a-l invinge pe Ana'thek, promite ca aceasta victorie doar le amana socotelile, jurand ca se vor infrunta din nou in Nether."}},faq={{q="Unde vrea Gan'zulah sa mergi?",a="Gan'zulah te trimite spre est, in inima teritoriului Skullsplitter, catre asezarea unde luptatorii acestora se aduna sub comanda lui Ana'thek the Cruel.",al={"unde sunt Skullsplitter","unde merg pentru a vorbi cu Ganzulah","locatia Skullsplitter"}},{q="Cine este Ana'thek the Cruel?",a="Ana'thek the Cruel este capetenia troll Skullsplitter, un rival detestat de Gan'zulah si de tribul Bloodscalp.",al={"cine este Anatek","cine este seful Skullsplitter","povestea lui Anatek cel Crud"}},{q="De ce poate vorbi Gan'zulah?",a="Capul taiat al lui Gan'zulah zace scufundat in cazanul fermecat de la Grom'gol Base Camp, permitandu-i spiritului sa-si rosteasca blestemele si cererile ramase de dincolo de moarte.",al={"cum vorbeste Ganzulah","de ce vorbeste capul","cazanul lui Ganzulah"}},{q="Ce trofeu cere Gan'zulah?",a="El cere armura sparta smulsa de la Chief Ana'thek the Cruel si uciderea vanatorilor, capvanatorilor si berserkerilor Skullsplitter.",al={"de ce obiect are nevoie Ganzulah","armura rupta a lui Anatek","obiectul de predat lui Ganzulah"}},{q="Ce urmeaza dupa ce-l ajuti pe Gan'zulah?",a="Dupa ce capeteniile tribale sunt infrante, cautarile continua cu The Fate of Yenniku, pentru a afla ce s-a intamplat cu tanarul troll Darkspear.",al={"ce urmeaza dupa ce vorbesti cu ganzulah","urmatoarea misiune dupa ganzulah","continuarea dupa speaking with ganzulah"}}},fp="23,275,23.466.0,16.376.0,15.331.1,36.164.0,26.117.0,30.172.0,34.142.0,40.141.0"}
P.entries["quest:5863"] = {n="The Dunemaul Compound"}
P.entries["quest:587"] = {n="Up to Snuff",s="In Booty Bay, piratul Deeg vrea o sticla de grog si tutun fin de prizat ori de cate ori ajunge in port, dar plantele medicinale ale orasului s-au epuizat. Negustorul spune ca Bloodsail Raiders au deturnat transportul, iar Deeg vrea sa-i aduci cincisprezece portii de tutun de prizat.",h="In Booty Bay, piratul Deeg vrea o sticla de grog si tutun fin de prizat ori de cate ori ajunge in port, dar...",kw={"bloodsail","booty bay","deeg","rom","ierborist","tutun de prizat"},sec={{t="Vicii pe tarm",b="Deeg recunoaste ca viata pe mare poate sa nu fie o viata buna, dar e singura pe care o are. In port, Deeg cauta grog si tutun de prizat de calitate: obiceiuri proaste, dar orice pirat are nevoie de viciile lui. Deeg a fost zdrobit sa afle ca herbalistul din Booty Bay a ramas fara. Herbalistul spune ca Bloodsail Raiders au deturnat transportul. Deeg crede ca un aventurier fara frica i-ar putea convinge pe jefuitori sa imparta, si vrea cincisprezece portii de tutun de prizat."},{t="Multumirile lui Deeg",b="Deeg e incantat de tabac, bucuros ca a sosit chiar inainte de plecare, si iti multumeste cu caldura ca unui vechi prieten."}},faq={{q="Cine este Deeg?",a="Deeg este un pirat din Booty Bay, care cauta grog si tutun de prizat fin de fiecare data cand ajunge in port.",al={"deeg booty bay","cine da misiunea Up to Snuff"}},{q="De ce a ramas herbalistul fara tutun de prizat?",a="Potrivit ierbarului, transportul de tutun de prizat a fost capturat de Bloodsail Raiders.",al={"de ce nu exista tabac","transportul ierbarului deturnat"}},{q="Cine are tutunul de prizat?",a="Potrivit herbalistului, Bloodsail Raiders au deturnat transportul, iar Deeg spera ca vor putea fi convinsi sa-l imparta.",al={"cine a luat tutunul de prizat","tutun de prizat Bloodsail"}},{q="Cat tutun de prizat vrea Deeg?",a="Cincisprezece portii de tutun de prizat, duse lui Deeg in Booty Bay.",al={"cat tabac","cerinta pentru Up to Snuff"}}},fp="11,239,12.420.0,13.119.1,12.81.0,34.88.0,18.119.0,30.54.0"}
P.entries["quest:588"] = {n="The Fate of Yenniku",s="La Grom'gol Base Camp, capul lui Nezzliok vorbeste din cazanul clocotitor, gata sa dezvaluie ce s-a intamplat cu tanarul Troll Darkspear Yenniku. Kin'weelay sta langa cazan, asteptand sa auda cuvintele spiritului.",h="La Grom'gol Base Camp, capul lui Nezzliok vorbeste din cazanul clocotitor, gata sa dezvaluie ce s-a intamplat...",kw={"cazan","grom'gol","kin'weelay","nezzliok","yenniku","zanzil"},ang={["faction:Horde"]="Recuperarea fiului capeteniei este esentiala pentru tribul Darkspear si aliatii sai aflati la Grom'gol Base Camp."},sec={{t="Cuvinte din ceaun",b="Dupa ce ai linistit spiritele lui Gan'zulah si Nezzliok, asculti cum capul din cazanul clocotitor isi dezvaluie in sfarsit secretul. Kin'weelay sta chiar langa cazan, asteptand sa-l auda."},{t="Ce a dezvaluit capul",b="Nezzliok declara ca Yenniku este pierdut pentru clanul sau, fiind luat de witch doctor Zanzil the Outcast. Zanzil l-a legat complet pe baiat, iar numai o magie foarte puternica il poate elibera. Auzind vestea, lui Kin'weelay nu-i mai ramane decat o speranta slaba."}},faq={{q="Cine dezvaluie unde se afla Yenniku?",a="Capul lui Nezzliok vorbeste prin cazanul bolborositor si dezvaluie ce s-a intamplat cu Yenniku.",al={"cine vorbeste din cazan","cine dezvaluie Fate of Yenniku","vocea din cazan"}},{q="Cine trebuie informat despre cuvintele lui Nezzliok?",a="Kin'weelay, aflat chiar langa cazanul clocotitor de la marginea nordica a Grom'gol Base Camp, trebuie sa afle ce a dezvaluit Nezzliok.",al={"cu cine vorbesc","preda fate of yenniku","locatia lui kin'weelay"}}},fp="19,212,21.199.0,22.244.1,34.95.0,43.139.0"}
P.entries["quest:5881"] = {n="Calling in the Reserves",s="\"Calling in the Reserves\" este o misiune de curier a Horde, incredintata aventurierilor care se odihnesc la Sun Rock Retreat. Maggran Earthbinder te trimite spre sud, la marginea din Barrens, cu ordinul de a inlocui garda istovita care supravegheaza Great Lift.",h="\"Calling in the Reserves\" este o misiune de curier a Horde, incredintata aventurierilor care se odihnesc la...",kw={"calling in the reserves","great lift","grish longrunner","maggran earthbinder","stonetalon mountains","sun rock retreat","the barrens","thousand needles"},ang={["faction:Horde"]="Misiunea ilustreaza modul in care comandantii Horde isi gestioneaza fortele pe frontiera Kalimdorului, schimband santinelele pentru a mentine moralul si posturile de observatie.",["race:Tauren"]="Ajutorul dat la schimbarea santinelelor de la Great Lift sustine trecatoarea vitala ce leaga tinuturile sudice din Kalimdor de teritoriile mai vaste ale Thunder Bluff."},sec={{t="O usurare mult asteptata",b="Chiar si intr-o perioada de relativa prosperitate de dupa Third War, mentinerea garnizoanelor in centrul Kalimdor-ului pune la incercare resursele Horde-ului. La Sun Rock Retreat, in Stonetalon Mountains, Maggran Earthbinder supravegheaza logistica si bunastarea trupelor. Dandu-si seama ca soldatii cu experienta obosesc dupa nesfarsite ture de garda, Maggran trimite spre sud, la Great Lift, o scrisoare de transfer pentru tanarul Grish Longrunner, care a stat de garda departe de casa."},{t="Supravegherea liftului",b="Great Lift este principala artera inginereasca ce leaga platourile inalte din sudul Barrens de canioanele sapate de vant din Thousand Needles. Predarea scrisorii catre Grish il scapa de straja izolata si monotona asupra mecanismelor liftului, deschizandu-i calea sa se intoarca in sfarsit la familia lui si permitandu-le unor oameni noi sa-i ia locul."}},faq={{q="Cine incepe aceasta misiune?",a="Maggran Earthbinder ofera misiunea la Sun Rock Retreat, sus, in muntii Stonetalon Mountains.",al={"cel care ofera misiunea","unde se gaseste Calling in the Reserves","locatia lui maggran earthbinder"}},{q="Unde trebuie sa duc scrisoarea lui Maggran?",a="Trebuie sa duci Maggran's Reserve Letter spre sud, prin Barrens, pana la Great Lift, imensa structura din lemn cu lift, ridicata la granita ce domina Thousand Needles.",al={"locatia lui Grish Longrunner","unde este Grish","unde este Marele Lift"}},{q="De ce are Grish Longrunner nevoie de ragaz?",a="Grish a petrecut o perioada indelungata de serviciu singur, pazind mecanismele liftului. Cu ceva timp in urma, a depus o cerere oficiala de inlocuire, ca sa poata calatori acasa si sa-si viziteze familia.",al={"povestea lui Grish","de ce pleaca Grish","datoria de santinela la Great Lift"}},{q="Este necesara vreo lupta pentru aceasta misiune?",a="Nu este nevoie de lupta. Este doar o misiune de mesager, menita sa indrume calatorii spre sud, catre Thousand Needles.",al={"trebuie sa lupt","misiune pasnica","treaba de curier"}},{q="Ce factiune castiga reputatie la finalizarea acestei misiuni?",a="Ducerea scrisorii la Grish iti aduce reputatie la Thunder Bluff, reflectand prezenta si administrarea taurenilor asupra acestui drum.",al={"recompensa de reputatie","cata reputatie ofera","reputatie cu thunder bluff"}},{q="Unde duce mai departe aceasta misiune?",a="Livrarea te duce chiar in varful Great Lift, de unde poti cobori cu lifturile in canioanele din Thousand Needles, pentru a explora mai departe avanposturile Horde.",al={"urmatoarea misiune","unde sa merg dupa","misiunea de indrumare din Thousand Needles"}}},fx={["39c5e94c"]={q="De ce vrea Maggran Earthbinder ca acest lucru sa fie facut?",a="Maggran este mandru de prosperitatea Horde si de dedicarea acesteia fata de rotirea si reinnoirea trupelor. Grish Longrunner ceruse concediu cu ceva timp in urma, pentru a se intoarce la familia sa, iar Maggran are in sfarsit un razboinic de rezerva pregatit sa-l inlocuiasca la postul sau indepartat, deasupra Great Lift.",al={"de ce sa trimiti scrisoarea","scopul scrisorii de rezerva a lui Maggran","de ce sa trimiti provizii de ajutor lui Grish"}}},fp="23,234,21.467.0,17.366.0,22.102.0,36.185.0,38.180.0,44.111.0,52.134.0,32.174.0"}
P.entries["quest:589"] = {n="The Singing Crystals",s="Kin'weelay cauta o cale de a-l salva pe tanarul Yenniku din intunericul care l-a cuprins. Dupa ce afla adevarul despre soarta lui Yenniku, witch doctor-ul planuieste sa gaseasca o nestemata legendara numita Mind's Eye si te trimite sa aduni fragmente rezonante, necesare pentru a-i stapani puterea.",h="Kin'weelay cauta o cale de a-l salva pe tanarul Yenniku din intunericul care l-a cuprins.",kw={"crystalvein mine","grom'gol","basilisc ironjaw","kin'weelay","mind's eye","fragment albastru pulsator","stranglethorn","yenniku"},ang={["faction:Horde"]="Acest efort ii ajuta pe Darkspear de la Grom'gol Base Camp in lupta lor disperata de a-l recupera pe fiul pierdut al sefului Darkspear."},sec={{t="Ecourile lui Mind's Eye",b="Dupa ce afla soarta crunta a lui Yenniku, vraciul Kin'weelay cauta raspunsuri in vechile legende ale junglei. Povestile vorbesc despre Mind's Eye, o nestemata ascunsa in adancurile din Stranglethorn, inzestrata cu o putere magica uriasa. Kin'weelay crede ca piatra ar putea detine secretul eliberarii spiritului tanarului troll. In timp ce cauta impreuna cu ceilalti indrumarea spiritelor junglei pentru a-i afla locul, are nevoie de catalizatori rari pentru a stapani in siguranta vrajitoria puternica a nestematei."},{t="Pesterile Crystalvein",b="Kin'weelay te trimite spre sud-est, catre Crystalvein Mine, unde basiliskii ironjaw salasluiesc sub pamant. Trebuie sa recuperezi de la aceste creaturi trei fragmente albastre pulsande. Kin'weelay intentioneaza sa canalizeze magia innascuta a acestor pietre cantatoare intr-un ritual final, supunand vointei sale forta bruta a Mind's Eye dupa recuperarea nestematei."}},faq={{q="Cine ofera aceasta sarcina?",a="Kin'weelay, un om al leacurilor Troll stationat la Grom'gol Base Camp in Stranglethorn Vale, da aceasta misiune.",al={"cine ofera Singing Crystals","cel care da misiunea","unde incepe misiunea Singing Crystals"}},{q="De ce sunt necesare cristalele albastre pulsatorii?",a="Kin'weelay are nevoie de magia lor pentru a controla Mind's Eye, o bijuterie puternica pe care intentioneaza sa o foloseasca pentru a-l smulge pe Yenniku din ghearele fortelor intunecate care-l tin prizonier.",al={"de ce ne trebuie fragmentele albastre","la ce folosesc fragmentele","scopul fragmentului albastru pulsatoriu"}},{q="Unde pot fi gasite basiliscurile cu falci de fier?",a="Ei salasluiesc in Crystalvein Mine, situata la sud-est de Grom'gol Base Camp, sus, in varfurile de la est de Gurubashi Arena.",al={"locatia lui ironjaw basilisk","unde se afla ironjaw basilisks","unde se afla crystalvein mine"}},{q="Ce a precedat aceasta sarcina?",a="Aceasta urmeaza dupa The Fate of Yenniku, care a dezvaluit situatia cumplita a tanarului troll.",al={"cristalele cantatoare, misiune prealabila","misiunea anterioara"}},{q="Ce face Kin'weelay in timp ce aduni fragmentele?",a="Comunica cu spiritele junglei pentru a descoperi ascunzatoarea exacta a Mind's Eye si a afla ce o protejeaza.",al={"ce face kinweelay","rolul lui kinweelay"}}},fp="20,275,24.488.0,23.353.0,21.110.0,39.150.0,41.127.0,27.89.0,53.125.0"}
P.entries["quest:59"] = {n="Cloth and Leather Armor",s="In Goldshire, Cloth and Leather Armor trimite spre est un calator de incredere, sa aduca echipament. Marshal Dughan elibereaza un insemn de armura care poate fi valorificat la Sara Timberlain, in Eastvale Logging Camp. Calatoria ii duce pe recruti dincolo de podul lui Guard Thomas, ca sa obtina armura pentru apararea regatului.",h="In Goldshire, Cloth and Leather Armor trimite spre est un calator de incredere, sa aduca echipament.",kw={"marcaj pentru armura","armura din panza si piele","Eastvale","Elwynn Forest","Guard Thomas","tabara de taietori de lemne","Marshal Dughan","Sara Timberlain","armata din Stormwind"},ang={["faction:Alliance"]="Ca aparator din Alliance, vezi cum contractele locale ajuta comunitatile rurale din Elwynn sa mentina Alliance in functiune, in timp ce capitala este paralizata politic.",["profession:Tailoring"]="Ca croitor, poti vedea din ordinul militar al Sarei Timberlain ca mestesugul tesaturilor este o ocupatie militara sponsorizata oficial in regat.",["race:Human"]="Ca Human, serviciul in slujba lui Marshal Dughan si relatiile cu Sara Timberlain reflecta legaturile civice care tin unite micile gospodarii din Elwynn."},sec={{t="Insemnul maresalului",b="Guard Thomas supravegheaza trecerea de pe raul din estul Elwynn, unde murlocs si gnolls ameninta granita. Dupa ce ii duci raportul la Goldshire, Marshal Dughan iti recunoaste serviciile printr-un Stormwind Armor Marker oficial. Garnizoana din Goldshire are putine provizii, asa ca Dughan iti da un marker in loc sa ia echipament din stocurile ei. Markerul este un bon militar care consemneaza serviciile tale pentru coroana."},{t="Tesatorul din Eastvale",b="La est de podul lui Guard Thomas se afla Eastvale Logging Camp, principala exploatare forestiera din Elwynn. Sara Timberlain lucreaza acolo la o comanda oficiala a Stormwind Army pentru a confectiona echipament din stofa si piele. Armeriile centrale ale regatului sunt suprasolicitate, lasand mestesugari locali precum Sara sa echipeze trupele si cercetasii auxiliari de la granita."}},faq={{q="Ce este Stormwind Armor Marker?",a="Un Stormwind Armor Marker este un bon oficial de rechizitie militara, eliberat de ofiteri precum Marshal Dughan. Recrutii de incredere il pot folosi pentru a ridica armuri croite pe masura de la mestesugari civili angajati de armata, in loc ca ofiterii sa pastreze seturi voluminoase la posturile lor.",al={"marcaj pentru armura","voucher Stormwind","ce este marcajul"}},{q="Cine este Sara Timberlain?",a="Sara Timberlain este croitoreasa si mestesugara care locuieste la Eastvale Logging Camp. In baza unui contract cu Stormwind Army, confectioneaza echipament din tesatura si piele pentru personalul regatului si luptatorii auxiliari autorizati.",al={"Sara Timberlain","croitor din Eastvale","cine confectioneaza armura"}},{q="Unde se afla Eastvale Logging Camp?",a="Eastvale Logging Camp se afla in extremitatea estica a Elwynn Forest. De la postul de pe podul peste rau al lui Guard Thomas, urmeaza drumul spre est, prin valea impadurita, unde taietorii de lemne recolteaza lemn pentru regat.",al={"locatia Eastvale","unde se afla Eastvale","cum ajungi la Timberlain"}},{q="De ce trimite Marshal Dughan aventurieri in Eastvale?",a="Marshal Dughan ii indruma pe recruti catre Sara Timberlain, la Eastvale, deoarece nu distribuie echipament gata facut de la postul sau din Goldshire. Ii trimite pe calatori spre est dupa fapte de vitejie, ca sa poata obtine protectia necesara apararii tinutului Elwynn.",al={"de ce apare marcajul Marshal Dughan","scopul lui Dughan","de ce Eastvale"}},{q="De ce se bazeaza armata pe croitorii locali pentru provizii?",a="King Varian Wrynn este disparut, iar armata din Stormwind este solicitata peste masura, raspunzand activitatii Defias si fiarelor salbatice. Posturile locale de aparare se bazeaza in mare masura pe lucratori regionali contractati pentru a-si mentine aprovizionarea.",al={"probleme de aprovizionare in Stormwind","de ce un mestesugar local","logistica armatei"}},{q="Impotriva cui se apara Guard Thomas?",a="Guard Thomas supravegheaza granita estica a Elwynn Forest si podul, veghind impotriva murlocilor de rau, a fiarelor pradalnice si a tinuturilor salbatice periculoase de langa Redridge Mountains.",al={"dusmanii lui guard thomas","amenintari la pod","amenintari in estul Elwynn"}}},fx={ebb61187={q="De ce vrea Marshal Dughan ca acest lucru sa fie facut?",a="Marshal Dughan vrea sa-ti rasplateasca vitejia si istetimea dupa ce ai dus raportul lui Guard Thomas de la granita estica. Inmanandu-ti un ordin oficial de rechizitie pentru Sara Timberlain, se asigura ca primesti haine rezistente din stofa sau piele, pentru a continua apararea tinutului Elwynn Forest impotriva amenintarilor tot mai mari.",al={"motivul lui Marshal Dughan","de ce sa o trimita la Sara Timberlain","de ce sa dai insemnul armurii"}}},fp="23,269,19.402.0,22.335.0,33.275.0,23.210.0,35.188.0,53.231.0,54.214.0,38.162.0"}
P.entries["quest:590"] = {n="A Rogue's Deal"}
P.entries["quest:591"] = {n="The Mind's Eye",s="Kin'weelay, aflat in Grom'gol Base Camp, cauta o nestemata puternica, cunoscuta drept Mind's Eye, un artefact esential pentru salvarea tanarului Yenniku. Piatra se afla in mainile puternicului vrajitor ogre Mai'Zoth, care locuieste in adancurile movilei de ogri Mosh'Ogg Ogre Mound.",h="Kin'weelay, aflat in Grom'gol Base Camp, cauta o nestemata puternica, cunoscuta drept Mind's Eye, un artefact...",kw={"darkspear","grom'gol","kin'weelay","mai'zoth","mind's eye","mosh'ogg","musuroiul ogre","yenniku"},ang={["faction:Horde"]="Pornind de la Grom'gol Base Camp, acest efort loveste direct in fortareata ogre Mosh'Ogg, in numele Troll Darkspear.",["race:Troll"]="Recuperarea Mind's Eye este esentiala pentru eliberarea lui Yenniku, fiul conducatorului Darkspear."},sec={{t="O nestemata puternica",b="Dupa recuperarea cristalelor cantatoare, Kin'weelay isi indreapta atentia spre obtinerea lui Mind's Eye. Acest artefact puternic este singurul mijloc care poate ajuta la salvarea lui Yenniku, fiul capeteniei Darkspear. Piatra se afla insa in mainile lui Mai'Zoth, un mage ogre nemilos, a carui prezenta Kin'weelay si-o aminteste din primele zile ale tribului in jungla."},{t="Adancurile din Mosh'Ogg",b="Mai'Zoth salasluieste in adancul Mosh'Ogg Ogre Mound, la est de Grom'gol. Puterea sa magica era formidabila chiar si inainte de a intra in posesia Mind's Eye, iar piatra i-a sporit si mai mult forta. Infruntarea lui in fortareata ogre este plina de primejdii, dar smulgerea artefactului din mainile sale ramane singura speranta de a-l elibera pe tanarul troll."},{t="In Nether",b="Odata recuperata bijuteria, Kin'weelay observa ca infrangerea lui Mai'Zoth il alunga pe mage-ul ogre din lumea carnii si a oaselor in Nether. Desi amenintarea fizica a fost inlaturata, Kin'weelay e tacut ingrijorat ca Mai'Zoth ar putea incepe o noua stapanire in lumea spiritelor. Deocamdata, insa, lasa grijile deoparte, ca sa pregateasca ritualul necesar pentru Saving Yenniku."}},faq={{q="Cine detine Mind's Eye?",a="Mind's Eye se afla in posesia lui Mai'Zoth, un ogre mage care si-a facut salasul in adancul Mosh'Ogg Ogre Mound, la est de Grom'gol Base Camp.",al={"cine are minds eye","unde se afla minds eye","cine lasa in urma minds eye"}},{q="De ce are Kin'weelay nevoie de Mind's Eye?",a="Kin'weelay are nevoie de artefact pentru a indeplini un ritual, pe care il considera singura cale de a-l salva pe Yenniku, fiul pierdut al capeteniei din Darkspear.",al={"de ce avem nevoie de Ochiul Mintii","scopul Ochiului Mintii","de ce obtinem Ochiul Mintii"}},{q="In ce punct al cautarii lui Yenniku se situeaza aceasta?",a="Urmeaza dupa The Singing Crystals. Dupa ce Mind's Eye este in siguranta, calea se deschide pentru urmatorul pas, Saving Yenniku.",al={"ce misiune preceda the minds eye","misiunea anterioara minds eye","ce urmeaza dupa singing crystals"}},{q="Cine este Mai'Zoth?",a="Mai'Zoth este un mage ogre feroce, cunoscut de Kin'weelay inca din vremea in care Troll din Darkspear locuiau in jungla. Magia lui este neobisnuit de puternica, iar puterea Mind's Eye o amplifica si mai mult.",al={"cine este Maizoth","despre Maizoth","povestea lui Maizoth"}}},fp="14,250,14.387.0,22.354.0,15.405.1,29.131.0,40.141.0,48.116.0,16.197.0"}
P.entries["quest:592"] = {n="Saving Yenniku",s="Dupa ce obtine Mind's Eye, Kin'weelay il transforma intr-o nestemata speciala a sufletului pentru a-l salva pe tanarul Troll Yenniku din mainile lui Zanzil the Outcast. Vasul fermecat este conceput sa-l ameteasca pe Yenniku si sa-i captureze spiritul, permitand eliberarea lui si intoarcerea sa la Nimboya.",h="Dupa ce obtine Mind's Eye, Kin'weelay il transforma intr-o nestemata speciala a sufletului pentru a-l salva...",kw={"Aboraz","Kin'weelay","Nimboya","Saving Yenniku","piatra sufletului","Stranglethorn","Yenniku","Zanzil"},ang={["faction:Horde"]="Aventurierii Horde din Grom'gol Base Camp duc cautarea lui Nimboya pentru Yenniku pana la Zanzil, la Ruins of Aboraz.",["race:Troll"]="Pentru tribul Darkspear, eliberarea tanarului Yenniku de magia abjecta a lui Zanzil the Outcast il apropie din nou pe tanarul captiv de poporul sau."},sec={{t="Un vas pentru spirit",b="Dupa recuperarea lui Mind's Eye, Kin'weelay transforma relicva puternica intr-o nestemata magica pentru suflete. Descantecul ei dublu ii permite aventurierului sa-l ameteasca mai intai pe Yenniku, apoi sa-i aseze piatra pe cap, capturandu-i spiritul ratacit inlauntrul ei. Odata ce esenta baiatului este prinsa in nestemata, aceasta poate fi dusa in siguranta inapoi la ai sai, in Grom'gol Base Camp."},{t="Barlogul proscrisului",b="Yenniku locuieste alaturi de Zanzil the Outcast in Ruins of Aboraz, aflate de-a lungul Crystal Shore, in sudul Cape of Stranglethorn. Pentru a ajunge la tanarul cazut, trebuie sa te aventurezi pe teritoriul lui Zanzil, sa folosesti vasul confectionat pentru a-l elibera de sub controlul witch doctor-ului si sa duci nestemata plina inapoi la Nimboya."}},faq={{q="Cine furnizeaza Soul Gem pentru aceasta sarcina?",a="Kin'weelay confectioneaza si ofera Soul Gem dupa ce remodeleaza Mind's Eye recuperat, apoi te trimite sa recuperezi spiritul lui Yenniku.",al={"cine ofera Soul Gem","unde gasesc Soul Gem","cine incepe Saving Yenniku"}},{q="Unde se afla Yenniku?",a="Yenniku poate fi gasit alaturi de Zanzil the Outcast la Ruins of Aboraz, pe Crystal Shore, departe, la Cape of Stranglethorn.",al={"unde este yenniku","locatia lui yenniku","locatia Ruins of Aboraz"}},{q="Cum functioneaza Soul Gem?",a="Nestemata remodelata are o vraja cu doua efecte: este folosita mai intai pentru a-l ametit pe Yenniku, apoi este asezata direct pe capul lui pentru a-i atrage sufletul inauntru.",al={"cum se foloseste soul gem","la ce foloseste soul gem","soul gem in stranglethorn"}},{q="Cine primeste Filled Soul Gem dupa ce Yenniku este in siguranta?",a="Dupa ce sufletul lui Yenniku este prins in siguranta in nestemata, aceasta trebuie dusa la Nimboya, inapoi la Grom'gol Base Camp.",al={"unde predau soul gem-ul plin","cine primeste gemul","unde il duc pe Yenniku"}}},fp="14,266,23.356.0,18.342.0,40.130.0,25.128.0,27.141.0,57.113.0"}
P.entries["quest:5921"] = {n="Moonglade"}
P.entries["quest:5922"] = {n="Moonglade",s="Aceasta misiune marcheaza prima intalnire a unui tanar druid Tauren cu Moonglade, sanctuarul sacru al druidismului Cenarion. Indrumat de Turak Runetotem in Thunder Bluff, initiatul invata sa strabata lumea treaza pentru a intra in comuniune directa cu stravechii pastratori ai naturii.",h="Aceasta misiune marcheaza prima intalnire a unui tanar druid Tauren cu Moonglade, sanctuarul sacru al...",kw={"forma de urs","cenarius","dendrite starblaze","moonglade","nighthaven","remulos","teleportare la moonglade","turak runetotem"},ang={["class:Druid"]="Acest rit de trecere face legatura intre credintele tribale traditionale si principiile mai largi ale Cenarion Circle, deschizand calea catre forme stravechi de schimbare a infatisarii.",["faction:Horde"]="Desi tensiunile mocnesc in Kalimdor, druizii Horde considera Moonglade unul dintre putinele locuri din lume unde se pot intalni pasnic cu fratii lor Night Elf.",["race:Tauren"]="Pentru initiatii tauren, sosirea in Moonglade este o trezire profunda: dovada ca legaturile lor stravechi cu Earth Mother se armonizeaza pe deplin cu invataturile lui Cenarius."},sec={{t="Un refugiu sacru, dincolo de factiuni",b="Moonglade ramane deoparte de politica zbuciumata a Kalimdorului. Adapostita sub ramurile copacilor primordiali si pazita de Keeper Remulos, fiul lui Cenarius, aceasta vale straveche este un refugiu neutru pentru toti cei care urmeaza calea naturii. Fie elf al noptii, fie tauren, orice druid care intra in Nighthaven este primit ca egal, sub ocrotirea atemporala a Cenarion Circle."},{t="Saltul peste Kalimdor",b="Pentru a-ti sustine dezvoltarea spirituala si martiala, Turak Runetotem te invata o vraja de transport unica, legata de vale. Evocand legatura mistica dintre druizi si lumea naturala, strabati sute de leghe intr-o clipa. Acest sanctuar va fi atat o sala de studiu, cat si un refugiu trainic de-a lungul calatoriei tale."},{t="Trezirea ursului",b="La sosirea in Nighthaven, il intalnesti pe Dendrite Starblaze, un druid night elf in varsta, care asteapta noi discipoli. Sub indrumarea sa incepe prima incercare adevarata a chemarii tale: sa cauti perspectiva ursului. Pentru a imbratisa caile Ghearei, trebuie sa-ti dovedesti puterea, curajul si echilibrul in fata lui Great Bear Spirit."}},faq={{q="De ce pot Tauren sa viziteze un refugiu Night Elf precum Moonglade?",a="Moonglade este un teritoriu sacru suveran aflat sub autoritatea Cenarion Circle, indrumat de Keeper Remulos. In granitele sale, devotamentul fata de natura si Cenarius trece cu totul inaintea conflictului dintre Horde si Alliance, permitandu-le druizilor Tauren si Night Elf sa se antreneze si sa locuiasca impreuna in pace.",al={"de ce sunt Tauren in Moonglade","Horde poate intra in Moonglade","este Moonglade neutru"}},{q="Cine este Dendrite Starblaze?",a="Dendrite Starblaze este un druid night elf batran, aflat in asezarea Nighthaven. El indruma initiatii proaspat sositi din ambele rase si le organizeaza primele incercari, pe masura ce se armonizeaza cu stravechile aspecte animale.",al={"dendrite starblaze","cine este dendrite","Night Elf care da misiuni"}},{q="Cine este Keeper Remulos?",a="Keeper Remulos este un Puternic Pazitor al Crangului si fiul semizeului Cenarius. El este aparatorul suprem al Moonglade, supravegheaza barrowurile sacre unde druidii adormiti hiberneaza si vegheaza ca sfintenia vaii sa ramana neatinsa.",al={"Keeper Remulos","Remulos din Moonglade","cine protejeaza Moonglade"}},{q="Ce se intampla dupa ce ajungi in Moonglade?",a="O discutie cu Dendrite Starblaze iti incepe incercarea alaturi de Great Bear Spirit. Acesta te trimite la salasul spiritului, in nord-vestul regiunii Moonglade, pentru a deprinde forta trupului si taria inimii, primul pas spre dezvaluirea secretelor formei de urs.",al={"ce fac mai departe","sirul de misiuni cu ursul","dupa misiunea din Moonglade"}},{q="Cum functioneaza Teleport: Moonglade in contextul lore-ului?",a="Druizii impletesc energiile naturale ale liniilor ley cu legatura lor spirituala cu Cenarion Circle pentru a strabate instantaneu distanta dintre locul in care se afla si inima din Moonglade. Acest tinut le serveste drept ancora spirituala, permitandu-le sa se intoarca pentru instruire si alinare ori de cate ori sunt chemati.",al={"teleportarea in Moonglade in lore","vraja de teleportare a druidului"}},{q="Unde se afla Turak Runetotem?",a="Turak Runetotem locuieste in varful lui Elder Rise, in Thunder Bluff, indrumandu-i pe tinerii tauren care raspund chemarii salbaticiei inainte sa-i trimita mai departe spre Moonglade.",al={"locatia lui turak runetotem","unde se afla turak"}}},fx={cadcf30c={q="De ce te trimite Turak Runetotem la Moonglade?",a="Iti incepi pregatirea in caile Ghearei, invatand mai ales sa comunici cu aspectul ursului si sa-l imbratisezi. Turak Runetotem nu te poate indruma de unul singur, din Thunder Bluff, prin aceasta initiere sacra; trebuie sa strabati tinuturile sacre din Moonglade si sa inveti sub indrumarea lui Dendrite Starblaze, pentru a lega o legatura autentica cu spiritele salbatice ale naturii.",al={"de ce ma trimite Turak in Moonglade","motivul lui Turak Runetotem","de ce sa merg in Moonglade"}},["979ecc1c"]={q="De ce trebuie sa faci pelerinajul la Moonglade personal?",a="Calea druidica cere o comuniune spirituala personala. Moonglade este sanctuarul unde druizii Cenarion comunica direct cu spiritele stravechi ale padurii si cu invataturile lui Cenarius. Imbratisarea spiritului ursului este o incercare intima si personala a caracterului si a magiei naturii, pe care niciun batran sau mentor n-o poate trece in locul tau.",al={"de ce trebuie sa merg la Moonglade","de ce nu ma poate antrena Turak aici","de ce eu, Moonglade"}}},fp="9,253,29.367.0,24.339.0,18.320.1,54.310.0,26.218.0,22.251.0,38.257.0,44.275.0,33.155.0"}
P.entries["quest:5923"] = {n="Heeding the Call",s="Heeding the Call marcheaza momentul in care un ucenic druid elf al noptii atrage atentia conducerii de rang inalt a Cenarion Circle. Convocat la Darnassus pentru a-l intalni pe Mathrengyl Bearwalker, tanarul initiat porneste pe calea sacra spre stapanirea primei sale intrupari animale, ursul.",h="Heeding the Call marcheaza momentul in care un ucenic druid elf al noptii atrage atentia conducerii de rang...",kw={"bear form","cenarion enclave","darnassus","denatharion","misiune de druid","fandral staghelm","heeding the call","kal","mathrengyl bearwalker","theridran"},ang={["class:Druid"]="Aceasta misiune marcheaza trecerea ta oficiala de la simplu novice, care tese vraji de radacina si manie, la un adevarat schimbator de forma ce invata tainele spiritelor din Kalimdor.",["faction:Alliance"]="Faptul ca poti primi aceasta misiune de la Theridran, in Stormwind, arata o coordonare tot mai stransa intre kaldorei din Teldrassil si aliatii lor umani din est.",["race:NightElf"]="Raspunzand chemarii, ajungi in inima Cenarion Enclave din Darnassus, cinstind traditia Kaldorei, veche de milenii, sub privirea vigilenta a cercului lui Fandral Staghelm."},sec={{t="O chemare din partea enclavei",b="Druizii novici care isi perfectioneaza mestesugul prin Teldrassil - sau studiaza departe de casa, in tinuturi indepartate precum Stormwind - primesc in cele din urma o convocare personala. Instructori precum Kal din Dolanaar, Denatharion din Darnassus sau Theridran, de peste Great Sea, le aduc vestea ca Mathrengyl Bearwalker doreste sa le supravegheze personal pregatirea. Fiind asistentul direct al lui Arch Druid Fandral Staghelm, Mathrengyl este unul dintre cei mai respectati si mai eruditi mentori ai elfilor noptii, iar atentia lui este un semn limpede ca un ucenic este pregatit pentru incercari adevarate."},{t="Calea ursului",b="Ajungand la Mathrengyl, la etajul superior al resedintei impunatoare a lui Fandral Staghelm din Cenarion Enclave, se deschide calea spre mistere mai adanci. Pentru a sluji cum se cuvine natura, un druid trebuie sa invete sa intruchipeze fapturile vii, nu doar sa le observe. Mathrengyl ii intampina pe candidati cu vestea ca prima lor mare incercare va fi sa imbratiseze puterea, rezistenta si spiritul ursului - o calatorie care ii va duce mult dincolo de Teldrassil, pana la stravechi meleaguri sacre."}},faq={{q="Cine ma trimite in aceasta misiune?",a="Poti primi aceasta chemare de la mai multi antrenori de druizi, dupa ce ai acumulat suficienta experienta: Kal din Dolanaar, Denatharion din Darnassus sau Theridran din cartierul Park al orasului Stormwind City.",al={"cel care ofera misiunea","cine incepe aceasta misiune","de unde pot lua aceasta misiune"}},{q="Cine este Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker este un druid night elf cu rang inalt si asistentul direct al Arh Druidului Fandral Staghelm. Locuieste in Cenarion Enclave din Darnassus si este unul dintre cei mai importanti instructori pentru initiatii care cauta sa stapaneasca formele animalice.",al={"mathrengyl","cine este mathrengyl","bearwalker"}},{q="Unde il pot gasi pe Mathrengyl Bearwalker in Darnassus?",a="Se afla in Cenarion Enclave, in cartierul de nord-vest din Darnassus. Il vei gasi asteptand la etajul al doilea al copacului viu urias care serveste drept sanctuar pentru Arch Druid Fandral Staghelm.",al={"locatia lui Mathrengyl","unde este Mathrengyl","locatia Cenarion Enclave"}},{q="La ce instruire duce aceasta misiune?",a="Raportarea la Mathrengyl marcheaza inceputul incercarii sacre a formei Bear Form. El te va indruma prin Kalimdor catre sanctuarul sacru din Moonglade, unde vei invata forta trupului si a spiritului necesara pentru a intra in comuniune cu Great Bear Spirit.",al={"ce urmeaza","ce primesc","urmatoarea misiune"}},{q="De ce pot primi aceasta misiune in Stormwind?",a="Emisarii si druizii night elf, precum Theridran, pastreaza un sanctuar in Park din Stormwind pentru a-i ajuta pe aliatii din Alliance. Daca un tanar druid calatoreste peste mare prin Elwynn Forest, Theridran ii poate transmite chemarea de intoarcere in Teldrassil.",al={"misiune din Stormwind","Theridran","pot obtine aceasta misiune in Stormwind"}},{q="De ce este forma de urs primul aspect animalic predat?",a="Druizii cred ca natura are nevoie atat de aparatori, cat si de ocrotitori. Ursul intruchipeaza rezistenta neimblanzita, forta fizica si curajul de a apara echilibrul de primejdii, fiind astfel aspectul fundamental pentru supravietuirea incercarilor din salbaticia periculoasa.",al={"de ce forma de urs","poveste despre ursul druidului"}}},fx={["7976a971"]={q="De ce sunt trimis la Mathrengyl Bearwalker?",a="Instructorii tai druizi recunosc ca ucenicia de baza s-a incheiat si ca esti pregatit pentru o instruire avansata. Mathrengyl Bearwalker slujeste direct sub Arch Druid Fandral Staghelm si supravegheaza ritualul esential al comuniunii cu marele spirit al ursului. Instructorii te indruma catre el, pentru ca tu sa incepi sa inveti schimbarea formei si sa-ti descatusezi taria trupului si a inimii necesara pentru a proteja echilibrul naturii.",al={"de ce Mathrengyl","de ce sa raspund chemarii","motivul pentru care sa raspund chemarii","de ce ma trimite Denatharion"}},fad6f2dc={q="De ce ma vrea Mathrengyl Bearwalker pe mine si nu pe altcineva?",a="Aceasta nu este o sarcina administrativa sau de aparare militara, ci un ritual personal de trecere, propriu drumului tau ca druid aspirant. Mathrengyl Bearwalker ii cauta pe druizii tineri care au potentialul de a canaliza spiritul salbaticiei. Doar tu poti comunica cu spiritele protectoare si trece prin incercarile spirituale necesare pentru a-ti stapani prima forma animala.",al={"de ce eu, sa raspund chemarii","de ce m-au ales pe mine","de ce are Mathrengyl nevoie de mine"}}},fp="16,278,26.560.0,20.479.0,27.197.0,29.235.0,52.204.0,38.222.0,38.246.0,52.241.0"}
P.entries["quest:5925"] = {n="Heeding the Call",s="Heeding the Call este o chemare esentiala care il indruma pe un ucenic druid night elf spre Darnassus. Mathrengyl Bearwalker, ajutorul direct al arhidruidului Fandral Staghelm, il cheama pe initiat sa-si continue pregatirea si sa se pregateasca pentru incercarile ursului.",h="Heeding the Call este o chemare esentiala care il indruma pe un ucenic druid night elf spre Darnassus.",kw={"forma de urs","cenarion enclave","darnassus","antrenament Druid","fandral staghelm","heeding the call","mathrengyl bearwalker","teldrassil"},ang={["class:Druid"]="Aceasta convocare marcheaza trecerea ta de la pregatirea de novice la o comuniune mai profunda cu formele naturii, incepand chiar sub indrumarea asistentului personal al arhidruidului Staghelm.",["faction:Alliance"]="Druizii Night Elf care raspund chemarii Cenarion in Darnassus intaresc vechile temelii magice si naturale ale Alliance in Kalimdor.",["race:NightElf"]="Avand loc in inima orasului Darnassus, la Cenarion Enclave, aceasta convocare subliniaza cat de adanc este inradacinat druidismul Cenarion in societatea Kaldorei."},sec={{t="O chemare la Darnassus",b="Cand un tanar druid isi incheie pregatirea de baza printre ramurile lui Teldrassil, soseste vestea ca Mathrengyl Bearwalker doreste sa-i vorbeasca personal. Mathrengyl nu este un mentor oarecare - el este asistentul direct al arhidruidului Fandral Staghelm si se numara printre cele mai venerabile si intelepte figuri din Cenarion Enclave. Aceasta chemare arata ca pregatirea novicei este gata sa capete un scop mai amplu, trecand dincolo de paza elementara spre artele sacre mai profunde ale naturii."},{t="Calea ursului",b="Calatoria duce direct la Cenarion Enclave din Darnassus, urcand pana la etajul al doilea al marelui copac al arhidruidului Staghelm. Intampinandu-l pe initiat, Bearwalker afirma ca fiecare adept care raspunde chemarii lui Cenarius trebuie sa cinsteasca plantele si fiarele, atat ca insotitori, cat si ca fiinte aflate in grija sa. A te dedica pastrarii echilibrului naturii cere mai mult decat contemplatie tacuta; inseamna sa inveti caile ursului salbatic si sa-ti stapanesti cu adevarat puterea trupului si a inimii."}},faq={{q="Cine este Mathrengyl Bearwalker?",a="Mathrengyl Bearwalker este un druid venerabil si intelept, care ii slujeste drept asistent direct arhidruidului Fandral Staghelm. El supravegheaza instruirea avansata a druizilor promitatori din Darnassus.",al={"cine vrea sa vorbeasca cu mine","cine este mathrengyl","cine este mathrengyl bearwalker"}},{q="Unde se afla Mathrengyl Bearwalker?",a="El locuieste la etajul al doilea al copacului lui Fandral Staghelm, in Cenarion Enclave din Darnassus, unde se intrunesc membrii de rang inalt ai Cenarion Circle din Teldrassil.",al={"unde il gasesc pe Bearwalker","unde este Mathrengyl","locatia Cenarion Enclave"}},{q="De ce am fost chemat sa vorbesc cu Mathrengyl?",a="Esti chemat fiindca ti-ai incheiat pregatirea de baza, iar calea ta de druid este gata sa se extinda. Mathrengyl isi asuma personal sarcina de a te indruma spre disciplinele mai profunde ale naturii.",al={"de ce sunt chemat","la ce foloseste aceasta misiune","de ce sa raspund chemarii"}},{q="Ce voi invata de la Mathrengyl Bearwalker?",a="Mathrengyl iti incepe instruirea in caile ursului, invatandu-te sa fii puternic trupeste si sufleteste pentru a apara echilibrul naturii.",al={"ce ma va invata Mathrengyl","ce invat mai departe","ce forma primesc"}},{q="Ce inseamna sa te numeri printre 'copiii lui Cenarius'?",a="Cenarius este semizeul protector al naturii si invatatorul primilor druizi. Adeptii sai considera ca toti druizii au datoria comuna de a proteja plantele si vietuitoarele salbatice din Azeroth.",al={"cine este Cenarius","semnificatia copiilor lui Cenarius"}},{q="Care este copacul lui Fandral Staghelm?",a="Este marele copac viu, scobit, din Cenarion Enclave din Darnassus, unde arhidruidul Fandral Staghelm si cercul sau restrans conduc treburile Cenarion in tot Teldrassil.",al={"in ce copac se afla","locatia copacului lui fandral"}}},fp="16,252,22.478.0,20.462.0,29.186.0,39.166.0,44.190.0,45.143.0,51.180.0,32.170.0"}
P.entries["quest:5926"] = {n="Heeding the Call",s="Heeding the Call marcheaza chemarea unui druid novice la Elder Rise, in Thunder Bluff, pentru indrumare individuala avansata. Transmisa de hangi si rude din asezarile Horde, chemarea ii indruma pe aspirantii la metamorfoza catre Turak Runetotem. Intalnirea declanseaza probele sacre necesare pentru a stapani forma si spiritul ursului.",h="Heeding the Call marcheaza chemarea unui druid novice la Elder Rise, in Thunder Bluff, pentru indrumare...",kw={"forma de urs","bloodhoof village","cenarion circle","druid","elder rise","gennia runetotem","heeding the call","thunder bluff","turak runetotem"},ang={["class:Druid"]="Aceasta misiune este primul pas vital pe calea stapanirii formelor animale, inceputul calatoriei sacre spre dobandirea spiritului si a tariei ursului.",["faction:Horde"]="Hangiii din tinuturile orcilor si ale taurenilor contribuie la primirea chemarii de catre druizii in devenire, cultivand legatura vitala a Horde cu salbaticia.",["race:Tauren"]="Pentru tauren, studiul sub indrumarea lui Turak in Elder Rise reafirma legatura lor ancestrala profunda cu Cenarion Circle si cu spiritele salbatice din Kalimdor."},sec={{t="O vorba la han",b="Vestea se raspandeste repede prin campiile din Mulgore si pe drumurile prafuite din Orgrimmar. Fie ca o aud de la Innkeeper Gryshka, printre orci, de la Innkeeper Pala din Thunder Bluff sau de la Gennia Runetotem din Bloodhoof Village, mesajul e acelasi: Turak Runetotem a observat primele tale progrese. Cenarion Circle nu-i cheama usor pe practicanti, iar aceasta invitatie arata ca zilele tale de cules ierburi si de invatare a vrajilor de baza ti-au adus ocazia unei legaturi mai profunde cu spiritele salbatice ale naturii."},{t="Cercul de pe Elder Rise",b="Turak Runetotem este asistentul arhidruidului Hamuul Runetotem si ii indruma pe tinerii Tauren spre datoria lor ancestrala in cortul mare al Cenarion de pe Elder Rise. Primindu-i pe initiati intr-o intelegere mai ampla a mostenirii lui Cenarius, Turak ii invata ca animalele si plantele sunt deopotriva aliati si responsabilitati sacre. Intalnirea cu el este pragul de inceput al ritualului: trecerea dincolo de indrumarea de baza, catre incercarile trupului si sufletului necesare pentru a intra in legatura directa cu Great Bear Spirit."}},faq={{q="Cine ma trimite sa vorbesc cu Turak Runetotem?",a="Chemarea poate fi transmisa de mai multe persoane de contact: Gennia Runetotem din Bloodhoof Village, Innkeeper Pala din Thunder Bluff sau Innkeeper Gryshka din Orgrimmar. Fiecare a fost anuntat ca Turak doreste sa-ti indrume personal pregatirea.",al={"cine ofera misiunea Heeding the Call","cine da misiunea Heeding the Call","de unde incep Heeding the Call"}},{q="Unde il pot gasi pe Turak Runetotem?",a="Turak locuieste pe Elder Rise din Thunder Bluff. Isi are casa in cortul proeminent al Cenarion Circle, aproape de ceilalti mentori druizi ai orasului.",al={"locatia lui Turak Runetotem","unde este turak","cum sa-l gasesti pe turak"}},{q="De ce este aceasta convocare atat de importanta pentru tinerii druizi?",a="Aceasta chemare da startul probelor tale oficiale de metamorfoza. Turak Runetotem te indruma spre un loc sacru din Moonglade, unde poti invata calea ursului si dobandi prima forma animala.",al={"de ce am nevoie de Turak","care este scopul acestei misiuni","misiune Druid de nivel 10 pentru Horde"}},{q="Cine este Turak Runetotem in ierarhia Cenarion?",a="Turak este un druid tauren respectat si un asistent de incredere al arhidruidului Hamuul Runetotem. Este cunoscut pentru rabdarea si intelepciunea cu care ii invata pe tinerii initiati despre echilibrul naturii.",al={"cine este Turak Runetotem","povestea lui Turak"}},{q="Pot accepta aceasta misiune si celelalte clase?",a="Nu. Aceasta misiune le este oferita exclusiv druidilor care au ajuns la al zecelea sezon de experienta si reprezinta ritul lor de trecere catre schimbarea formei.",al={"Heeding the Call este doar pentru Druid","poate Shaman sa faca aceasta misiune"}},{q="Ce se intampla dupa ce vorbesc cu Turak?",a="Turak te primeste in slujba lui Cenarius si te trimite la sanctuarul druidic sacru din Moonglade, sa-l cauti pe Dendrite Starblaze si sa incepi comuniunea cu Great Bear Spirit.",al={"ce urmeaza dupa Heeding the Call","urmatoarea misiune dupa turak"}}},fx={["309dc9df"]={q="De ce ma trimit la Turak Runetotem?",a="Vestea a ajuns la asezari ca Turak Runetotem, ajutorul Arhidruidului, cauta druizi tineri promitatori care au nevoie de invataturi mai profunde. Cei care dau misiunea sunt doar mesageri, ca sa te asiguri ca nu ratezi chemarea lui. Turak s-a oferit sa te instruiasca personal, marcand clipa in care pregatirea ta rudimentara infloreste intr-o adevarata comuniune cu natura si cu caile salbaticiei.",al={"de ce sa ma trimita la Turak","de ce vrea Gennia sa vorbesc cu Turak","de ce sa-l vad pe Turak Runetotem"}}},fp="16,326,17.516.0,24.497.0,43.242.0,33.149.0,50.184.0,49.181.0,36.151.0,36.176.1"}
P.entries["quest:5929"] = {n="Great Bear Spirit",s="Great Bear Spirit este o misiune fundamentala de indrumare pentru druizii din Moonglade, care ii trimite pe initiati sa caute un spirit stravechi si nobil in salbaticia din nord-vest. Intrarea in comuniune cu spiritul le transmite intelepciunea esentiala despre natura si puterea ursului, marcand un pas crucial in pregatirea spirituala si razboinica a unui druid.",h="Great Bear Spirit este o misiune fundamentala de indrumare pentru druizii din Moonglade, care ii trimite pe...",kw={"forma de urs","Dendrite Starblaze","misiune de Druid","Great Bear Spirit","Moonglade","Nighthaven"},ang={["class:Druid"]="Comuniunea cu Great Bear Spirit este un rit de trecere esential pentru fiecare druid, oferindu-i intelepciunea naturii si temelia spirituala necesare pentru a dobandi rezistenta ursului."},sec={{t="Nobilul mentor din Moonglade",b="Great Bear Spirit salasluieste in tinuturile salbatice din nord-vestul Moonglade, departe de cararile linistite din Nighthaven. Respectat ca mentor nobil si stravechi, spiritul este primul indrumator al tuturor initiatilor care cauta sa inteleaga esenta naturala a ursului. Cererea binecuvantarii si intelepciunii sale este o traditie sacra impartasita de fiecare druid care urmeaza calea salbaticiei."},{t="Un ritual de concentrare primordiala",b="Indrumati de Dendrite Starblaze in Nighthaven, tinerii druizi calatoresc spre dealuri pentru a se infatisa spiritului. Comuniunea cu Great Bear Spirit le insufla intelepciune primordiala si constientizarea puterii naturii. La intoarcere, Dendrite le pune la incercare concentrarea, observand ca, desi intalnirea le da putere bruta si intentie constienta, druizii trebuie apoi sa invete sa-si indrepte acea forta interioara spre indatoririle de zi cu zi."}},faq={{q="Unde poate fi gasit Great Bear Spirit?",a="Great Bear Spirit salasluieste in tinuturile nord-vestice din Moonglade, departe de asezarea Nighthaven, la marginile mai salbatice ale sanctuarului sacru.",al={"unde este spiritul ursului","gaseste spiritul ursului in Moonglade","locatia spiritului ursului"}},{q="Cine trimite druizii sa-l caute pe Great Bear Spirit?",a="Dendrite Starblaze, un druid batran stationat in Nighthaven, ii indruma pe initiati sa intre in comuniune cu spiritul, ca parte a pregatirii lor naturale.",al={"cine te trimite la Spiritul Ursului","rolul lui Dendrite Starblaze","cel care ofera misiunea Spiritul Ursului"}},{q="Ce este Great Bear Spirit?",a="Great Bear Spirit este venerat ca o fiinta inteleapta si nobila, care le slujeste tuturor druidilor practicanti drept calauza, indrumator si mentor in intelegerea primordiala a ursului.",al={"ce este spiritul ursului","povestea spiritului ursului","cine este Marele Spirit al Ursului"}},{q="De ce trebuie druizii sa intre in comuniune cu Great Bear Spirit?",a="Initiatii cauta spiritul pentru a afla esenta firii ursului, absorbindu-i forta bruta, rezistenta si intelepciunea inainte de a se intoarce ca sa canalizeze aceste insusiri in mestesugul lor.",al={"de ce sa vorbesti cu spiritul ursului","scopul misiunii spiritului ursului","ce afli de la spiritul ursului"}},{q="Ce se intampla dupa ce Great Bear Spirit este multumit?",a="Dupa ce comunica cu spiritul, initiatii se intorc la Dendrite Starblaze in Nighthaven, care le recunoaste intelegerea nou dobandita si ii pregateste sa stapaneasca si sa canalizeze acea putere.",al={"ce se intampla dupa spiritul ursului","Dendrite dupa spirit","dupa vizita la spiritul ursului"}},{q="Trebuie ca toti druizii sa caute intelepciunea spiritului?",a="Fiecare druid trebuie, mai devreme sau mai tarziu, sa caute sfatul lui Great Bear Spirit, deoarece comuniunea cu spiritul este considerata un pas fundamental pentru armonizarea cu formele animalelor si cu puterea naturii.",al={"viziteaza toti druizii spiritul ursului","este obligatoriu spiritul ursului","cine viziteaza spiritul ursului"}}},fp="17,335,29.379.0,22.422.0,41.164.0,51.139.0,30.170.0,51.184.0,54.186.0,47.174.0"}
P.entries["quest:593"] = {n="Filling the Soul Gem",s="In adancul junglei din Stranglethorn Vale, se incearca salvarea tanarului troll Yenniku. Cum baiatul este prins intr-o transa, se scoate o piatra sufleteasca pregatita pentru a-i captura spiritul.",h="In adancul junglei din Stranglethorn Vale, se incearca salvarea tanarului troll Yenniku.",kw={"saving yenniku","nestemata sufletului","stranglethorn vale","troll","yenniku"},sec={{t="O transa in jungla",b="Dupa eforturile de a-l salva pe Yenniku, te afli fata in fata cu tanarul Troll in Stranglethorn Vale. Si-a pierdut mintea, ratacind cu totul intr-un alt loc, in timp ce sta nemiscat in fata ta. Singura cale de a continua este sa folosesti nestemata vrajita, pregatita special pentru a-i pastra esenta."},{t="Vasul",b="Cand apesi nestemata pe fruntea lui Yenniku, spiritul lui este atras direct in piatra. Pe masura ce esenta ii este absorbita, trupul i se cutremura si se prabuseste, devenind o carcasa goala, lipsita de minte."}},faq={{q="In ce stare se afla Yenniku cand ajungi la el?",a="Yenniku sta impietrit si nu raspunde, cu gandurile departe de imprejurimile sale fizice.",al={"starea lui yenniku","ce are yenniku","yenniku este naucit"}},{q="Ce obiect se foloseste asupra lui Yenniku?",a="O nestemata sufleteasca adusa din Stranglethorn Vale este folosita pentru a interactiona cu tanarul troll.",al={"ce obiect este necesar","nestemata folosita asupra lui yenniku","obiectul lui yenniku"}},{q="Ce a precedat acest moment?",a="Aceasta intalnire continua direct evenimentele din Saving Yenniku, in jungla din Stranglethorn Vale.",al={"misiunea anterioara","conditie prealabila pentru Filling the Soul Gem","ce duce la aceasta"}}},fp="20,192,22.287.0,10.182.1,48.99.0,29.84.0,29.98.0"}
P.entries["quest:5931"] = {n="Back to Darnassus"}
P.entries["quest:5932"] = {n="Back to Thunder Bluff",s="\"Back to Thunder Bluff\" este un rit de initiere esential pentru tinerii druizi tauren care se intorc din poienile sacre ale Moonglade. Dupa ce a comunicat cu Great Bear Spirit, novicele este trimis de Dendrite Starblaze inapoi la Elder Rise, pentru a-si continua pregatirea sub indrumarea lui Turak Runetotem.",h="\"Back to Thunder Bluff\" este un rit de initiere esential pentru tinerii druizi tauren care se intorc din...",kw={"inapoi la Thunder Bluff","forma de urs","Dendrite Starblaze","Elder Rise","marele spirit al ursului","Moonglade","Nighthaven","Turak Runetotem"},ang={["class:Druid"]="Aceasta etapa a calatoriei tale leaga sanctuarul stravechi si izolat din Moonglade de inaltimile batute de vant din Thunder Bluff, marcand progresul tau pe Calea Ghearei.",["faction:Horde"]="Cunostintele aduse inapoi din Moonglade asigura prezenta unor puternici aparatori schimbatori de forma in randurile Horde, pe campiile din Kalimdor.",["race:Tauren"]="Intoarcerea la Elder Rise aduce acasa intelepciunea spiritelor stravechi, spre binele si protectia triburilor tale din Mulgore."},sec={{t="O fratie unita printr-un pod",b="Moonglade se afla departe de dezbinarea dintre factiunile lumii muritorilor, fiind un sanctuar unde practicantii magiei naturii night elf si tauren se aduna in cadrul Cenarion Circle. Dupa comuniunea cu Great Bear Spirit, indrumatorul night elf Dendrite Starblaze ii trimite pe tinerii tauren inapoi la semenii lor. Desi night elves ii privesc adesea pe tauren ca pe niste novice in invataturile formalizate ale lui Cenarius, Starblaze recunoaste cu usurinta intelepciunea profunda si echilibrul pastrat de Turak Runetotem."},{t="Intoarcerea la faleze",b="Dupa ce urca din nou pe inaltimile intinse din Elder Rise, in Thunder Bluff, novicele se infatiseaza inaintea lui Turak Runetotem, transformat. Comunicarea cu spiritele totemice stravechi, precum Great Bear Spirit, este adanc inradacinata in cultura taurenilor, insa urmarea Caii Ghearei este un angajament serios. Odata stabilita legatura spirituala, Turak il pregateste pe druid sa-si puna in practica noua forta si rezistenta."}},faq={{q="De ce invata un night elf un tauren in Moonglade?",a="Cenarion Circle este neutru si dedicat in intregime ocrotirii naturii. In Moonglade, ostilitatea politica dintre Horde si Alliance este lasata deoparte, astfel incat batrani Night Elf precum Dendrite Starblaze sa-i poata indruma pe druizii tauren aflati la inceput de drum.",al={"dendrite starblaze horda","de ce mentor Night Elf","cercul Cenarion tauren"}},{q="Cine este Turak Runetotem?",a="Turak Runetotem este un druid tauren respectat, unul dintre asistentii Arhidruidului, aflat in Elder Rise din Thunder Bluff. El supravegheaza pregatirea tinerilor tauren care vor sa urmeze calea naturii si a ghearei si este o veriga importanta de legatura cu Cenarion Circle.",al={"rolul lui Turak Runetotem","liderul druidilor din Elder Rise"}},{q="Ce a facut tanarul druid chiar inainte de aceasta misiune?",a="Inainte de a fi trimis inapoi in Mulgore, initiatul a calatorit la Moonglade pentru a-l cauta pe stravechiul Great Bear Spirit si a intra in comuniune cu el, primindu-i binecuvantarea si invatand esenta spirituala a formei de urs.",al={"ce misiune a precedat Back to Thunder Bluff","misiunea Great Bear Spirit"}},{q="Cum se intorc tinerii druizi din Moonglade la Thunder Bluff?",a="Bunthen Plainswind, aflat in sud-vestul Nighthaven, ofera servicii specializate de maestru de zbor, menite sa-i duca in siguranta pe druizii tauren inapoi la Thunder Bluff dupa ritualurile lor.",al={"cum ma intorc din moonglade","zborul de intoarcere din moonglade"}},{q="Ce urmeaza in pregatirea druidului?",a="La intoarcere, Turak Runetotem ii da initiatului misiunea 'Body and Heart', trimitandu-l sa treaca printr-o incercare fizica la Moonkin Stone, acolo unde Barrens se intalneste cu Mulgore. Astfel, initiatul dovedeste ca poate canaliza puterea spiritului si o poate transforma in adevarata forma de bestie.",al={"urmatoarea misiune de druid","dupa intoarcerea la Thunder Bluff"}},{q="De ce spune Dendrite Starblaze ca Tauren sunt 'tineri in caile lui Cenarius'?",a="Desi legendele tauren amintesc de vechea comuniune cu Cenarius din zorii lumii, druismul Cenarion organizat a fost dezvoltat si mentinut de night elf vreme de peste zece mii de ani. Taurenii si-au reluat abia de curand studiile organizate sub indrumarea Cenarion Circle.",al={"sunt taurenii druizi noi","istoria druizilor tauren si Cenarius"}}},fx={["9396c536"]={q="De ce te trimite Dendrite Starblaze inapoi la Thunder Bluff?",a="Prima ta comuniune cu Great Bear Spirit din Moonglade a fost doar pasul initial al trezirii tale. Dendrite Starblaze stie ca punerea in practica a lectiilor salbaticiei necesita indrumare nemijlocita din partea propriului tau mentor. El ii incredinteaza urmatoarea etapa a instruirii tale lui Turak Runetotem, un druid tauren care paseste in deplin echilibru, ca sa-ti poti dovedi vrednicia si sa primesti puterea neclintita a ursului.",al={"de ce sa-l trimit la Turak","motivul lui Dendrite Starblaze","de ce sa ma intorc la Thunder Bluff"}}},fp="21,276,20.491.0,20.427.0,51.262.0,23.261.0,52.198.0,64.183.0,40.244.0,72.261.0"}
P.entries["quest:594"] = {n="Message in a Bottle",s="O sticla adusa de valuri, gasita pe tarmurile din Stranglethorn Vale, contine un apel urgent de salvare. Autorul sustine ca este tinut prizonier de o bestie uriasa pe o insula izolata din South Seas.",h="O sticla adusa de valuri, gasita pe tarmurile din Stranglethorn Vale, contine un apel urgent de salvare.",kw={"sticla pe jumatate ingropata","mesaj intr-o sticla","princess poobah","skymane","south seas","stranglethorn vale","tarm salbatic"},sec={{t="Un apel din valuri",b="Intr-un recipient de sticla pe jumatate ingropat in nisip se afla un bilet scris ingrijit, cu o cerere de ajutor imediat. Prizonierul spune ca e captiv pe o insula straina, sub bolta deasa a junglei, si ca este tinut de un Skymane urias. Printre copaci se intrevad doar repere vagi: coasta din Wild Shore se vede spre nord-vest, iar corabii mari cu panze plutesc spre sud-vest."},{t="Autorul biletului",b="Urmand indicatiile nautice, ajungi peste apa la o insula din larg, unde te asteapta autorul mesajului. Captiva izolata este Princess Poobah, disperata sa ajunga in sfarsit la ea un aventurier care sa-i ofere sansa la libertate."}},faq={{q="Ce scrie pe biletul din sticla?",a="Mesajul este o rugaminte urgenta, scrisa cu un scris de mana limpede. Explica faptul ca autorul este tinut prizonier de un Skymane urias pe o insula din South Seas si il implora pe cel care gaseste biletul sa-l salveze.",al={"continutul biletului","biletul din sticla","ce scrie pe biletul din sticla"}},{q="Unde spune autorul ca se afla insula?",a="Desi copacii junglei ascund stelele noaptea, captivul remarca faptul ca, in zilele senine, Wild Shore se poate vedea la nord-vest, iar vasele mari cu panze apar la sud-vest.",al={"locatia insulei","cum il gasesc pe prizonier","reperele insulei"}},{q="Ce il tine captiv pe autor?",a="Biletul spune ca o creatura numita great Skymane il tine prizonier pe autor pe insula.",al={"cine l-a capturat pe autor","ce-l tine captiv pe autor","rapitorul lui skymane"}},{q="Duce aceasta la aventuri noi?",a="Gasirea expeditorului este prima parte a unui sir de doua misiuni, care duce direct la a doua parte dupa ce gasesti prizonierul.",al={"misiunea urmatoare","exista o continuare","ce se intampla dupa aceasta"}}},fp="19,192,21.379.0,22.233.1,37.202.0,48.179.0,35.102.0,37.120.0"}
P.entries["quest:5943"] = {n="Gizelton Caravan",s="Rigger Gizelton si Cork si-au pornit caravana ca sa se imbogateasca, dar au descoperit ca negotul este mai periculos decat se asteptau. In fata se afla Mannoroc Coven, iar Rigger vrea un aventurier capabil sa pazeasca caravana cand trece pe acolo.",h="Rigger Gizelton si Cork si-au pornit caravana ca sa se imbogateasca, dar au descoperit ca negotul este mai...",kw={"caravana","dop","coven","Desolace","Gizelton","kodo","Mannoroc","mecanic","Scrabblescrew","Smeed"},sec={{t="Dincolo de Mannoroc Coven",b="Rigger Gizelton si Cork au pus la cale caravana ca sa faca avere, fara sa-si dea seama cat de riscant putea fi sa obtina profit. Mannoroc Coven se afla inainte. De obicei, demonii lasa caravana in pace, dar de data aceasta kodo sunt speriati. Rigger iti ofera plata daca protejezi caravana pana trece de coven. Dupa ce ajunge in siguranta, plata te asteapta la Scrabblescrew's Camp, la Smeed, un asociat de afaceri de-al lor."},{t="Indoielile lui Smeed",b="La Scrabblescrew's Camp, Smeed isi sterge fruntea si spune ca ar fi ruinat daca ar disparea vreodata caravana, asa ca se bucura sa afle ca nu s-a pierdut. Nu stie daca are sens sa plateasca atat de mult pentru a proteja o caravana ai carei proprietari castiga doar o moneda de aur pe saptamana. Totusi, cat timp Cork si Rigger continua sa-i plateasca kodo-urile, nu-i pasa cum isi conduc afacerea."}},faq={{q="Cine este Rigger Gizelton?",a="Un proprietar de caravane care a infiintat Gizelton Caravan impreuna cu Cork, in speranta ca se va imbogati.",al={"cine este rigger","trecutul lui gizelton","rigger gizelton"}},{q="De ce are caravana nevoie de protectie dupa Mannoroc Coven?",a="Rigger spune ca demonii de acolo ignora de obicei convoiul, dar de data aceasta ceva a speriat kodos.",al={"de ce sa escortezi caravana","pericolul reprezentat de Mannoroc Coven","de ce sa aperi caravana"}},{q="Cine te plateste pentru protejarea caravanei?",a="Smeed, asociatul de afaceri al familiei Gizelton de la Scrabblescrew's Camp, dupa ce caravana trece in siguranta de coven.",al={"cine ma plateste","unde predau Gizelton Caravan","recompensa lui smeed"}},{q="Cine este Cork?",a="Partenerul lui Rigger Gizelton din caravana.",al={"cork gizelton","cine este cork"}}},fp="16,210,19.399.0,18.360.1,23.85.0,57.103.0,40.108.0,12.41.0"}
P.entries["quest:595"] = {n="The Bloodsail Buccaneers",s="First Mate Crazz din Blackwater Raiders are nevoie de un aventurier care sa cerceteze zvonurile despre pirati rivali. Echipajul sau e ocupat sa bea si sa caute companie in Booty Bay, asa ca iti cere sa cercetezi un golf din apropiere, de-a lungul coastei Savage Coast, in cautarea unor semne ale Bloodsail Buccaneers.",h="First Mate Crazz din Blackwater Raiders are nevoie de un aventurier care sa cerceteze zvonurile despre pirati...",kw={"blackwater raiders","bloodsail buccaneers","booty bay","corespondenta","first mate crazz","savage coast","stranglethorn vale"},sec={{t="Un cercetas de-a lungul Savage Coast",b="Blackwater Raiders au acostat de curand in Booty Bay, doar ca sa afle ca rivalii lor, Bloodsail Buccaneers, au fost vazuti prin sudul Stranglethorn Vale. Cum restul echipajului e distras de grog si de aventurile de pe tarm, First Mate Crazz apeleaza la ajutorul unui strain. Iti cere sa mergi spre nord, de-a lungul Savage Coast, si sa cercetezi un golfulet ca sa vezi ce pun la cale Bloodsail Buccaneers."},{t="Semne in golf",b="In timp ce cercetezi golful, gasesti un butoi cu cateva monede si o harta acoperita de notite mazgalite in graba, asezata deasupra."}},faq={{q="Cine este First Mate Crazz?",a="First Mate Crazz este ofiter in randurile Blackwater Raiders, stationati in Booty Bay. Confruntat cu zvonuri despre pirati rivali si cu un echipaj lipsit de tragere de inima, angajeaza aventurieri in trecere ca sa cerceteze coasta.",al={"first mate crazz","cine ofera misiunea","cine este crazz"}},{q="De ce are nevoie First Mate Crazz de un strain?",a="Echipajul Blackwater tocmai a ajuns in port si abia a acostat; sunt prea ocupati sa chefuiasca pe tarm ca sa cerceteze ceva pe cont propriu.",al={"de ce sa angajeze un aventurier","de ce nu se poate ocupa echipajul lui","de ce sa-l ajut pe Crazz"}},{q="Unde te trimite Crazz sa investighezi?",a="Iti cere sa cercetezi golful aflat chiar la nord de Booty Bay, de-a lungul fasiei cunoscute drept Savage Coast.",al={"unde trebuie sa merg","unde este golful","unde sunt bloodsail"}},{q="Ce rivalitate ii tulbura pe Blackwater Raiders?",a="Blackwater Raiders sunt prinsi intr-o dusmanie amara cu Bloodsail Buccaneers, care au fost vazuti recent raspandindu-se in sudul Stranglethorn Vale.",al={"cine sunt rivalii","de ce ii urasc pe bloodsail","rivalitatea cu bloodsail"}}},fp="24,261,30.402.0,17.118.1,24.192.0,43.131.0,41.116.0,49.162.0"}
P.entries["quest:596"] = {n="Bloody Bone Necklaces",s="Kin'weelay de la Grom'gol Base Camp are propriile planuri in Stranglethorn Vale, dincolo de a-l ajuta pe Nimboya. El vrea sa slabeasca tribul rival Bloodscalp strangand trofee de la razboinicii sai.",h="Kin'weelay de la Grom'gol Base Camp are propriile planuri in Stranglethorn Vale, dincolo de a-l ajuta pe...",kw={"bloodscalp","darkspear","grom'gol","kin'weelay","coliere","nimboya","stranglethorn"},ang={["faction:Horde"]="Kin'weelay a fost trimis la Grom'gol Base Camp sa-l ajute pe Nimboya si isi foloseste timpul acolo pentru a vana tribul Bloodscalp, aflat la nord.",["race:Troll"]="Pentru Darkspear, vanatoarea celor din Bloodscalp tine de dobandirea puterii asupra unui trib inamic."},sec={{t="Trofee de razboi",b="Desi Kin'weelay a sosit la avanpostul din jungla, Grom'gol Base Camp, ca sa-l ajute pe Nimboya, are si propriile interese. Trollii Bloodscalp care salasluiesc la nord sunt dusmanii celor din Darkspear. Kin'weelay crede ca obtinerea de trofee personale de la dusmanii cazuti le da putere spirituala asupra acestora, asa ca le cere calatorilor sa vaneze razboinici Bloodscalp si sa le ia colierele de os insangerate pe care le poarta la gat."},{t="Secatuirea spiritelor",b="Dupa ce primeste podoabele din oase recoltate, Kin'weelay intentioneaza sa le fiarba si sa le lase la inmuiat pana se transforma in pasta. Prin acest ritual, vrea sa vestejeasca si sa slabeasca direct spiritele persistente ale Bloodscalp ucisi."}},faq={{q="Cine cere colierele din oase?",a="Kin'weelay ofera misiunea la Grom'gol Base Camp, in Stranglethorn Vale. Desi a fost trimis acolo ca sa-l ajute pe Nimboya, foloseste tabara pentru propria razbunare spirituala.",al={"responsabilul misiunii","cine ofera Bloody Bone Necklaces","misiunea lui Kin'weelay"}},{q="De ce vrea Kin'weelay trofee de la tribul Bloodscalp?",a="Bloodscalp sunt dusmani de moarte ai tribului Darkspear. Kin'weelay crede ca luarea trofeelor de la dusmanii ucisi le da putere asupra acestora, permitandu-le celor din Darkspear sa-si impuna dominatia asupra rivalilor.",al={"de ce sa aduni coliere","scopul colierelor Bloodscalp","de ce sa vanezi Bloodscalp"}},{q="Unde se afla Bloodscalps?",a="Trolls Bloodscalp locuiesc in tinuturile de la nord de Grom'gol Base Camp, in tot nordul Stranglethorn Vale.",al={"unde gasesti Bloodscalp","locatia Bloodscalp","unde sunt Troll"}},{q="Ce urmeaza dupa aceasta vanatoare?",a="Dupa aceasta vanatoare, Kin'weelay ii trimite pe aventurieri mai departe, catre misiunea urmatoare, Split Bone Necklace.",al={"urmatoarea misiune","continuarea dupa Bloody Bone Necklaces","ce urmeaza dupa Bloody Bone Necklaces"}}},fp="21,188,15.417.0,20.236.1,32.173.0,60.201.0,34.115.0,32.87.0"}
P.entries["quest:597"] = {n="The Bloodsail Buccaneers",s="Corespondenta recuperata de la Bloodsail Buccaneers contine o harta a Booty Bay si ordine scrise de a securiza o tabara retrasa in locul marcat si de a astepta un semnal de la postul de comanda din sud inainte de atac.",h="Corespondenta recuperata de la Bloodsail Buccaneers contine o harta a Booty Bay si ordine scrise de a...",kw={"bloodsail buccaneers","corespondenta bloodsail","booty bay","first mate crazz","post de comanda sudic","stranglethorn vale"},sec={{t="Un complot dezvaluit",b="In urma cercetarilor tale anterioare despre Bloodsail Buccaneers, o harta interceptata si ordine scrise dezvaluie planurile imediate ale piratilor. Un X rosu pe harta lui Booty Bay marcheaza locul exact in care piratii trebuie sa-si instaleze tabara. Ordinele le cer membrilor echipajului sa-si pastreze pozitiile in liniste, sa-i elimine pe toti cei care se apropie si sa astepte semnalul de atac trimis de la avanpostul de comanda sudic."},{t="Raportare la port",b="Ducand aceste informatii scrise inapoi la Booty Bay, ii vei preda direct informatiile lui First Mate Crazz, care te-a trimis initial sa cercetezi zona. Piratii asteapta in mod evident un semnal inainte sa atace."}},faq={{q="Ce este scris in corespondenta Bloodsail?",a="Textul le cere piratilor din echipaj sa-si asigure o tabara linistita in locul marcat, sa-i ucida pe toti cei care se apropie si sa astepte un semnal de la postul lor de comanda din sud, pentru a lansa atacul.",al={"textul ordinelor Bloodsail","ce spune biletul","detalii despre harta Bloodsail"}},{q="Unde indica harta?",a="Harta capturata a lui Booty Bay are un X rosu, care indica locul unde piratii intentioneaza sa-si ridice tabara.",al={"x-ul de pe harta Bloodsail","ce inseamna x-ul rosu","unde este tabara"}},{q="Cine trebuie sa afle despre aceasta descoperire?",a="Informatiile trebuie raportate direct lui First Mate Crazz, in Booty Bay; el isi aminteste ca ti-a cerut sa cercetezi zona.",al={"cui predau obiectul","cine primeste harta Bloodsail","raport pentru First Mate Crazz"}},{q="Ce a avut loc inainte de a gasi aceasta corespondenta?",a="Aceasta investigatie urmeaza direct misiunii initiale primite de la First Mate Crazz in Booty Bay, privind Bloodsail Buccaneers.",al={"misiune prealabila","misiunea anterioara Bloodsail","inceputul lantului Bloodsail"}}},fp="24,215,15.385.0,23.205.0,48.186.0,25.105.0,39.121.0,45.133.0"}
P.entries["quest:598"] = {n="Split Bone Necklace",s="Kin'weelay din Grom'gol Base Camp le cere aliatilor Horde sa vaneze tribul Skullsplitter, care traieste la sud-est. Desi Darkspears au parasit Stranglethorn Vale, vechiul lor conflict cu acesti rivali din jungla ramane nerezolvat. Intoarcerea cu douazeci si cinci de trofee din oase despicate ii ajuta pe Darkspears in razboiul lor si le castiga prietenia.",h="Kin'weelay din Grom'gol Base Camp le cere aliatilor Horde sa vaneze tribul Skullsplitter, care traieste la...",kw={"darkspear","grom'gol base camp","kin'weelay","skullsplitter","split bone necklace","stranglethorn vale"},ang={["faction:Horde"]="Ajutarea lui Kin'weelay la Grom'gol Base Camp in razboiul impotriva Skullsplitter castiga prietenia celor din Darkspear.",["race:Troll"]="Pentru Troll Darkspear, luarea trofeelor de la Skullsplitter duce mai departe un razboi indelungat, care nu s-a incheiat cand tribul a parasit Stranglethorn."},sec={{t="O dusmanie nestinsa",b="Dupa strangerea trofeelor Bloodscalp, Kin'weelay isi indreapta atentia spre un alt dusman de demult. Tribul Skullsplitter traieste la sud-est de Grom'gol Base Camp, unde s-a luptat cu Darkspear de-a lungul multor ani. Chiar daca Darkspear nu mai locuiesc in jungla din Stranglethorn Vale, raman legati de acest razboi care nu se mai sfarseste."},{t="Trofee de razboi",b="Pentru a castiga prietenia si respectul tribului Darkspear, un aventurier trebuie sa patrunda pe teritoriul Skullsplitter si sa ia douazeci si cinci dintre distinctivele lor coliere din oase despicate. Kin'weelay este mandru sa vada cum acesti trolli ostili sunt secerati ca niste puieti de un basilisc, socotind fiecare trofeu recuperat o victorie pentru poporul sau."}},faq={{q="Cine propune aceasta vanatoare si unde se afla?",a="Kin'weelay iti propune vanatoarea de la Grom'gol Base Camp, un avanpost Horde de pe coasta vestica a Stranglethorn Vale.",al={"cine ofera split bone necklace","locatia lui kinweelay","cel care da misiunea split bone necklace"}},{q="Ce a precedat aceasta sarcina?",a="Aceasta sarcina urmeaza dupa Bloody Bone Necklaces, o vanatoare anterioara in care Kin'weelay le-a cerut aventurierilor sa adune trofee de la tribul Bloodscalp.",al={"conditie prealabila split bone necklace","misiunea anterioara lui split bone necklace","pasul precedent"}},{q="De ce se lupta Darkspear cu Skullsplitters daca au parasit Stranglethorn Vale?",a="Darkspears si Skullsplitters s-au razboit ani la rand in jungla. Chiar daca tribul Darkspear a migrat departe de Stranglethorn Vale, Kin'weelay explica faptul ca membrii sai sunt in continuare legati de conflict si intentioneaza sa-si faca dusmanii sa regrete ca l-au inceput.",al={"de ce urasc Darkspear clanul Skullsplitter","povestea razboiului Skullsplitter","conflictul dintre Darkspear si Skullsplitter"}},{q="Unde se gaseste tribul Skullsplitter?",a="Skullsplitter locuiesc in tinuturile aflate la sud-est de Grom'gol Base Camp, in Stranglethorn Vale.",al={"locatia Skullsplitter","unde sunt Skullsplitter","taberele Skullsplitter"}},{q="Ce dovada cere Kin'weelay de la vanatoare?",a="Kin'weelay are nevoie de douazeci si cinci de Split Bone Necklaces, luate direct de la trolls Skullsplitter cazuti.",al={"ce obiecte sunt necesare pentru kinweelay","obiect split bone necklace","cate coliere"}}},fp="19,345,16.374.0,15.336.0,46.111.0,27.152.0,79.275.0,43.108.0,48.101.0"}
P.entries["quest:599"] = {n="The Bloodsail Buccaneers",s="First Mate Crazz a aflat ca Bloodsail Buccaneers intentioneaza sa atace Booty Bay. Amploarea amenintarii necesita atentia comandantului Blackwater Raiders, Fleet Master Seahorn, care trebuie avertizat imediat.",h="First Mate Crazz a aflat ca Bloodsail Buccaneers intentioneaza sa atace Booty Bay.",kw={"blackwater raiders","bloodsail bucaneers","booty bay","first mate crazz","fleet master seahorn","stranglethorn vale"},sec={{t="Un avertisment pentru comandantul flotei",b="Dupa ce descopera ca Bloodsail Buccaneers pun la cale un atac direct asupra Booty Bay, First Mate Crazz isi da seama ca situatia e mai grava decat crezuse. Iti cere sa-l cauti pe Fleet Master Seahorn, aflat undeva in orasul-port, si sa-l instiintezi despre atacul care se pregateste, inainte ca piratii rivali sa-si puna planul in aplicare."},{t="Sfidarea lui Seahorn",b="Dupa ce i se prezinta raportul despre atacul planificat, Fleet Master Seahorn isi bate joc de ambitia piratilor rivali si declara ca atacarea Booty Bay ar fi la fel de nechibzuita precum saritul de pe Overlook Cliffs. Chiar si asa, recunoaste valoarea informatiilor si iti multumeste in numele Blackwater Raiders."}},faq={{q="Cine te trimite sa-l avertizezi pe Fleet Master Seahorn?",a="First Mate Crazz te trimite sa-l avertizezi pe Seahorn dupa ce afla amploarea planurilor ostile ale Bloodsail Buccaneers impotriva portului.",al={"cine incepe aceasta misiune","misiunea lui First Mate Crazz","cel care da misiunea Bloodsail Buccaneers"}},{q="Unde poate fi gasit Fleet Master Seahorn?",a="Fleet Master Seahorn isi are cartierul general in ascunzatoarea piratilor din Booty Bay, in sudul Stranglethorn Vale.",al={"unde se afla seahorn","locatia lui seahorn","orasul lui fleet master seahorn"}},{q="Care este planul Bloodsail Buccaneers?",a="Bloodsail Buccaneers pregatesc un atac in toata regula asupra Booty Bay, sfidand stapanirea Blackwater Raiders asupra orasului.",al={"ce pun la cale Bloodsail","planul de atac al Bloodsail","complotul Bloodsail Buccaneers"}},{q="Ce factiune controleaza Booty Bay?",a="Booty Bay este controlat si administrat de Blackwater Raiders, care protejeaza cu inversunare portul de rivalii lor Bloodsail.",al={"cine conduce booty bay","factiunea piratilor din booty bay"}}},fp="24,254,30.306.0,18.301.1,43.129.0,40.102.0,41.132.0,33.116.0"}
P.entries["quest:6"] = {n="Bounty on Garrick Padfoot",s="In Northshire, o recompensa din partea Alliance il vizeaza pe Garrick Padfoot, un hot notoriu din partea locului. Deputy Willem de la Northshire Abbey cheama recrutii sa-l vaneze in apropierea podgoriilor.",h="In Northshire, o recompensa din partea Alliance il vizeaza pe Garrick Padfoot, un hot notoriu din partea...",kw={"recompensa","talhar","elwynn","garrick","northshire","padfoot","hotii","podgorie","willem"},ang={["class:Rogue"]="Ca Rogue, vezi cum opereaza proscrisii in umbrele din Elwynn. O ascunzatoare prost camuflata atrage o lovitura rapida de lama.",["faction:Alliance"]="Infrangerea lui Garrick Padfoot este o prima misiune pentru un aventurier aspirant al Alliance si ajuta la restabilirea stabilitatii in Kingdom of Stormwind.",["race:Human"]="Ca human crescut in regat, ai motive sa-ti aperi pamantul sfant al patriei si fermierii locali de ucigasi precum Padfoot."},sec={{t="O molima in Vale",b="Northshire Valley oferea odinioara un loc sigur pentru pregatirea recrutilor si ingrijirea viilor sale sacre. Pe masura ce ordinea se clatina in Elwynn, hotii au ajuns in vale. Garrick Padfoot, un talhar, s-a ridicat repede la conducerea lor. De saptamani intregi, el si banda lui jefuiesc transporturi, ataca negustori pe drumuri si ameninta fermierii din zona."},{t="Dreptatea adjunctului Willem",b="Garzile Stormwind sunt intinse la maximum, protejand capitala si granitele ei exterioare. Marshal-ii si adjunctii locali se bazeaza pe voluntari ca sa mentina pacea in Northshire. Deputy Willem ofera public o recompensa pentru capul lui Garrick, sperand sa scape valea de banda acestuia. Daca il dobori pe Padfoot la darapanatura sa de la est de rau, lovesti direct in faradelegea care se raspandeste prin tinuturile locuite de Human."}},faq={{q="Cine este Garrick Padfoot?",a="Garrick Padfoot este un bandit si ucigas in Northshire Valley. De saptamani intregi ii hartuieste pe fermierii locali si ataca negustorii, strangand o ceata restransa de batausi langa vii.",al={"garrick padfoot","cine este garrick","padfoot"}},{q="Unde poate fi gasit Garrick Padfoot?",a="Garrick Padfoot se ascunde intr-o coliba mica de lemn, la est de Northshire Abbey, dincolo de podul peste rau si aproape de podgorii. Alti banditi il pazesc.",al={"unde este Garrick Padfoot","locatia lui Garrick","coliba lui Garrick"}},{q="Cine pune recompensa pe capul lui Garrick?",a="Deputy Willem, stationat in fata Northshire Abbey, afiseaza recompensa. Cu prea putini garzi ai orasului pentru a pazi valea, el le cere recrutilor ratacitori sa-l aduca pe proscris in fata justitiei.",al={"cine ofera recompensa pentru Bounty on Garrick Padfoot","recompensa lui Willem"}},{q="De ce nu trimite Stormwind soldati obisnuiti sa se ocupe de el?",a="Armata din Stormwind este suprasolicitata. Cu King Varian Wrynn disparut si tensiunile in crestere in Elwynn Forest si dincolo de hotarele sale, capitala nu-si poate permite sa trimita garnizoane de veterani pentru fiecare gainar. Adjunctii locali trebuie sa apeleze la recruti.",al={"de ce nu-l omoara garzile pe garrick","unde sunt garzile din Stormwind"}},{q="Lucreaza Garrick Padfoot singur?",a="Nu. Garrick a adunat o mica banda de proscrisi si banditi care campeaza in jurul colibei lui, langa viile din Northshire, pentru a-l proteja.",al={"garrick lupta singur","gasca lui padfoot"}},{q="Ce dovada ii cere Deputy Willem?",a="Deputy Willem cere o dovada concreta inainte sa plateasca: adu capul taiat al lui Garrick Padfoot inapoi la Northshire Abbey.",al={"dovada mortii lui garrick","capul lui garrick"}}},fx={["38d5a8ce"]={q="De ce vrea Deputy Willem sa-l ucida pe Garrick Padfoot?",a="Garrick Padfoot a terorizat Northshire Valley timp de saptamani intregi. In calitate de criminal neindurator care conduce o banda de hoti, ii praduieste fara incetare pe fermierii si negustorii calatori ce tin valea in viata. Ajutorul de serif Willem il vrea mort pentru a pune capat raidurilor sale, a reda siguranta podgoriilor si drumurilor si a proteja comunitatea manastirii de noi acte de violenta.",al={"de ce sa-l omori pe Garrick Padfoot","motivul lui Deputy Willem","de ce vrea Willem sa-l vada mort pe Garrick"}}},fp="25,166,22.328.0,23.381.0,23.180.0,35.143.0,33.178.0,63.235.0,33.132.0,38.124.0"}
P.entries["quest:60"] = {n="Kobold Candles",s="La Lion's Pride Inn din Goldshire, William Pestle cauta lumanari de la koboldii care au facut stocuri prea mari in minele din Elwynn Forest. Venit in vizita de la atelierul sau din Stormwind, alchimistul are nevoie de ceara lor groasa, iar sarcina le face cunostinta aventurierilor cu daunatorii subterani care ameninta filoanele pretioase de aur ale regatului.",h="La Lion's Pride Inn din Goldshire, William Pestle cauta lumanari de la koboldii care au facut stocuri prea...",kw={"alchimist","lumanare","Elwynn","Fargodeep","Goldshire","Jasperlode","kobold","ceara","William Pestle"},ang={["faction:Alliance"]="Ca membru al Alliance, ajuti la securizarea infrastructurii locale, in timp ce armata regala este intinsa la maximum de conflictele politice interne si de disparitia fortelor coroanei.",["profession:Mining"]="Alungarea koboldilor pentru lumanarile lor ii aduce pe prospectori direct la cele mai bogate filoane de cupru si aur din Elwynn, abandonate de minerii Human.",["race:Human"]="Ca Human, recucerirea minelor furate din Elwynn si aprovizionarea mestesugarilor din Stormwind sunt primele indatoriri ale unui tanar supus al regatului."},sec={{t="Comisioanele alchimistului",b="William Pestle conduce Pestle's Apothecary impreuna cu fratele sau, in Trade District din Stormwind City. Ceara este mereu greu de gasit, in timp ce prepara leacuri, alifii si potiuni. In loc sa cumpere lumanari lustruite de la negustorii orasului, Pestle apeleaza la daunatorii din Elwynn. Kobold poarta bulgari mari de seu si ceara pe frunte, gata sa-i fie smulsi de un aventurier indraznet."},{t="Minele din Elwynn",b="Kobolds au napadit Fargodeep Mine, la sud de Goldshire, si Jasperlode Mine, la nord-est. Aceste creaturi care adulmeca necontenit pretuiesc lumanarile mai presus de aproape orice. Flacarile palpainde le calauzesc prin galerii intunecate in timp ce sapa dupa aur si maruntisuri stralucitoare. Strangerea lumanarilor reface stocurile de alchimie ale lui Pestle si loveste in daunatorii care sufoca exploatarile miniere pretioase ale regatului."}},faq={{q="De ce are William Pestle nevoie de lumanari kobold?",a="William Pestle si fratele sau conduc o farmacie in Trade District din Stormwind. Folosesc seul si ceara obtinute din lumanari mari pentru sigilare, alifii si alte preparate alchimice.",al={"de ce vrea Pestle lumanari","la ce se folosesc lumanarile","utilizarea cerii de lumanare"}},{q="Unde gasesti lumanarile mari?",a="Muncitorii kobold, daunatorii si sapatorii poarta lumanari in minele din Elwynn Forest, mai ales in Fargodeep Mine, la sud de Goldshire, si in Jasperlode Mine, la est.",al={"unde sunt lumanarile kobold","locatiile lumanarilor","cum obtin lumanari mari"}},{q="De ce sunt kobolzii atat de obsedati de lumanari?",a="Kobolds traiesc in tuneluri subterane bezna si se bazeaza pe flacarile prinse de cap pentru a vedea in timp ce sapa. Teama lor de intuneric este superstitioasa si aproape frenetica, asa ca isi apara cu indarjire lumanarile de oricine incearca sa li le ia.",al={"de ce au koboldzi lumanari","ce inseamna nu iei lumanarea","povestea lumanarilor koboldzilor"}},{q="Cine este William Pestle?",a="William Pestle este un negustor si alchimist Human din Stormwind. Cand nu se afla in magazinul sau din Trade District al orasului, calatoreste la Goldshire pentru a cumpara materiale ieftine de la aventurieri.",al={"cine este William Pestle","povestea lui William Pestle","Pestle din Goldshire"}},{q="Are aceasta misiune vreo legatura cu alte probleme din Elwynn?",a="Da. Invazia de koboldi din minele Fargodeep si Jasperlode Mine ameninta economia oraselor Goldshire si Stormwind. Minerii umani au fost alungati, iar securizarea tunelurilor este una dintre prioritatile principale ale lui Marshal Dughan.",al={"probleme in minele din Elwynn","de ce sunt kobolzi in mine","amenintarea kobolzilor din Goldshire"}},{q="Mai exista si alte mine infestate de kobolzi in Elwynn?",a="Fargodeep Mine si Jasperlode Mine sunt cele doua principale asezari Kobold din apropiere de Goldshire. Activitatea lor se extinde si pe malurile raului din padure, spre est, pana la granitele cu Redridge.",al={"alte mine kobold","lista minelor din elwynn"}}},fx={["13eaf00c"]={q="La ce foloseste Large Candle?",a="William Pestle are nevoie de lumanarile mari pentru ceara lor. El si fratele sau conduc Pestle's Apothecary in Trade District din Stormwind. Misiunile nu precizeaza pentru ce preparate anume folosesc acea ceara.",al={"utilizarea lumanarilor mari","de ce lumanari mari","la ce folosesc lumanarile"}},decb568d={q="De ce se afla koboldii in minele din Elwynn?",a="Kobolds sunt necrofagi subterani atrasi de tuneluri intunecate si bogate in minerale, unde pot sapa dupa aur si minereuri pretioase. Cu armata Stormwind slabita si regele Varian Wrynn disparut, minele locale din Elwynn, precum Fargodeep si Jasperlode, au ramas slab aparate, permitandu-le kobolds sa cotropeasca galeriile si sa-i alunge pe minerii humans.",al={"de ce sunt kobolzii aici","de ce sunt kobolzii in Fargodeep","invazia koboldilor in Elwynn"}},["27573e3c"]={q="De ce te roaga William Pestle pe tine, in locul garzilor din Stormwind?",a="William Pestle este alchimist, nu soldat. Kobolzii pazesc cu inversunare tunelurile din Fargodeep si Jasperlode, iar o incursiune personala in mine ar fi fatala. Intre timp, gardienii locali din Stormwind si marshal-ii din Elwynn sunt complet coplesiti de banditii Defias si de gnolli, asa ca lasa treburi marunte, precum strangerea cerii, in seama aventurierilor aflati in trecere.",al={"de ce nu isi ia william singur lumanari","de ce sa angajeze aventurieri pentru lumanari","de ce nu garzile din stormwind"}}},fp="14,312,20.381.0,19.389.0,44.190.0,36.160.0,41.248.0,22.192.0,52.209.0,56.181.0"}
P.entries["quest:600"] = {n="Venture Company Mining",s="In Booty Bay, goblinul Crank Fizzlebub vrea ca cineva sa loveasca in operatiunile Venture Company din nordul Stranglethorn Vale. Situl lor de excavare de langa Crystalvein Mine continua sa produca Singing Blue Crystals de mare valoare din dealurile din apropiere, iar Crank cere sa-i fie aduse inapoi zece dintre aceste pietre.",h="In Booty Bay, goblinul Crank Fizzlebub vrea ca cineva sa loveasca in operatiunile Venture Company din nordul...",kw={"booty bay","crank fizzlebub","crystalvein mine","cristale albastre cantatoare","stranglethorn vale","venture company"},sec={{t="Sabotarea competitiei",b="Dupa ce ai adunat Singing Blue Shards, Crank Fizzlebub iti atrage atentia asupra unui rival mai mare. Venture Company isi desfasoara operatiunile prin toata jungla, micsorand profiturile goblinilor independenti. Desi numerosi basilisci ii impiedica pe mineri sa intre in Crystalvein Mine, muncitorii continua sa sape pe dealurile din jur pentru a extrage Singing Blue Crystals. Crank iti cere sa iei cristalele de la acesti mineri si sa le duci la Booty Bay, drept dovada a pierderilor suferite de ei."},{t="Dupa sosirea cristalelor",b="Desi Crank prezinta cererea drept o razbunare justificata impotriva unui cartel nemilos, entuziasmul cu care priveste Singing Blue Crystals adunate ii da in vileag adevaratul interes. Departe de a dori doar sa umileasca Venture Company, intentioneaza sa vanda pietrele recuperate pe o avere insemnata, in Booty Bay."}},faq={{q="Cine ofera misiunea Venture Company Mining?",a="Crank Fizzlebub, un goblin din Booty Bay, iti ofera aceasta treaba dupa ce termini Singing Blue Shards.",al={"cine incepe Venture Company Mining","cine da misiunea Venture Company Mining"}},{q="Unde sapa minerii dupa aceste cristale?",a="Venture Company opereaza in apropiere de Crystalvein Mine, in regiunea nordica din Stranglethorn Vale, lucrand dealurile din jurul minei.",al={"unde exploateaza Venture Company","locatia minei Venture Company din Stranglethorn"}},{q="De ce nu se afla minerii Venture Company in mina?",a="Crank explica faptul ca numerosi basilisks din Crystalvein Mine ii impiedica pe mineri sa intre, obligandu-i sa sape de-a lungul dealurilor de la margine.",al={"de ce in afara Crystalvein Mine","basiliscurile de la Crystalvein Mine"}},{q="Ce iti cere Crank Fizzlebub sa-i aduci?",a="Iti cere zece Singing Blue Crystals luate de la minerii Venture Company care lucreaza langa Crystalvein Mine.",al={"obiectele necesare pentru mineritul Venture Company","ce obiecte ii trebuie lui Crank Fizzlebub"}},{q="Ce a precedat Venture Company Mining?",a="Misiunea anterioara din acest sir este Singing Blue Shards, in care Crank iti cere mai intai sa aduni cioburi de cristal mai mici in Stranglethorn Vale.",al={"lantul misiunilor de minerit venture company","conditie prealabila pentru mineritul venture company"}}},fp="22,304,26.502.0,25.304.1,43.101.0,48.135.0,54.152.0,47.106.0,40.138.0"}
P.entries["quest:6001"] = {n="Body and Heart"}
P.entries["quest:6002"] = {n="Body and Heart",s="Body and Heart este incercarea culminanta pentru tinerii druizi tauren care vor sa stapaneasca Bear Form. Trimisi de Turak Runetotem din Thunder Bluff, initiatii trebuie sa calatoreasca la granita dintre Mulgore si Barrens, sa-l cheme pe Lunaclaw si sa-l invinga la Moonkin Stone.",h="Body and Heart este incercarea culminanta pentru tinerii druizi tauren care vor sa stapaneasca Bear Form.",kw={"barrens","forma de urs","trup si inima","camp taurajo","cenarion lunardust","lunaclaw","moonkin stone","mulgore","thunder bluff","turak runetotem"},ang={["class:Druid"]="Acest rit de trecere leaga invataturile Cenarion ale night elves de mostenirea taurenilor, permitandu-le tinerilor druizi sa-si manifeste in sfarsit rezistenta feroce a Bear Form.",["faction:Horde"]="Druizii Tauren aduc rezistenta esentiala in primele linii ale Horde, ancorand puterea magica a factiunii in paza adanca a salbaticiei.",["race:Tauren"]="Pentru Shu'halo, trezirea ursului launtric este atat o comuniune sacra cu spiritele naturii, cat si o cale practica de a apara campiile din Mulgore de amenintarile care se apropie."},sec={{t="Calea ghearei",b="Pentru a urma cu adevarat calea Druid of the Claw, initiatii tauren trebuie sa imbine convingerea spirituala cu rezistenta fizica. Dupa comuniunea cu Great Bear Spirit din Moonglade, pregatirea unui druid este pusa la incercare in practica. Turak Runetotem, elderul care antreneaza druizii in varful Elder Rise din Thunder Bluff, le daruieste Cenarion Lunardust aspirantilor vrednici si ii indeamna sa caute o piatra sacra langa frontiera arida unde Mulgore se intalneste cu Barrens."},{t="Incercarea lui Lunaclaw",b="La vest de Camp Taurajo, Moonkin Stone marcheaza un rar loc al Cenarion Circle din sudul Kalimdorului. Moonkin nu sunt originari din campiile dogorite ale centrului Kalimdorului, ceea ce face ca prezenta bestiei pazitoare Lunaclaw sa fie foarte insemnata. Raspandind praful lunar peste monumentul stravechi, druidul o cheama pe Lunaclaw la lupta. Infrangerea creaturii dovedeste ca aspirantul stapaneste atat puterea trupului, cat si limpezimea inimii, castigand binecuvantarea bestiei si dezvaluindu-si esenta ursului dinlauntru."}},faq={{q="Care este scopul acestei incercari?",a="Aceasta misiune este ultimul pas pentru a obtine Bear Form pentru druizii Horde. Indeplinind provocarea, dovedesti ca esti pregatit sa preiei mantia unui Druid of the Claw sub indrumarea lui Turak Runetotem.",al={"la ce folosesc trupul si inima","ce face trupul si inima","ce primesc de la trupul si inima"}},{q="Unde se afla Moonkin Stone?",a="Moonkin Stone se afla in Barrens, la vest de Camp Taurajo, de-a lungul drumului care duce spre poarta Mulgore. Chiar la sud de drum, ascunsa in spatele unui copac de langa un cort singuratic, se afla piatra sacra.",al={"locatia Moonkin Stone","unde este Moonkin Stone","unde gasesti Moonkin Stone"}},{q="Cine este Lunaclaw?",a="Lunaclaw este un gardian moonkin feroce, legat de Moonkin Stone. Invocat cu Cenarion Lunardust, acesta pune la incercare daca un druid are tenacitatea bruta si stapanirea de sine necesare pentru a manui puterea ursului.",al={"cine este Lunaclaw","ce este Lunaclaw"}},{q="Ce se intampla daca pierd lupta impotriva lui Lunaclaw?",a="Daca esti invins, Cenarion Lunardust se consuma. Trebuie sa te intorci la Turak Runetotem, in varful Elder Rise din Thunder Bluff, pentru a primi inca un saculet cu praf inainte sa incerci din nou invocarea.",al={"a esuat Lunaclaw","a pierdut praful lunar","a murit din cauza lui Lunaclaw"}},{q="Sunt moonkin originari din Barrens?",a="Nu. Dupa cum observa Turak Runetotem, moonkin nu sunt originari din Barrens sau Mulgore. Creatura este o aparitie nefireasca pe savana, legata in mod special de riturile Cenarion si de stravechi locuri ale puterii celeste.",al={"moonkin in Barrens","de ce sunt moonkin aici","moonkin din Barrens"}},{q="Cine ofera misiunea Body and Heart?",a="Misiunea este oferita de Turak Runetotem, instructorul senior de druizi aflat la Elder Rise, in Thunder Bluff, dupa intoarcerea initiatului din Moonglade.",al={"cine incepe Body and Heart","cel care da misiunea Body and Heart"}}},fx={["928957c5"]={q="De ce vrea Turak Runetotem sa te infrunti cu Lunaclaw?",a="Turak Runetotem iti este mentor in Thunder Bluff si trebuie sa se asigure ca esti cu adevarat pregatit sa urmezi calea Druid of the Claw. Un druid nu poate primi pur si simplu tainele transformarii in urs; trebuie sa dovedesti ca ai atat taria sufleteasca, cat si forta fizica necesare pentru a stapani puterea bruta a acestei forme. Invocandu-l si invingandu-l pe Lunaclaw, dovedesti ca ai taria de caracter si puterea trupeasca necesare, inainte ca el sa te invete.",al={"motivul lui Turak Runetotem","de ce sa-l inving pe Lunaclaw","motivul testului lui Turak"}},ac0863bb={q="De ce trebuie sa treci singur aceasta incercare, in loc sa trimiti garzi?",a="Acesta este un ritual sacru de initiere, propriu calatoriei tale spirituale ca Druid in devenire. Turak nu poate indeplini ritualul in locul tau, iar bravii din Thunder Bluff nu te-ar putea ajuta, fiindca scopul nu este sa elimini o amenintare, ci sa asimilezi o lectie spirituala. Lunaclaw iti ofera o comuniune a puterii, pe care o poti dobandi doar punandu-ti la incercare propriul echilibru, propria hotarare si propria devotiune in fata paznicului.",al={"de ce eu, Body and Heart","de ce trebuie sa lupt singur cu Lunaclaw","ma pot ajuta gardienii sa infrunt Lunaclaw"}}},fp="14,256,19.461.0,21.507.0,34.205.0,35.199.0,16.218.0,51.201.0,34.205.0,35.155.0"}
P.entries["quest:601"] = {n="Water Elementals",s="In urma descoperirilor legate de Stone of the Tides, Baron Revilgaz cauta o modalitate de a contracara blestemul artefactului. Ii trimite pe aventurieri inapoi pe insula ca sa adune bratari de la elementali ai apei invocati, astfel incat expertii sa le poata examina reziduurile magice.",h="In urma descoperirilor legate de Stone of the Tides, Baron Revilgaz cauta o modalitate de a contracara...",kw={"booty bay","bratari","blestem","dalaran","gazban","revilgaz","stone of the tides","elemental de apa"},sec={{t="Stavilirea blestemului",b="Crezand ca elementalii de apa au fost chemati de vrajitorul goblin Gazban, Baron Revilgaz banuieste ca reziduurile lor magice contin indicii despre cum sa manuiasca Stone of the Tides. Se spune ca piatra blestema pe oricine o poarta, facandu-l sa alunece intre realitate si irealitate. Pentru a gasi o contramasura, Revilgaz te trimite inapoi pe insula din largul coastei sa aduni bratari elementale pe care le-ar putea analiza Mage invatati din Dalaran."},{t="Stapanul din Booty Bay",b="Dupa ce primeste bratarile, Revilgaz recunoaste ca nu are cunostintele de specialitate necesare pentru a stabili daca vreuna ii va fi de folos. In loc sa calatoreasca el insusi la Dalaran - nu va parasi Booty Bay doar ca sa stea de vorba cu niste magi batrani si plictisitori - te trimite spre nord, ca sa le arate un mage."}},faq={{q="Cine doreste bratarii elementale ale apei?",a="Baron Revilgaz, conducatorul Blackwater Raiders din Booty Bay, cere bratarile pentru a investiga magia care inconjoara Stone of the Tides.",al={"cine da misiunea water elementals","misiunea baron revilgaz","cine vrea bratari"}},{q="De ce are Baron Revilgaz nevoie de bratare elementale?",a="Spera ca studierea reziduurilor magice de pe bracere va dezvalui o metoda de a contracara blestemul Stone of the Tides, care il face pe purtatorul sau sa dispara si sa reapara.",al={"de ce sa colectezi bratarile","la ce folosesc bratarile elementalilor de apa","blestemul pietrei mareelor"}},{q="Cine a invocat acesti elementali de apa?",a="Baron Revilgaz crede ca au fost invocate de Gazban, un goblin wizard despre care se spune ca a gasit Stone of the Tides.",al={"cine a chemat elementalii","povestea lui gazban","vrajitor goblin"}},{q="Unde duce aceasta sarcina mai departe?",a="Urmeaza Magical Analysis: Revilgaz trimite bratarile spre nord, la Dalaran, ca un mage sa le examineze reziduurile.",al={"ce urmeaza dupa elementalii apei","misiunea urmatoare","unde se duc bratarile de mana"}},{q="De ce nu duce Revilgaz personal bratarile la Dalaran?",a="Nu are de gand sa plece din Booty Bay doar ca sa stea de vorba cu niste mages batrani si plictisitori si insista ca nu are de ce sa se teama de rivalii care ar putea aparea.",al={"de ce nu pleaca Revilgaz","Revilgaz si Dalaran","de ce ramane in Booty Bay"}}},fp="16,262,17.440.0,18.277.0,38.144.0,47.185.0,36.112.0,31.109.0,57.131.0"}
P.entries["quest:602"] = {n="Magical Analysis",s="Baron Revilgaz te trimite spre nord, din Booty Bay, ca sa ceri sfatul celor din Kirin Tor din Dalaran. Cu un sac de bratari de apa elementala, il cauti pe Archmage Ansirem Runeweaver pentru a descifra blestemul arcan legat de Stone of the Tides.",h="Baron Revilgaz te trimite spre nord, din Booty Bay, ca sa ceri sfatul celor din Kirin Tor din Dalaran.",kw={"ansirem runeweaver","baron revilgaz","booty bay","dalaran","gurubashi empire","analiza magica","stone of the tides","bratari de elemental de apa"},ang={["class:Mage"]="Livrarea de artefacte arcane unui arhimage din Kirin Tor este pe placul magilor, mai ales ca Baron Revilgaz insusi spune ca magii nu pot rezista unei enigme magice."},sec={{t="Un apel catre Dalaran",b="Dupa ce vanezi bratarile elementarilor de apa, Baron Revilgaz iti inmaneaza un manunchi dintre ele. Conducatorul goblin stie ca dezlegarea blestemului din spatele Stone of the Tides necesita o cunoastere a magiei mai profunda decat poate oferi Booty Bay. Te indruma spre nord, catre ruinele Dalaranului, unde vrajitorii sunt inca ocupati cu reconstruirea regatului lor distrus. Convins ca savantii arcani nu pot ignora un mister captivant, Revilgaz iti recomanda sa-l cauti direct pe Archmage Ansirem Runeweaver, cu care a avut de-a face in trecut, fiind un vrajitor priceput."},{t="Cunostintele Archmage-ului",b="Ajungand la Ansirem Runeweaver in toiul eforturilor necontenite din Dalaran, arhimagul ocupat se opreste la auzul relicvei. Cu ani in urma, Runeweaver a scris un tratat savant intreg despre vechile legende ale Gurubashi Empire, dobandind o intelegere rara a trecutului relicvei. Cercetand bratarile, observa urme de reziduuri magice care merita studiate si isi lasa deoparte munca pentru a descoperi ce ascunde vraja."}},faq={{q="Cine te trimite la Dalaran pentru acest studiu?",a="Baron Revilgaz din Booty Bay iti da sacul cu bratare elementale si iti spune sa ceri sfatul vrajitorilor din Dalaran.",al={"cine da Magical Analysis","cel care ofera misiunea Magical Analysis","cine incepe Magical Analysis"}},{q="De ce il alege Baron Revilgaz pe Archmage Ansirem Runeweaver?",a="Revilgaz a mai avut de-a face cu Runeweaver si stie ca arhimageul are cunostinte vaste; are, de asemenea, incredere ca magii nu pot rezista unei enigme magice.",al={"de ce ansirem","legatura dintre revilgaz si ansirem","de ce ansirem runeweaver"}},{q="Ce s-a intamplat inainte de aceasta calatorie la Dalaran?",a="Aceasta insarcinare urmeaza direct dupa Water Elementals, in care ai adunat bratari de elementali ai apei pentru Baron Revilgaz.",al={"misiunea anterioara","conditie prealabila pentru Magical Analysis","ce misiune duce aici"}},{q="Ce urmeaza dupa ce ajungi la archmage?",a="Predarea aparatoarelor duce mai departe la Ansirem's Key.",al={"urmatoarea misiune","ce urmeaza dupa Magical Analysis","dupa predarea bracerelor"}}},fp="16,231,17.569.0,19.405.1,40.119.0,57.143.0,41.113.0,44.51.0"}
P.entries["quest:6027"] = {n="Book of the Ancients",s="Azore Aldamort din turnul Ethel Rethor iti incredinteaza o nestemata. Asezata in mana unei statui-serpente de pe Ranazjar Isle, aceasta il cheama pe protectorul Book of the Ancients, care adaposteste secrete pastrate de naga de secole.",h="Azore Aldamort din turnul Ethel Rethor iti incredinteaza o nestemata.",kw={"azore aldamort","book of the ancients","ethel rethor","gem of the serpent","naga","ranazjar isle","statuia sarpelui"},sec={{t="Statuia sarpelui",b="Dupa Sceptre of Light, Azore Aldamort iti inmaneaza Gem of the Serpent. Pe Ranazjar Isle, o insulita la nord-vest de turnul din Ethel Rethor, se afla o statuie a unui sarpe, iar giuvaierul trebuie pus in mana ei. Astfel va aparea paznicul Book of the Ancients, o carte care pastreaza secretele naga de secole. Azore spera ca aceasta va va invata multe despre dusmanii lor solzosi."}},faq={{q="Cine este Azore Aldamort?",a="Paznicul turnului de la Ethel Rethor, care spera sa afle multe despre naga, pe care Azore ii numeste dusmani solzosi.",al={"azore aldamort","cine da book of the ancients","tipul din turnul din ethel rethor"}},{q="Ce este Book of the Ancients?",a="O carte care contine secretele naga, pastrata vreme de secole. Cineva o pazeste.",al={"ce este Book of the Ancients","legende despre carte","cartea naga din Desolace"}},{q="Unde se afla Ranazjar Isle?",a="O insula mica la nord-vest de turnul Ethel Rethor.",al={"locatia Ranazjar Isle","unde este Ranazjar Isle","unde trebuie sa duc nestemata"}},{q="La ce foloseste Gem of the Serpent?",a="Asezata pe mana Statuii Sarpe de pe Ranazjar Isle, aceasta aduce la viata paznicul Book of the Ancients.",al={"nestemata sarpelui","statuia sarpelui, mana","cum sa invoci gardianul"}},{q="Ce a fost inainte de asta?",a="Sceptre of Light, care preceda aceasta etapa.",al={"misiunea precedenta","lantul Sceptre of Light","conditie prealabila"}}},fp="20,250,18.378.0,22.110.0,33.81.0,23.51.0,35.113.0,22.47.0"}
P.entries["quest:603"] = {n="Ansirem's Key",s="Dupa examinarea sa magica, Archmage Ansirem Runeweaver indica un pumnal stravechi de Troll, capabil sa tulbure altarul focal care da putere Stone of the Tides. Cu mult timp in urma, i l-a dat fiicei sale Catelyn, o fata incapatanata care a plecat de acasa pentru a se alatura piratilor din Booty Bay.",h="Dupa examinarea sa magica, Archmage Ansirem Runeweaver indica un pumnal stravechi de Troll, capabil sa...",kw={"ansirem","booty bay","catelyn","pumnal","runeweaver","stone of the tides","relicva troll"},sec={{t="O fiica ratacita",b="Ansirem Runeweaver stabileste ca un altar sau un punct focal amplifica puterea Stone of the Tides. Pentru a contracara acea magie este nevoie de o alta relicva troll: un pumnal stravechi pe care l-a gasit in timp ce cerceta Stranglethorn. Cu mult timp in urma, i l-a dat fiicei sale Catelyn, o fata incapatanata care a plecat de acasa pentru a se alatura piratilor din Booty Bay."},{t="Un luptator dezarmat",b="Odata ajuns in Booty Bay, afli ca pumnalul nu mai este la soldul lui Catelyn. Candva renumita drept cea mai iscusita luptatoare cu cutitul din asezare, a fost invinsa intr-un duel cu unul dintre Bloodsail Buccaneers. Invingatorul a luat lama troll drept trofeu, lasand-o dezarmata, umilita si batjocorita cu cruzime de ceilalti taietori de gat."}},faq={{q="De ce are Archmage Ansirem nevoie de pumnalul troll?",a="Mage-ul care tine Stone of the Tides ii canalizeaza magia printr-un altar. Ansirem intentioneaza sa intrerupa aceasta amplificare a puterii, coplesind-o, si stie de existenta unui pumnal troll stravechi care ar putea face asta.",al={"de ce am nevoie de un pumnal","scopul cheii lui ansirem","la ce foloseste pumnalul"}},{q="Cine este Catelyn?",a="Catelyn este fiica indrazneata a lui Archmage Ansirem Runeweaver. Si-a lasat tatal in urma ca sa fuga la Booty Bay si sa duca o viata de pirat.",al={"cine este catelyn","fiica lui ansirem","catelyn the blade"}},{q="Unde a gasit Ansirem pumnalul initial?",a="Ansirem a descoperit relicva in timp ce facea cercetari in junglele din Stranglethorn Vale, inainte sa i-o dea fiicei sale.",al={"originea pumnalului","unde a gasit ansirem pumnalul"}},{q="Unde poate fi gasita Catelyn?",a="Locuieste in adapostul piratilor din Booty Bay, la capatul sudic al Stranglethorn Vale.",al={"unde se afla catelyn","locatia lui catelyn"}}},fp="13,282,18.332.0,18.332.1,48.201.0,15.147.0,45.124.0,27.92.0"}
P.entries["quest:604"] = {n="The Bloodsail Buccaneers",s="Fleet Master Seahorn are incredere ca un aliat loial al Blackwater Raiders va ataca asa-zisul post de comanda sudic al Bloodsail Buccaneers, aflat pe Wild Shore. Recuperarea hartilor si a ordinelor scrise va arata exact ce pun la cale piratii.",h="Fleet Master Seahorn are incredere ca un aliat loial al Blackwater Raiders va ataca asa-zisul post de comanda...",kw={"blackwater raiders","bloodsail buccaneers","harti bloodsail","ordinele bloodsail","booty bay","fleet master seahorn","wild shore"},sec={{t="Raiduri pe Wild Shore",b="Dupa ce ai lucrat pentru Crazz, Fleet Master Seahorn remarca loialitatea ta fata de Blackwater Raiders. Bloodsail Buccaneers au infiintat ceea ce numesc un avanpost de comanda sudic pe Wild Shore. Seahorn iti cere sa ataci tabara, sa-i dobori pe spadasinii lor si sa le iei hartile navale si ordinele scrise, ca flota sa le poata afla intentiile."},{t="Dezvaluirea planului flotei",b="Cu hartile si ordinele in mana, Seahorn afla planurile Bloodsail si concluzioneaza ca piratii au ancorat aproape de cap."}},faq={{q="Cine atribuie acest raid?",a="Fleet Master Seahorn iti da aceasta insarcinare in Booty Bay, dupa ce aude de la Crazz laude despre devotamentul tau.",al={"cine ofera misiunea Bloodsail Buccaneers","misiunea lui Seahorn"}},{q="Unde se afla postul de comanda Bloodsail?",a="Buccaneers si-au stabilit tabara de comanda sudica de-a lungul Wild Shore, la sud de Booty Bay, in Stranglethorn Vale.",al={"locatia postului de comanda sudic al Bloodsail","unde se afla Wild Shore"}},{q="Ce obiecte sunt necesare din tabara Bloodsail?",a="Seahorn cere Hartile Bloodsail si ordinele Bloodsail scrise, pentru a descifra intentiile bucanierilor rivali.",al={"ce documente vrea Seahorn","ordinele si hartile Bloodsail"}},{q="De ce vrea Fleet Master Seahorn hartile si ordinele lor?",a="Seahorn vrea sa afle exact ce pun la cale Bloodsail Buccaneers.",al={"de ce sa ataci Wild Shore","ce vrea Seahorn sa afle"}}},fp="24,248,22.372.0,29.133.1,22.112.0,44.118.0,52.124.0,59.69.0"}
P.entries["quest:605"] = {n="Singing Blue Shards",s="Crank Fizzlebub cauta un aventurier intreprinzator care sa adune Singing Crystal Shards de la basiliskii din Stranglethorn Vale. Concurenta cu Venture Company il impiedica sa extraga direct zacamintele minerale, asa ca pieile de basilisk sunt urmatoarea cea mai buna optiune. Promite o parte din castig oricui e dispus sa-i aduca zece exemplare pe masura.",h="Crank Fizzlebub cauta un aventurier intreprinzator care sa adune Singing Crystal Shards de la basiliskii din...",kw={"basilisci","crank fizzlebub","singing blue shards","cristale cantatoare","stranglethorn vale","venture company","zul'kunda"},sec={{t="O oportunitate profitabila",b="Crank Fizzlebub a identificat o piata entuziasta pentru Singing Crystals, specifice tinuturilor Stranglethorn Vale. Din nefericire pentru planurile lui de afaceri, prezenta agresiva a Venture Company ii ingreuneaza culegerea cristalelor brute de pe teren. Pentru a-si ocoli rivalii, Fizzlebub recurge la o metoda alternativa: basiliskii inghit cristalele, ingloband mineralul in pielea lor intarita, ceea ce le permite sa recupereze de la ei fragmente utilizabile."},{t="Vanatoarea de-a lungul coastei",b="Desi orice basilisc din jungla ar putea lasa fragmente de cristal potrivite, Fizzlebub spune ca exemplarele mai blande se gasesc de-a lungul tarmurilor de la sud de Zul'Kunda, in nord. Adunarea a zece cioburi ii permite sa continue afacerile cu cumparatorii sai, dupa care interesele lui comerciale se indreapta spre operatiunile Venture Company."}},faq={{q="De ce vrea Crank Fizzlebub Singing Crystal Shards?",a="Singing Crystals sunt specifice regiunii Stranglethorn Vale si au mare valoare pentru anumiti cumparatori. Crank Fizzlebub spune ca le poate vinde si promite o parte din profit.",al={"de ce sunt importante cristalele cantatoare","scopul lui Crank Fizzlebub","la ce folosesc cristalele cantatoare"}},{q="De ce nu poate Crank Fizzlebub sa recolteze cristalele direct?",a="Fizzlebub da vina pe Venture Company pentru ca ii ingreuneaza strangerea pe cont propriu a cristalelor brute unui negustor cinstit ca el.",al={"de ce sa omori basilisk","problema Venture Company","de ce sa nu extragi cristale"}},{q="De ce au basilisk aceste cristale?",a="Basiliscii din Stranglethorn Vale se hranesc cu cristale, care se integreaza treptat in pielea lor si le confera o piele intarita, pietroasa.",al={"povestea cristalului de basilisc","de ce lasa basiliscii cristale"}},{q="Unde sugereaza Crank Fizzlebub sa caute basilisk?",a="Fizzlebub spune ca orice basilisk poate oferi fragmente, dar exemplarele mai blande traiesc de-a lungul tarmurilor de la sud de Zul'Kunda, in nord.",al={"unde gasesc cioburi","locatia basilisk","basilisk din Zul'Kunda"}},{q="Ce se intampla dupa predarea fragmentelor?",a="Dupa ce primeste zece fragmente, Fizzlebub iti plateste partea de profit promisa si isi indreapta atentia direct catre operatiunile Venture Company.",al={"ce urmeaza dupa singing blue shards","continuarea Singing Blue Shards"}}},fp="19,354,23.463.0,17.321.0,53.163.0,57.121.0,37.142.0,57.118.0,41.159.1"}
P.entries["quest:606"] = {n="Scaring Shaky",s="\"Sea Wolf\" MacKinley nu-i poate suferi pe cei care au datorii la jocurile de noroc, iar multi ii datoreaza bani. Primul este \"Shaky\" Phillipe, de la docurile din Booty Bay, care inca ii datoreaza o suma frumusica de la partida de saptamana trecuta. Planul lui MacKinley e sa-l sperie, folosind maruntaie de Elder Mistvale Gorillas.",h="\"Sea Wolf\" MacKinley nu-i poate suferi pe cei care au datorii la jocurile de noroc, iar multi ii datoreaza...",kw={"booty bay","datorie la jocuri de noroc","maruntaie mistvale","gorile mistvale","scaring shaky","sea wolf mackinley","shaky phillipe","stranglethorn vale"},sec={{t="Recuperarea unei datorii",b="'Sea Wolf' MacKinley nu suporta datoriile la jocuri de noroc ramase neplatite, iar multi ii datoreaza bani. Primul dintre ei este 'Shaky' Phillipe, aflat langa docuri, a carui datorie de la jocul de saptamana trecuta este mare. Ca sa recuperezi banii, trebuie sa-l inspaimanti pe Phillipe. Esti trimis in afara orasului sa vanezi Elder Mistvale Gorillas si sa aduci o gramada zdravana de maruntaie pentru Phillipe. MacKinley vrea sa pastreze secretul ca provin de la un animal, ca Phillipe sa-si imagineze ce e mai rau."},{t="Reactia lui Phillipe",b="Phillipe se stramba la vederea maruntaielor si nu vrea sa afle de unde provin. Apoi Phillipe intreaba daca Sea Wolf te-a trimis."}},faq={{q="Cine este \"Sea Wolf\" MacKinley?",a="Multi ii datoreaza bani din jocuri de noroc lui MacKinley, care vrea ajutor sa-i recupereze, incepand cu \"Shaky\" Phillipe.",al={"cine este mackinley","sea wolf mackinley","cine ofera scaring shaky"}},{q="De ce vrea MacKinley sa-l sperie pe \"Shaky\" Phillipe?",a="Phillipe ii datoreaza lui MacKinley o suma mare din jocul de saptamana trecuta, iar MacKinley crede ca o sperietura il va face sa plateasca.",al={"de ce sa-l sperii pe shaky","datoria lui shaky phillipe","de ce sa-l vizezi pe phillipe"}},{q="Ce creaturi furnizeaza maruntaiele?",a="Elder Mistvale Gorillas, despre care MacKinley spune ca se gasesc in afara orasului.",al={"de unde provin maruntaiele","sursa maruntaielor Mistvale","ce trebuie sa ucid pentru maruntaie"}},{q="Unde poate fi gasit \"Shaky\" Phillipe?",a="Jos, langa docurile din Booty Bay.",al={"unde este shaky phillipe","locatia lui shaky","gaseste-l pe shaky phillipe"}},{q="Ce ar trebui sa-i spui lui Phillipe despre maruntaie?",a="Nimic. MacKinley vrea ca Phillipe sa-si imagineze ce e mai rau, asa ca nu trebuie mentionat ca organele sunt de origine animala.",al={"sa-i spun lui shaky de unde provin giblets"}}},fp="13,261,17.438.0,19.125.1,28.111.0,50.118.0,35.69.0,36.31.0,48.109.0"}
P.entries["quest:6061"] = {n="Taming the Beast",s="Taming the Beast este ritualul de initiere fundamental pentru tinerii vanatori tauren din Bloodhoof Village. Indrumat de instructorul Yaw Sharpmane, vanatorul porneste in Mulgore pentru a imblanzi un strider adult de campie, facand primul pas catre legatura spirituala cu creaturile Mamei-Pamant.",h="Taming the Beast este ritualul de initiere fundamental pentru tinerii vanatori tauren din Bloodhoof Village.",kw={"bloodhoof village","earthmother","misiune de hunter","mulgore","plainstrider","imblanzire","toiag de imblanzire","yaw sharpmane"},ang={["class:Hunter"]="Acest rit marcheaza trecerea de la un cercetas incepator la un adevarat stapan al bestiilor, invatandu-te sa comunici cu animalele prin indrumarea Earthmother.",["race:Tauren"]="Imblanzirea unei bestii este o practica ancestrala, esentiala pentru traditia de vanatoare nomada din Mulgore, care intareste legatura dintre vanator si natura."},sec={{t="O legatura sacra cu salbaticia",b="Pentru tauren, vanatoarea nu a insemnat niciodata doar uciderea fiarelor pentru carne si blanuri. Traditiile stramosesti spun ca invingerea si comuniunea cu vietatile salbatice din Mulgore ii permit vanatorului sa le primeasca spiritul si sa se apropie de Earthmother. Imblanzirea unei fiare insotitoare inalta aceasta legatura, transformand ceea ce putea fi un adversar intr-un tovaras pe viata, aflat in armonie cu echilibrul natural al campiilor."},{t="Prima incercare",b="Yaw Sharpmane isi incepe instruirea novicei nu cu pradatori feroce din varful lantului trofic, ci cu plainstriderii iuti si vigilenti care cutreiera pajistile din Mulgore. Inarmat cu o nuia fermecata de imblanzire, vanatorul trebuie sa infrunte un plainstrider adult, sa-i calmeze instinctele salbatice si sa-i castige increderea. Aceasta prima incercare ii dovedeste hotararea si il pregateste pentru fiarele mai greu de stapanit care urmeaza."}},faq={{q="Care este scopul acestei incercari?",a="Aceasta misiune este prima proba practica pentru tinerii vanatori tauren care vor sa invete arta imblanzirii animalelor. Folosind o vergea de imblanzire pentru a linisti un alergator de campie adult, vanatorul deprinde bazele unei legaturi spirituale si practice cu fiarele.",al={"de ce tamuiesc un plainstrider","scopul misiunii","scopul misiunii cu animal de companie pentru tauren"}},{q="Cine ofera aceasta misiune si unde se afla?",a="Misiunea este oferita de Yaw Sharpmane, instructorul de vanatoare din Bloodhoof Village, in campiile centrale ale Mulgore.",al={"cine ofera misiunea","locatia celui care da misiunea","locatia lui Yaw Sharpmane"}},{q="Pastrez permanent adultul plainstrider?",a="Nu. Bestiile imblanzite in primele trei probe ale lui Yaw Sharpmane sunt doar tovarasi de antrenament temporari. Dupa ce inchei intregul sir de antrenamente si stapanesti imblanzirea bestiilor, poti pleca sa imblanzesti permanent orice companion compatibil.",al={"ramane acest animal de companie permanent","pastrezi Plainstrider-ul","pastrezi animalul dupa misiune"}},{q="De ce considera tauren imblanzirea fiarelor un act spiritual?",a="Traditia Tauren spune ca interactiunea cu fapturile salbatice si infrangerea lor le permit vanatorilor sa le absoarba spiritele si sa devina una cu lumea naturala. Imblanzirea unei bestii reflecta respectul reciproc si unitatea cu creatiile Earthmother.",al={"povestea animalelor de companie ale taurenilor","povestea imblanzirii prin Earthmother","de ce imblanzesc taureni bestii"}},{q="Unde pot fi gasiti plainstriderii adulti?",a="Plainstriderii adulti cutreiera pe intinderi savanele si vaile domoale din jurul Bloodhoof Village, in Mulgore.",al={"unde sunt plainstriderii","locatia plainstriderilor","gaseste un plainstrider adult"}},{q="Ce urmeaza dupa aceasta misiune?",a="Daca ii inapoiezi toiagul de imblanzire lui Yaw Sharpmane, vei trece la urmatoarea incercare, in care trebuie sa imblanzesti un stalker, apoi un swoop agresiv, inainte sa inveti arta dresarii permanente a bestiilor.",al={"ce urmeaza","lantul de misiuni de dupa aceasta","urmatorul pas in imblanzire"}}},fx={fd2667bc={q="De ce vrea Yaw Sharpmane sa imblanzesti un alergator de campie?",a="Yaw Sharpmane te indruma in traditiile sacre ale vanatorului tauren. Pentru tauren, infrangerea si imblanzirea fiarelor salbatice sunt o disciplina spirituala care il apropie pe vanator de Earthmother si il armonizeaza cu lumea naturala. El iti incepe pregatirea cu plainstriderii adulti si iuti din Mulgore, ca sa deprinzi rabdarea si concentrarea spirituala necesare inainte de a lega o legatura cu un companion permanent.",al={"de ce sa imblanzesti un plainstrider","motivul lui Yaw Sharpmane","de ce un plainstrider adult"}},fe0439d7={q="De ce ma pune Yaw Sharpmane sa trec aceasta incercare in loc sa o faca el insusi?",a="Acesta este un rit de trecere personal pe care fiecare vanator aspirant trebuie sa-l parcurga singur. Yaw Sharpmane este un mentor cu experienta, insarcinat sa-i invete pe altii obiceiurile stramosesti, nu sa faca treaba in locul tau. Imblanzirea unei creaturi salbatice cere sa-ti cladesti propria legatura spirituala cu natura si sa te deschizi prezentei Mamei Pamant. Niciun batran sau strajer nu poate crea aceasta legatura in locul tau.",al={"de ce ma trimit","de ce are Yaw Sharpmane nevoie de mine","de ce trebuie sa imblanzesc bestia"}}},fp="16,289,27.405.0,14.390.0,34.268.0,48.125.0,45.233.0,52.239.0,39.118.0,28.198.0"}
P.entries["quest:6062"] = {n="Taming the Beast"}
P.entries["quest:6063"] = {n="Taming the Beast"}
P.entries["quest:6064"] = {n="Taming the Beast",s="Taming the Beast este prima proba din calatoria unui vanator pitic spre stapanirea animalelor de companie din Dun Morogh. Indrumati de Grif Wildheart in Kharanos, tinerii urmaritori invata sa domoleasca un Large Crag Boar feroce si sa se lege de el, folosind o vergea fermecata de imblanzire.",h="Taming the Beast este prima proba din calatoria unui vanator pitic spre stapanirea animalelor de companie din...",kw={"bestie","mistret","mistret de munte","Dun Morogh","Grif Wildheart","Hunter","Kharanos","imblanzire","toiag de imblanzire"},ang={["class:Hunter"]="Aceasta misiune marcheaza pragul hotarator la care un tragator incepator devine un adevarat stapan al fiarelor, incepand seria de incercari care deblocheaza tovarasi animale permanenti.",["race:Dwarf"]="Cercetasii montani din Ironforge venereaza fiarele care pot indura frigul muscator din Dun Morogh; inceperea cu mistretul de stanca robust reflecta pretuirea Dwarf pentru darzenie si rezistenta."},sec={{t="Insotitorul unui vanator",b="Pana acum, vanatorii de munte si cercetasii dwarfi se bazeaza doar pe armele de foc, capcane si instinctele lor de supravietuire in salbaticie. Dar adevaratul suflet al unui Hunter sta in legarea unei prietenii de-o viata cu o bestie salbatica. Grif Wildheart, aflat in fata Thunderbrew Distillery din Kharanos, supravegheaza acest ritual de trecere. In loc sa se astepte ca un novice sa lege pentru totdeauna prima bestie intalnita, Grif ii pune la incercare rabdarea si hotararea cu mai multe specii locale din Dun Morogh."},{t="Mistretul de stanca",b="Prima proba il pune pe urmele unui mistret de stanca mare, unul dintre porcii salbatici, cu piele groasa si rezistenta, care cutreiera poalele inzapezite din Dun Morogh. Acoperite de blana aspra si carne tare, aceste fiare sunt indaratnice si agresive, ceea ce le face o proba initiala ideala pentru vointa. Manuind Taming Rod fermecata primita de la Grif, vanatorul trebuie sa reziste atacului mistretului si sa-i domoleasca furia pana cand acesta se supune poruncilor sale."}},faq={{q="Cine ofera aceasta incercare?",a="Incercarea este oferita de Grif Wildheart, un antrenor de vanatori pitic, cu multa experienta, aflat in afara Thunderbrew Distillery din Kharanos.",al={"cine ofera misiunea","cine incepe Taming the Beast","locatia lui Grif Wildheart"}},{q="De ce trebuie sa imblanzesc mai intai un Large Crag Boar?",a="Mistretii Crag mari sunt rezistenti si incapatanati, dar se gasesc din belsug pe crestele inzapezite din Dun Morogh. Imblanzirea unei astfel de creaturi robuste, cu pielea groasa, este un exercitiu de baza pentru impunerea unei autoritati calme asupra unei fiare agresive.",al={"de ce mistret de stanca","ce fiara trebuie sa imblanzesc","imblanzirea mistretilor"}},{q="Pot sa pastrez acest mistret pentru totdeauna?",a="Nu. Aceasta incercare este doar un exercitiu. Legatura creata cu Taming Rod este temporara si iti da ocazia sa incerci sa comanzi creatura inainte de a returna toiagul si a incerca si alte specii.",al={"mistretul asta ramane permanent","pastrez mistretul de stanca","pot sa pastrez animalul de companie"}},{q="Unde gasesc mistreti mari de stanca?",a="Mistretii Crag Boar de talie mare cutreiera intinderile inzapezite si padurile de pini din jurul Kharanos, precum si pantele inghetate din Dun Morogh.",al={"locatiile mistretilor","unde se gasesc mistreti mari de stanca","locul de aparitie al mistretului mare de stanca"}},{q="Ce urmeaza dupa ce imblanzesti mistretul de stanca?",a="Intoarcerea la Grif Wildheart incheie prima lectie si duce direct la a doua incercare, in care trebuie sa imblanzesti un Snow Leopard.",al={"urmatoarea incercare","ce urmeaza dupa aceasta misiune","urmatoarea misiune din lantul Hunter"}},{q="Cum functioneaza Taming Rod?",a="Taming Rod este o unealta fermecata oferita de instructorii vanatorilor, care ii ajuta pe incepatori sa-si canalizeze vointa si sa domoleasca instinctele salbatice, fara sa aiba nevoie de pregatire magica avansata sau de o viata intreaga de experienta in imblanzirea fiarelor.",al={"povestea vergii de imblanzire","ce este vergia","cum imblanzesc"}}},fx={["49cdd252"]={q="De ce vrea Grif Wildheart sa imblanzesti o bestie?",a="Grif Wildheart te invata bazele meseriei de vanator dwarven adevarat. In ochii lui, a sti cum sa te imprietenesti cu o bestie insotitoare si sa-i dai ordine este la fel de important ca sa-ti intretii arma. In loc sa-ti dea un animal de companie, el crede ca singurul mod potrivit de a invata este experienta directa in salbaticie, unde iti testezi rabdarea si priceperea impotriva diferitelor creaturi locale inainte sa-ti alegi un insotitor permanent.",al={"motivul lui Grif Wildheart","de ce sa imblanzesc o bestie","motivul antrenamentului lui Grif Wildheart"}}},fp="16,251,20.493.0,13.427.0,22.127.0,38.231.0,35.190.0,34.124.0,38.144.0,29.209.0"}
P.entries["quest:6065"] = {n="The Hunter's Path",s="Hunter's Path este o etapa esentiala pentru tinerii vanatori tauren din Mulgore, indrumandu-i spre pregatirea avansata in insotirea bestiilor. Dupa ce mentorii locali se conving ca si-au dovedit indemanarea de baza cu arcul si priceperea in urmarirea prazii, novicii sunt trimisi in Bloodhoof Village sa ceara sfatul instructorului de vanatoare Yaw Sharpmane. Aceasta calatorie da startul probelor spirituale si practice necesare pentru a imblanzi si a lega o relatie cu bestiile salbatice.",h="Hunter's Path este o etapa esentiala pentru tinerii vanatori tauren din Mulgore, indrumandu-i spre pregatirea...",kw={"fiara","bloodhoof village","camp narache","calea vanatorului","mulgore","misiune cu animal de companie","imblanzire","yaw sharpmane"},ang={["class:Hunter"]="Aceasta misiune marcheaza momentul in care un arcas sau un tragator cu pusca devine un adevarat stapan al fiarelor, facand primul pas spre dobandirea unui companion de lupta loial.",["faction:Horde"]="Vanatorii Hoardei se bazeaza in mare masura pe fiarele feroce ale tinuturilor de frontiera, care apara linia intai si cerceteaza salbaticia aspra din Kalimdor.",["race:Tauren"]="Pentru Shu'halo, invatarea imblanzirii fiarelor salbatice este o extensie spirituala a veneratiei lor fata de natura si creatia Earth Mother."},sec={{t="Un ritual de trecere",b="Pentru nomazii Shu'halo, vanatoarea este sacra, nu doar un sport. Un Hunter trebuie sa inteleaga echilibrul naturii, sa cinsteasca spiritele campiilor si sa respecte animalele care sustin triburile. Cand un tanar Hunter isi dovedeste destula pricepere pentru a supravietui in salbaticie si a manuia un arc sau o pusca, batranii recunosc ca este pregatit sa paseasca dincolo de urmarirea solitara. Porunca de a cauta indrumatori cu experienta marcheaza pragul adevaratei maturitati in cultura taurenilor."},{t="Drumul spre Bloodhoof Village",b="Drumul ii poarta pe novici prin intinsele pajisti din Mulgore pana la Bloodhoof Village, o asezare centrala in care se aduna comunitatea, aflata langa Stonebull Lake. Acolo ii asteapta Yaw Sharpmane, un vanator cu experienta, care cunoaste bine firea faunei locale. O discutie cu Sharpmane nu este o simpla formalitate; ea arata ca un vanator este pregatit sa treaca probele solicitante ale imblanzirii fiarelor, invatand sa intre in legatura cu pradatorii, nu doar sa-i vaneze."}},faq={{q="Care este scopul misiunii The Hunter's Path?",a="Misiunea este invitatia oficiala adresata tinerilor vanatori tauren, prin care sunt chemati sa inceapa probele de imblanzire a fiarelor. Il indruma pe vanator catre Bloodhoof Village pentru a vorbi cu Yaw Sharpmane, care supravegheaza ritualurile necesare legarii de un animal insotitor.",al={"de ce primesc aceasta misiune","scopul Hunter's Path","inceputul misiunii de animal de companie pentru Hunter"}},{q="Cine te trimite in aceasta misiune?",a="Misiunea este oferita de instructorii de vanatori tauren, precum Kary Thunderhorn din Thunder Bluff, dupa ce un vanator in devenire a acumulat suficienta experienta si stapaneste elementele de baza ale supravietuirii si tragerii cu arma.",al={"cine ofera calea vanatorului","misiune de la antrenorul de Hunter"}},{q="Cine este Yaw Sharpmane?",a="Yaw Sharpmane este un instructor de vanatori tauren respectat, care locuieste in Bloodhoof Village. I s-a incredintat sarcina de a-i invata pe tinerii vanatori arta periculoasa de a se apropia de fiarele salbatice din Mulgore, de a le calma si de a le imblanzi.",al={"cine este Sharpmane","rolul lui Yaw Sharpmane"}},{q="Ce se intampla dupa finalizarea acestei misiuni?",a="Dupa ce i se prezinta lui Yaw Sharpmane, acesta incepe seria de probe 'Taming the Beast'. In cadrul acestor misiuni, vanatorul trebuie sa se aventureze in salbaticie cu un baston de imblanzire si sa domoleasca mai multe creaturi locale, inainte de a castiga dreptul de a antrena un companion permanent.",al={"ce urmeaza","urmatoarea misiune dupa Calea Vanatorului"}},{q="De ce isi leaga vanatorii Tauren soarta de animale, in loc sa le vaneze pur si simplu?",a="In traditia tauren, fiarele sunt spirite inrudite cu Earth Mother. Un animal legat de vanator nu este un slujitor, ci un tovaras si partener de vanatoare, intruchipand respectul reciproc si supravietuirea impartasita in campii.",al={"legenda animalelor de companie tauren","de ce imblanzesc taurenii animale de companie"}},{q="Pot vanatorii din alte rase accepta aceasta misiune anume?",a="Aceasta versiune a misiunii este conceputa special pentru vanatorii tauren aflati in pregatire in Mulgore. Celelalte rase ale Hordei, precum orcii si trollii, primesc instructiuni de antrenament echivalente, adaptate tinuturilor lor natale din Durotar.",al={"este doar pentru tauren","pot orcii sa urmeze calea vanatorului tauren"}}},fx={a380c02c={q="De ce te trimite instructorul tau la Yaw Sharpmane?",a="Instructorul tau recunoaste ca ai acumulat destula experienta in salbaticie pentru a face urmatorul pas crucial din viata unui hunter: sa legi o legatura cu un animal insotitor si sa-l dresezi. Te trimite la Yaw Sharpmane, in Bloodhoof Village, fiindca el detine cunostintele specializate si traditiile stravechi necesare pentru a te indruma prin incercarile de imblanzire a fiarelor.",al={"de ce sa-l vad pe yaw sharpmane","motivul antrenorului pentru hunters path","de ce sa ma trimita in bloodhoof village"}}},fp="17,421,17.483.0,29.455.0,41.243.0,28.203.0,21.207.0,41.250.0,68.203.0,52.228.0"}
P.entries["quest:6068"] = {n="The Hunter's Path"}
P.entries["quest:607"] = {n="Return to MacKinley",s="Dupa sperietura cu maruntaiele, \"Shaky\" Phillipe iti da o punguta pe care sa i-o duci lui \"Sea Wolf\" MacKinley. Phillipe jura ca datoria trebuia oricum platita si adauga ca nu e nevoie sa fii brutal.",h="Dupa sperietura cu maruntaiele, \"Shaky\" Phillipe iti da o punguta pe care sa i-o duci lui \"Sea Wolf\"...",kw={"datorie","mackinley","lupul de mare","shaky phillipe","stranglethorn vale"},sec={{t="Rugamintea lui Shaky",b="Phillipe iti pune in mana o punga cu plata pentru Sea Wolf. Vrea sa-i spui lui MacKinley ca datoria urma sa fie oricum platita si jura ca asa e. Pune totul pe seama faptului ca s-a ametit putin si s-a ratacit, spune ca MacKinley va intelege si ca nu e nevoie sa recurga la violenta."},{t="Sea Wolf asculta povestea",b="MacKinley rade si te intreaba cat de tare s-a cutremurat Phillipe cand i-ai aratat maruntaiele. Adauga ca Phillipe e atat de usor de citit, incat, daca joci carti impotriva lui Phillipe, castigi fara efort."}},faq={{q="Cine iti da punga?",a="\"Shaky\" Phillipe iti da punga cu plata pentru Sea Wolf MacKinley.",al={"cine ofera Return to MacKinley","de unde incep Return to MacKinley"}},{q="Ce scuza da Phillipe pentru a nu plati?",a="Phillipe pune totul pe seama faptului ca s-a imbatat putin si s-a ratacit si jura ca oricum avea de gand sa-si plateasca datoria.",al={"de ce n-a platit Shaky","scuza lui Phillipe","de ce a intarziat Shaky, Phillipe"}},{q="Ce a fost inainte de acest pas?",a="Urmeaza dupa Scaring Shaky, unde MacKinley te-a pus sa-l sperii pe Phillipe cu maruntaie.",al={"ce vine inainte de Return to MacKinley","misiunea anterioara"}}},fp="19,198,12.292.0,23.191.1,24.71.0,46.118.0,27.83.0"}
P.entries["quest:6074"] = {n="The Hunter's Path"}
P.entries["quest:608"] = {n="The Bloodsail Buccaneers",s="In timp ce Bloodsail Buccaneers pregatesc un atac, Fleet Master Seahorn decide sa nu-si mobilizeze intreaga flota pentru o contraofensiva. In schimb, trimite un echipaj de aventurieri sa se strecoare in locul de debarcare si sa elimine conducatorii de seama ai buccaneers inainte ca atacul lor sa poata incepe.",h="In timp ce Bloodsail Buccaneers pregatesc un atac, Fleet Master Seahorn decide sa nu-si mobilizeze intreaga...",kw={"blackwater","bloodsail","booty bay","firallon","keelhaul","pirati","seahorn","stillwater"},sec={{t="Decimarea flotei de pirati",b="Dupa ce a aflat planurile de invazie ale bucanierilor, Fleet Master Seahorn refuza sa astepte pana cand dusmanul isi va pregati atacul. Luand in deradere priceperea nautica a lui Fleet Master Firallon, Seahorn intentioneaza sa neutralizeze rapid amenintarea, eliminandu-i comandantii. In loc sa riste o confruntare navala in toata regula, trimite o echipa de atac direct in tabara de debarcare a lui Firallon, pentru a-i ucide pe Firallon, Captain Stillwater si Captain Keelhaul, asigurandu-se ca forta bucanierilor se destrama fara conducatori."}},faq={{q="Cine ordona atacul asupra conducerii Bloodsail?",a="Fleet Master Seahorn din Booty Bay conduce atacul si vrea sa distruga flota ostila inainte ca aceasta sa poata ataca.",al={"cine ofera misiunea Bloodsail Buccaneers","cel care da misiunea Bloodsail Buccaneers","cine te trimite dupa Firallon"}},{q="Care comandanti bucanieri trebuie eliminati?",a="Tinta sunt Fleet Master Firallon, Captain Stillwater si Captain Keelhaul, care conduc fortele Bloodsail.",al={"tinte pentru bloodsail buccaneers","comandanti bloodsail de ucis","cine sunt capii bloodsail"}},{q="De ce trimite Fleet Master Seahorn aventurieri in locul corabiilor sale?",a="Seahorn considera ca un grup de aventurieri priceput poate lovi tabara de debarcare si asasina ofiterii inamici, provocand prabusirea flotei inamice fara sa-si riste propriile nave.",al={"de ce trimitem aventurieri la firallon","de ce nu trimitem blackwater fleet","planul lui seahorn"}},{q="In ce context mai larg se inscrie aceasta confruntare cu Bloodsail Buccaneers?",a="Aceasta confruntare urmeaza descoperirii planurilor scrise de atac ale buccaneerilor, in primele etape ale investigatiei Bloodsail din Stranglethorn Vale.",al={"misiunea Bloodsail anterioara","ce misiune preceda aceasta","ordinea lantului Bloodsail"}}},fp="24,281,29.478.0,50.116.0,49.111.0,68.179.0,85.156.0"}
